/* Alpha Academy Cambodia — Khmer Conversational Mastery: lesson bank
   ---------------------------------------------------------------------------
   100 real-life situations in 10 chapters, by Ngorn Kakteka. Read by
   assets/js/kcm.js.

   Per situation:  n, ch (chapter index), title, titleKm, goal, scene,
   dialogue [{who, note?, kh, ro, en}], sayit?, phrases [{en, kh, ro}],
   tips [{label, html, culture}].

   `kh` is plain Khmer text. `ro`, `en`, `goal`, `scene`, `sayit` and tip
   `html` may carry inline <b>, <em>, <span class="kh"> and <span class="ro">
   only — <b> inside romanization marks the stressed syllable.
   A dialogue turn whose `who` is "You" is the learner's line: role-play
   mode hides exactly those.                                                */
window.KCM = {"chapters": [{"en": "Greetings & Everyday Basics","km": "ការស្វាគមន៍ និងមូលដ្ឋានគ្រឹះ"},{"en": "Getting Around","km": "ការធ្វើដំណើរ"},{"en": "Food & Drink","km": "ម្ហូបអាហារ និងភេសជ្ជៈ"},{"en": "Shopping & Money","km": "ការទិញទំនិញ និងលុយកាក់"},{"en": "Accommodation & Home","km": "កន្លែងស្នាក់នៅ និងផ្ទះសម្បែង"},{"en": "Health & Emergencies","km": "សុខភាព និងគ្រាអាសន្ន"},{"en": "Work, Business & Study","km": "ការងារ អាជីវកម្ម និងការសិក្សា"},{"en": "Social Life & Relationships","km": "ជីវិតសង្គម និងទំនាក់ទំនង"},{"en": "Travel, Culture & Leisure","km": "ទេសចរណ៍ វប្បធម៌ និងកម្សាន្ត"},{"en": "Daily Life & Admin","km": "ជីវិតប្រចាំថ្ងៃ និងរដ្ឋបាល"}],"key": [{"sym": "a","exp": "as in <em>but</em> — short"},{"sym": "aa","exp": "as in <em>father</em> — long"},{"sym": "i","exp": "as in <em>sit</em>"},{"sym": "ii / ee","exp": "as in <em>see</em>"},{"sym": "u","exp": "as in <em>put</em>"},{"sym": "oo","exp": "as in <em>food</em>"},{"sym": "ei","exp": "as in <em>day</em>"},{"sym": "ae","exp": "as in <em>cat</em>, stretched"},{"sym": "ao","exp": "as in <em>now</em>, shortened"},{"sym": "oe","exp": "as in <em>her</em> (no <em>r</em>)"},{"sym": "uo","exp": "glide <em>oo → uh</em>"},{"sym": "ie","exp": "glide <em>ee → uh</em>"},{"sym": "kh","exp": "puffed <em>k</em> — never as in <em>loch</em>"},{"sym": "ph","exp": "puffed <em>p</em> — never <em>f</em>"},{"sym": "th","exp": "puffed <em>t</em> — never as in <em>the</em>"},{"sym": "ng","exp": "as in <em>singer</em> — can begin a word"},{"sym": "ny","exp": "as in <em>canyon</em>"},{"sym": "r","exp": "a light tap, often softened"}],"sits": [
{"n": 1,"title": "Saying Hello & Goodbye","titleKm": "ការស្វាគមន៍ និងការលា","scene": "You walk into a small Phnom Penh coffee shop for the first time. The owner looks up from the counter.","dialogue": [{"who": "Owner","kh": "ជម្រាបសួរ!","ro": "chom-<b>RIEP</b> suor!","en": "Hello! <em>(formal)</em>"},{"who": "You","kh": "ជម្រាបសួរ បាទ។ សុខសប្បាយជាទេ?","ro": "chom-<b>RIEP</b> suor baat. sok sa-<b>BAY</b> chie tei?","en": "Hello. How are you?"},{"who": "Owner","kh": "សុខសប្បាយ អរគុណ។ ចុះលោកវិញ?","ro": "sok sa-<b>BAY</b>, or-<b>KUN</b>. choh lowk vinh?","en": "I’m well, thank you. And you?"},{"who": "You","kh": "ខ្ញុំក៏សុខសប្បាយដែរ។","ro": "khnyom kâ sok sa-<b>BAY</b> dae.","en": "I’m fine too."},{"who": "You","note": "(leaving)","kh": "អរគុណច្រើន។ ជួបគ្នាថ្ងៃក្រោយ!","ro": "or-<b>KUN</b> chraen. chuop knie thngai <b>KRAOY</b>!","en": "Thank you. See you next time!"}],"sayit": "<span class=\"kh\">ជម្រាបសួរ</span> is <b>three</b> syllables, not four: <span class=\"ro\">chom · riep · suor</span>, with the weight on <span class=\"ro\">RIEP</span>. The final <em>r</em> is barely there — closer to <em>“sua”</em> than <em>“sewer”</em>.","phrases": [{"en": "Hello <em>(formal, safe anywhere)</em>","kh": "ជម្រាបសួរ","ro": "chom-<b>riep</b> suor"},{"en": "Hi <em>(casual, friends)</em>","kh": "សួស្តី","ro": "suor-<b>sdei</b>"},{"en": "Good morning","kh": "អរុណសួស្តី","ro": "a-run suor-<b>sdei</b>"},{"en": "Goodbye <em>(everyday)</em>","kh": "លាហើយ","ro": "lie <b>haoy</b>"},{"en": "Goodbye <em>(formal)</em>","kh": "ជម្រាបលា","ro": "chom-<b>riep</b> lie"},{"en": "See you next time","kh": "ជួបគ្នាថ្ងៃក្រោយ","ro": "chuop knie thngai <b>kraoy</b>"},{"en": "See you tomorrow","kh": "ជួបគ្នាថ្ងៃស្អែក","ro": "chuop knie thngai <b>sa-aek</b>"},{"en": "Yes / polite “sir” <em>(male speaker)</em>","kh": "បាទ","ro": "<b>baat</b>"},{"en": "Yes / polite “ma’am” <em>(female speaker)</em>","kh": "ចាស","ro": "<b>chaa</b>"},{"en": "Thank you","kh": "អរគុណ","ro": "or-<b>kun</b>"}],"tips": [{"label": "The Sampeah","html": "Pair <span class=\"kh\">ជម្រាបសួរ</span> with the <b>sampeah</b> — palms together at the chest, a small bow. The <b>higher your hands, the more respect</b> you show: chest for peers, mouth for elders and teachers, nose-bridge for monks and officials. A foreigner who returns a sampeah correctly is remembered warmly for it. And note the gender split: men end sentences with <span class=\"ro\">baat</span>, women with <span class=\"ro\">chaa</span>. Using the wrong one is the fastest way to get a friendly laugh.","culture": true}],"goal": "You can greet a stranger politely, ask how they are, answer, and leave — using the correct male/female politeness particle throughout.","ch": 0},
{"n": 2,"title": "How Are You?","titleKm": "សុខទុក្ខ និងការសួរនាំ","scene": "You bump into a neighbour you haven’t seen in weeks — an exchange that is short, warm, and almost always ends with a question about food.","dialogue": [{"who": "Neighbour","kh": "អូ! យូរហើយមិនបានជួបគ្នា។","ro": "ouh! <b>YOO</b> haoy min baan chuop knie.","en": "Oh! Long time no see."},{"who": "You","kh": "មែនហើយ! សុខសប្បាយជាទេ?","ro": "maen haoy! sok sa-<b>BAY</b> chie tei?","en": "That’s right! How are you?"},{"who": "Neighbour","kh": "ធម្មតាទេ តែរវល់ណាស់។ ចុះបងវិញ?","ro": "thoam-ma-<b>DAA</b> tei, tae ro-<b>VOL</b> nas. choh bong vinh?","en": "So-so, but very busy. And you?"},{"who": "Neighbour","kh": "ញ៉ាំបាយហើយនៅ?","ro": "nyam bai haoy <b>nov</b>?","en": "Have you eaten yet?"},{"who": "You","kh": "ញ៉ាំហើយ បាទ។ អរគុណ។","ro": "<b>NYAM</b> haoy, baat. or-kun.","en": "I’ve eaten already, thanks."}],"sayit": "The question tag <span class=\"kh\">…ទេ?</span> <span class=\"ro\">(tei?)</span> turns almost any statement into a yes/no question, and it <b>rises only slightly</b> — Khmer does not swing the pitch the way English does. Over-lifting the end of <span class=\"ro\">sok sa-BAY chie tei?</span> makes it sound anxious rather than friendly.","phrases": [{"en": "How are you?","kh": "សុខសប្បាយជាទេ?","ro": "sok sa-<b>bay</b> chie tei?"},{"en": "I’m fine, thank you.","kh": "ខ្ញុំសុខសប្បាយ អរគុណ។","ro": "khnyom sok sa-<b>bay</b>, or-kun"},{"en": "So-so / normal.","kh": "ធម្មតាទេ","ro": "thoam-ma-<b>daa</b> tei"},{"en": "I’m not feeling well.","kh": "ខ្ញុំមិនសូវស្រួលខ្លួនទេ","ro": "khnyom min sao <b>sruol</b> kluon tei"},{"en": "I’m very tired.","kh": "ខ្ញុំនឿយហត់ណាស់","ro": "khnyom nuey-<b>hot</b> nas"},{"en": "And you?","kh": "ចុះអ្នកវិញ?","ro": "choh neak <b>vinh</b>?"},{"en": "Long time no see.","kh": "យូរហើយមិនបានជួបគ្នា","ro": "<b>yoo</b> haoy min baan chuop knie"},{"en": "Have you eaten yet?","kh": "ញ៉ាំបាយហើយនៅ?","ro": "nyam bai haoy <b>nov</b>?"},{"en": "Yes, I’ve eaten already.","kh": "ញ៉ាំហើយ","ro": "<b>nyam</b> haoy"},{"en": "Not yet.","kh": "នៅទេ","ro": "<b>nov</b> tei"},{"en": "Take care of yourself.","kh": "ថែរក្សាខ្លួនផង","ro": "thae-rak-<b>saa</b> kluon phong"}],"tips": [{"label": "“Have You Eaten?”","html": "<span class=\"kh\">ញ៉ាំបាយហើយនៅ?</span> <span class=\"ro\">(nyam bai haoy nov?)</span> is <b>not really about food</b> — it is Cambodia’s everyday “How’s it going?”, rooted in generations for whom a full stomach was the truest measure of well-being. Answer <span class=\"ro\">nyam haoy</span> (“already eaten”) unless you actually want lunch — <span class=\"ro\">nov tei</span> (“not yet”) is often taken as accepting an invitation you didn’t know you’d received.","culture": false}],"goal": "You can say how you feel — well, tired, busy, unwell — bounce the question back, and handle Cambodia’s real greeting: “Have you eaten yet?”","ch": 0},
{"n": 3,"title": "Introducing Yourself","titleKm": "ការណែនាំខ្លួន","scene": "A friend brings you to a family gathering, and everyone turns to look.","dialogue": [{"who": "Sophea","kh": "តើអ្នកឈ្មោះអ្វី?","ro": "tae neak <b>chhmuoh</b> a-vei?","en": "What is your name?"},{"who": "You","kh": "ខ្ញុំឈ្មោះ ដេវីត។ រីករាយដែលបានស្គាល់អ្នក។","ro": "khnyom <b>chhmuoh</b> David. rik-<b>RIEY</b> dael baan skoal neak.","en": "My name is David. Nice to meet you."},{"who": "Sophea","kh": "តើអ្នកមកពីប្រទេសណា?","ro": "tae neak mok pii bra-<b>TEIH</b> naa?","en": "Which country are you from?"},{"who": "You","kh": "ខ្ញុំមកពីប្រទេសអង់គ្លេស។","ro": "khnyom mok pii bra-<b>TEIH</b> ong-<b>GLEIH</b>.","en": "I’m from England."},{"who": "Sophea","kh": "តើអ្នកធ្វើការអ្វី?","ro": "tae neak thveu <b>KAA</b> a-vei?","en": "What work do you do?"},{"who": "You","kh": "ខ្ញុំជាគ្រូបង្រៀន។ សូមនិយាយយឺតៗ។","ro": "khnyom chie kruu bong-<b>RIEN</b>. som ni-yiey <b>YOEUT</b>-yoeut.","en": "I’m a teacher. Please speak slowly."}],"sayit": "<span class=\"kh\">ខ្ញុំ</span> <span class=\"ro\">(khnyom, “I”)</span> is <b>one syllable</b> — never “ker-nyom”. In fast speech it shortens to <span class=\"ro\">nyom</span>, or drops out entirely.","phrases": [{"en": "What is your name?","kh": "តើអ្នកឈ្មោះអ្វី?","ro": "tae neak <b>chhmuoh</b> a-vei?"},{"en": "My name is …","kh": "ខ្ញុំឈ្មោះ …","ro": "khnyom <b>chhmuoh</b> …"},{"en": "Nice to meet you.","kh": "រីករាយដែលបានស្គាល់អ្នក","ro": "rik-<b>riey</b> dael baan skoal neak"},{"en": "Where are you from?","kh": "តើអ្នកមកពីណា?","ro": "tae neak mok pii <b>naa</b>?"},{"en": "I’m from …","kh": "ខ្ញុំមកពី …","ro": "khnyom mok <b>pii</b> …"},{"en": "What work do you do?","kh": "តើអ្នកធ្វើការអ្វី?","ro": "tae neak thveu <b>kaa</b> a-vei?"},{"en": "I work as a …","kh": "ខ្ញុំធ្វើការជា …","ro": "khnyom thveu kaa <b>chie</b> …"},{"en": "I am … years old.","kh": "ខ្ញុំមានអាយុ … ឆ្នាំ","ro": "khnyom mien <b>aa-yuk</b> … chhnam"},{"en": "I’m learning Khmer.","kh": "ខ្ញុំកំពុងរៀនភាសាខ្មែរ","ro": "khnyom kom-pung <b>rien</b> phie-saa khmae"},{"en": "I speak only a little.","kh": "ខ្ញុំនិយាយបានតិចតួច","ro": "khnyom ni-yiey baan tech-<b>tuoch</b>"}],"tips": [{"label": "Age Decides the Pronoun","html": "Khmer has no neutral “you”. Before speaking, guess the person’s age relative to yours: <span class=\"ro\">bong</span> <span class=\"kh\">(បង)</span> for someone slightly older, <span class=\"ro\">p’oun</span> <span class=\"kh\">(ប្អូន)</span> for someone younger, <span class=\"ro\">lowk / lowk srei</span> <span class=\"kh\">(លោក / លោកស្រី)</span> for formal or senior, and <span class=\"ro\">om</span> <span class=\"kh\">(ឪ​ម)</span> for your parents’ generation. <b>Calling an older person <span class=\"ro\">bong</span> is always safe;</b> calling them <span class=\"ro\">p’oun</span> is not. Also expect your family name first — the author of this book, <em>Ngorn Kakteka</em>, is addressed as <em>Kakteka</em>.","culture": true}],"goal": "You can give your name, country, job and level of Khmer, ask the same in return, and choose the right pronoun for the person in front of you.","ch": 0},
{"n": 4,"title": "Asking Someone’s Name","titleKm": "ការសួរឈ្មោះ","scene": "You have met this person twice now and still cannot remember what to call them. Ask — nobody minds.","dialogue": [{"who": "You","kh": "សូមទោស ខ្ញុំភ្លេចឈ្មោះអ្នក។","ro": "som <b>TOH</b>, khnyom phlech chhmuoh neak.","en": "Sorry, I’ve forgotten your name."},{"who": "Dara","kh": "អត់អីទេ។ ខ្ញុំឈ្មោះ សុខ ដារា។","ro": "ot ei <b>TEI</b>. khnyom chhmuoh Sok Dara.","en": "No problem. My name is Sok Dara."},{"who": "You","kh": "តើខ្ញុំគួរហៅអ្នកយ៉ាងម៉េច?","ro": "tae khnyom kuor hav neak yang <b>MECH</b>?","en": "What should I call you?"},{"who": "Dara","kh": "ហៅខ្ញុំថា បងដារា បានហើយ។","ro": "hav khnyom thaa <b>BONG</b> Dara baan haoy.","en": "Just call me Bong Dara."},{"who": "You","kh": "តើសរសេរយ៉ាងម៉េច?","ro": "tae sor-<b>SEI</b> yang mech?","en": "How do you write it?"}],"sayit": "<span class=\"kh\">ភ្លេច</span> <span class=\"ro\">(phlech)</span> starts with a <b>puffed p</b>, not an <em>f</em>. English speakers reach for “flech” — the mouth position is closer to <em>“p-lech”</em> said quickly.","phrases": [{"en": "What should I call you?","kh": "តើខ្ញុំគួរហៅអ្នកយ៉ាងម៉េច?","ro": "tae khnyom kuor hav neak yang <b>mech</b>?"},{"en": "Do you have a nickname?","kh": "តើអ្នកមានឈ្មោះហៅក្រៅទេ?","ro": "tae neak mien chhmuoh hav <b>krav</b> tei?"},{"en": "My nickname is …","kh": "ឈ្មោះហៅក្រៅខ្ញុំគឺ …","ro": "chhmuoh hav krav khnyom <b>keu</b> …"},{"en": "Sorry, I forgot your name.","kh": "សូមទោស ខ្ញុំភ្លេចឈ្មោះអ្នក","ro": "som toh, khnyom <b>phlech</b> chhmuoh neak"},{"en": "Please say it again.","kh": "សូមនិយាយម្ដងទៀត","ro": "som ni-yiey <b>mdong</b> tiet"},{"en": "How do you write it?","kh": "តើសរសេរយ៉ាងម៉េច?","ro": "tae sor-<b>sei</b> yang mech?"},{"en": "No problem.","kh": "អត់អីទេ","ro": "ot ei <b>tei</b>"},{"en": "This is my friend, …","kh": "នេះជាមិត្តភក្តិខ្ញុំ …","ro": "nih chie mit-<b>phak</b> khnyom …"}],"tips": [{"label": "Everyone Has Two Names","html": "The name on the ID card is often <b>not</b> the name anyone uses. Most Cambodians go by a one-syllable nickname given in childhood — <span class=\"ro\">Ti, Srey, Bong, Nak</span> — and colleagues of twenty years may never learn the formal one. Ask for the <span class=\"kh\">ឈ្មោះហៅក្រៅ</span> <span class=\"ro\">(chhmuoh hav krav)</span> and use it. Attach <span class=\"ro\">bong</span> or <span class=\"ro\">p’oun</span> in front and you sound like a local, not a form.","culture": true}],"goal": "You have met this person twice now and still cannot remember what to call them. Ask — nobody minds.","ch": 0},
{"n": 5,"title": "Please, Thank You & Sorry","titleKm": "សូម អរគុណ និងសូមទោស","scene": "Three words carry more goodwill than any amount of vocabulary. Here they are in one exchange.","dialogue": [{"who": "You","kh": "សូមទោស! ជួយខ្ញុំបន្តិចផង។","ro": "som <b>TOH</b>! chuoy khnyom bon-tech phong.","en": "Excuse me! Please help me a moment."},{"who": "Woman","kh": "បាទ មានរឿងអ្វី?","ro": "baat, mien <b>ROEUNG</b> a-vei?","en": "Yes, what’s the matter?"},{"who": "You","kh": "សូមប្រាប់ផ្លូវទៅផ្សារ។","ro": "som <b>BRAB</b> phlov teuv phsaa.","en": "Please tell me the way to the market."},{"who": "You","kh": "អរគុណច្រើន!","ro": "or-<b>KUN</b> chraen!","en": "Thank you very much!"},{"who": "Woman","kh": "មិនអីទេ។ អញ្ជើញ។","ro": "min ei <b>TEI</b>. an-choeun.","en": "It’s nothing. Go ahead."}],"sayit": "<span class=\"kh\">សូម</span> <span class=\"ro\">(som)</span> rhymes with English <em>“some”</em> and goes <b>in front</b> of the verb, never at the end: <span class=\"ro\">som brab</span>, not “brab som”.","phrases": [{"en": "Please … <em>(before a verb)</em>","kh": "សូម …","ro": "<b>som</b> …"},{"en": "Thank you","kh": "អរគុណ","ro": "or-<b>kun</b>"},{"en": "Thank you very much","kh": "អរគុណច្រើន","ro": "or-<b>kun</b> chraen"},{"en": "Sorry / excuse me","kh": "សូមទោស","ro": "som <b>toh</b>"},{"en": "It’s nothing / never mind","kh": "មិនអីទេ","ro": "min ei <b>tei</b>"},{"en": "Please help me.","kh": "ជួយខ្ញុំផង","ro": "<b>chuoy</b> khnyom phong"},{"en": "No need, thank you.","kh": "មិនបាច់ទេ អរគុណ","ro": "min <b>bach</b> tei, or-kun"},{"en": "Please, go ahead. <em>(inviting)</em>","kh": "អញ្ជើញ","ro": "an-<b>choeun</b>"}],"tips": [{"label": "There Is No “You’re Welcome”","html": "Khmer has no single reply to thanks. Cambodians answer with <span class=\"kh\">អត់អីទេ</span> <span class=\"ro\">(ot ei tei)</span> or <span class=\"kh\">មិនអីទេ</span> <span class=\"ro\">(min ei tei)</span> — both meaning “it’s nothing”. And <span class=\"kh\">សូមទោស</span> does double duty: it is your apology <em>and</em> your “excuse me” for squeezing past someone in a crowded market. Say it with a small dip of the head and it never sounds abrupt.","culture": false}],"goal": "Three words carry more goodwill than any amount of vocabulary. Here they are in one exchange.","ch": 0},
{"n": 6,"title": "Yes, No & “I Don’t Understand”","titleKm": "បាទ ទេ និងខ្ញុំមិនយល់","scene": "Someone is speaking to you at full speed. These five sentences buy you time without ending the conversation.","dialogue": [{"who": "Man","kh": "តើអ្នកយល់ទេ?","ro": "tae neak <b>YUL</b> tei?","en": "Do you understand?"},{"who": "You","kh": "អត់ទេ ខ្ញុំមិនយល់ទេ។","ro": "ot <b>TEI</b>, khnyom min <b>YUL</b> tei.","en": "No, I don’t understand."},{"who": "You","kh": "តើវាមានន័យថាម៉េច?","ro": "tae vie mien <b>NEY</b> thaa mech?","en": "What does it mean?"},{"who": "Man","kh": "មានន័យថា «ថ្ងៃស្អែក»។","ro": "mien <b>NEY</b> thaa “thngai sa-aek”.","en": "It means “tomorrow”."},{"who": "You","kh": "អា! ខ្ញុំយល់ហើយ។ អរគុណ។","ro": "aa! khnyom <b>YUL</b> haoy. or-kun.","en": "Ah! Now I understand. Thanks."}],"sayit": "The negative is a <b>sandwich</b>: <span class=\"ro\">min</span> … <span class=\"ro\">tei</span> wraps around the verb. <span class=\"kh\">ខ្ញុំមិនយល់ទេ</span> is literally “I not understand no”. Drop the final <span class=\"ro\">tei</span> and it sounds unfinished.","phrases": [{"en": "Yes <em>(male / female)</em>","kh": "បាទ / ចាស","ro": "<b>baat</b> / <b>chaa</b>"},{"en": "No / not","kh": "ទេ / អត់ទេ","ro": "<b>tei</b> / ot <b>tei</b>"},{"en": "I understand.","kh": "ខ្ញុំយល់ហើយ","ro": "khnyom <b>yul</b> haoy"},{"en": "I don’t understand.","kh": "ខ្ញុំមិនយល់ទេ","ro": "khnyom min <b>yul</b> tei"},{"en": "What does it mean?","kh": "មានន័យថាម៉េច?","ro": "mien <b>ney</b> thaa mech?"},{"en": "I don’t know.","kh": "ខ្ញុំមិនដឹងទេ","ro": "khnyom min <b>deung</b> tei"},{"en": "That’s not right.","kh": "មិនមែនទេ","ro": "min <b>maen</b> tei"},{"en": "Correct / that’s right.","kh": "ត្រូវហើយ","ro": "<b>trov</b> haoy"}],"tips": [{"label": "“Yes” Often Means “I’m Listening”","html": "A Cambodian nodding <span class=\"ro\">baat, baat, baat</span> through your explanation is telling you <b>they can hear you</b> — not that they agree, and not that they understood. Direct refusal is felt as harsh, so a genuine “no” usually arrives dressed as <span class=\"ro\">“maybe”</span>, <span class=\"ro\">“a bit difficult”</span>, or a smile and silence. When something matters, ask the person to tell you the plan back in their own words.","culture": true}],"goal": "Someone is speaking to you at full speed. These five sentences buy you time without ending the conversation.","ch": 0},
{"n": 7,"title": "Repeat & Speak Slowly","titleKm": "សូមនិយាយម្ដងទៀត","scene": "The most valuable page in this book. Learn these before anything else — they keep every other conversation alive.","dialogue": [{"who": "Seller","kh": "មួយគីឡូបីពាន់រៀល។","ro": "muoy ki-<b>LOU</b> bei poan riel.","en": "Three thousand riel a kilo."},{"who": "You","kh": "សូមទោស សូមនិយាយយឺតៗ។","ro": "som toh, som ni-yiey <b>YOEUT</b>-yoeut.","en": "Sorry, please speak slowly."},{"who": "Seller","kh": "បី... ពាន់... រៀល។","ro": "bei … <b>POAN</b> … riel.","en": "Three … thousand … riel."},{"who": "You","kh": "សូមសរសេរឲ្យខ្ញុំផង។","ro": "som sor-sei <b>AOY</b> khnyom phong.","en": "Please write it for me."},{"who": "You","kh": "ឥឡូវខ្ញុំយល់ហើយ។ អរគុណ។","ro": "eu-<b>LOV</b> khnyom yul haoy. or-kun.","en": "Now I understand. Thank you."}],"sayit": "Doubling a word softens or stretches it. <span class=\"kh\">យឺតៗ</span> <span class=\"ro\">(yoeut-yoeut)</span> is “slowly, slowly”; the little mark <span class=\"kh\">ៗ</span> means “say it twice”. You will see it everywhere.","phrases": [{"en": "Please speak slowly.","kh": "សូមនិយាយយឺតៗ","ro": "som ni-yiey <b>yoeut</b>-yoeut"},{"en": "Please say it again.","kh": "សូមនិយាយម្ដងទៀត","ro": "som ni-yiey <b>mdong</b> tiet"},{"en": "Please speak louder.","kh": "សូមនិយាយឮៗ","ro": "som ni-yiey <b>lu</b>-lu"},{"en": "I didn’t hear you.","kh": "ខ្ញុំមិនបានឮទេ","ro": "khnyom min baan <b>lu</b> tei"},{"en": "Please write it for me.","kh": "សូមសរសេរឲ្យខ្ញុំផង","ro": "som sor-sei <b>aoy</b> khnyom phong"},{"en": "How do you say … in Khmer?","kh": "… ជាភាសាខ្មែរនិយាយយ៉ាងម៉េច?","ro": "… chie phie-saa khmae ni-yiey yang <b>mech</b>?"},{"en": "What is this called?","kh": "តើនេះហៅថាអ្វី?","ro": "tae nih hav thaa <b>a-vei</b>?"},{"en": "Do you speak English?","kh": "តើអ្នកនិយាយអង់គ្លេសបានទេ?","ro": "tae neak ni-yiey ong-<b>gleih</b> baan tei?"}],"tips": [{"label": "Ask for the Pen","html": "Cambodian numbers are the hardest thing on this page to hear at speed, and <b>every price in the country is negotiable in writing</b>. Carrying a small notebook — or handing over your phone’s calculator — turns a failed exchange into a friendly one in two seconds. Sellers do this with each other constantly; it is not a foreigner’s crutch, it is normal practice.","culture": false}],"goal": "The most valuable page in this book. Learn these before anything else — they keep every other conversation alive.","ch": 0},
{"n": 8,"title": "Where Are You From?","titleKm": "តើអ្នកមកពីណា?","scene": "Within thirty seconds of meeting you, someone will ask this. Have the whole answer ready.","dialogue": [{"who": "Driver","kh": "តើអ្នកមកពីប្រទេសណា?","ro": "tae neak mok pii bra-<b>TEIH</b> naa?","en": "Which country are you from?"},{"who": "You","kh": "ខ្ញុំមកពីប្រទេសអូស្ត្រាលី។","ro": "khnyom mok pii bra-<b>TEIH</b> ou-straa-lii.","en": "I’m from Australia."},{"who": "Driver","kh": "តើអ្នកនៅកម្ពុជាបានប៉ុន្មានហើយ?","ro": "tae neak nov kam-pu-chie baan <b>PON</b>-man haoy?","en": "How long have you been in Cambodia?"},{"who": "You","kh": "បានពីរឆ្នាំហើយ។","ro": "baan <b>PII</b> chhnam haoy.","en": "Two years now."},{"who": "You","kh": "ខ្ញុំចូលចិត្តកម្ពុជាណាស់។","ro": "khnyom chol-<b>CHET</b> kam-pu-chie nas.","en": "I like Cambodia very much."}],"sayit": "The country’s own name is <span class=\"kh\">កម្ពុជា</span> <span class=\"ro\">(kam-pu-chie)</span> — four beats, stress light throughout. “Cambodia” is the English exonym; using the Khmer one always earns a smile.","phrases": [{"en": "Which country are you from?","kh": "តើអ្នកមកពីប្រទេសណា?","ro": "tae neak mok pii bra-<b>teih</b> naa?"},{"en": "America / England","kh": "អាមេរិក / អង់គ្លេស","ro": "aa-mei-<b>rik</b> / ong-<b>gleih</b>"},{"en": "France / Australia","kh": "បារាំង / អូស្ត្រាលី","ro": "baa-<b>rang</b> / ou-straa-<b>lii</b>"},{"en": "Japan / China","kh": "ជប៉ុន / ចិន","ro": "chie-<b>pon</b> / <b>chen</b>"},{"en": "How long have you been here?","kh": "តើអ្នកនៅទីនេះបានប៉ុន្មានហើយ?","ro": "tae neak nov ti-nih baan <b>pon</b>-man haoy?"},{"en": "It’s my first time.","kh": "ជាលើកទីមួយ","ro": "chie leuk ti <b>muoy</b>"},{"en": "I like Cambodia very much.","kh": "ខ្ញុំចូលចិត្តកម្ពុជាណាស់","ro": "khnyom chol-<b>chet</b> kam-pu-chie nas"},{"en": "I live here now.","kh": "ឥឡូវខ្ញុំរស់នៅទីនេះ","ro": "eu-<b>lov</b> khnyom ruoh nov ti-nih"}],"tips": [{"label": "The Questions That Follow","html": "Expect the next three questions to be your <b>age, marital status and salary</b> — in that order, from someone you met four minutes ago. This is not nosiness. Age settles which pronoun to use, and the rest is ordinary friendly accounting. A vague answer is perfectly acceptable: <span class=\"kh\">ចាំមួយភ្លែត</span> <span class=\"ro\">(cham muoy phlet — “hang on a second”)</span> and a laugh closes the subject with no offence taken.","culture": true}],"goal": "Within thirty seconds of meeting you, someone will ask this. Have the whole answer ready.","ch": 0},
{"n": 9,"title": "Talking About the Weather","titleKm": "និយាយអំពីអាកាសធាតុ","scene": "Cambodia has two seasons and one universal complaint. Both are excellent conversation starters.","dialogue": [{"who": "Neighbour","kh": "ថ្ងៃនេះក្ដៅណាស់!","ro": "thngai nih <b>KDAV</b> nas!","en": "It’s so hot today!"},{"who": "You","kh": "មែនហើយ ក្ដៅពេក។","ro": "maen haoy, <b>KDAV</b> peik.","en": "Yes, too hot."},{"who": "Neighbour","kh": "ល្ងាចនេះប្រហែលភ្លៀងធ្លាក់។","ro": "lngiech nih bra-<b>HAEL</b> pleang thleak.","en": "It will probably rain this evening."},{"who": "You","kh": "រដូវវស្សាមកដល់ហើយ។","ro": "ro-<b>DOV</b> voa-saa mok dol haoy.","en": "The rainy season has arrived."},{"who": "You","kh": "ខ្ញុំចូលចិត្តរដូវត្រជាក់ជាង។","ro": "khnyom chol-chet ro-dov tro-<b>CHEAK</b> chieng.","en": "I prefer the cool season."}],"sayit": "<span class=\"kh\">ក្ដៅ</span> <span class=\"ro\">(kdav)</span> is one syllable — the <em>k</em> and <em>d</em> are pressed together with no vowel between them. Khmer is full of these clusters; resist the urge to insert “kuh-dav”.","phrases": [{"en": "It’s very hot.","kh": "ក្ដៅណាស់","ro": "<b>kdav</b> nas"},{"en": "It’s cool / cold.","kh": "ត្រជាក់","ro": "tro-<b>cheak</b>"},{"en": "It’s raining.","kh": "ភ្លៀងធ្លាក់","ro": "<b>pleang</b> thleak"},{"en": "It’s very windy.","kh": "ខ្យល់បក់ខ្លាំង","ro": "khyol bok <b>khlang</b>"},{"en": "The rainy season","kh": "រដូវវស្សា","ro": "ro-<b>dov</b> voa-saa"},{"en": "The dry season","kh": "រដូវប្រាំង","ro": "ro-<b>dov</b> prang"},{"en": "Will it rain tomorrow?","kh": "ថ្ងៃស្អែកភ្លៀងទេ?","ro": "thngai sa-aek <b>pleang</b> tei?"},{"en": "The weather is nice today.","kh": "ថ្ងៃនេះអាកាសធាតុល្អ","ro": "thngai nih aa-kaah-thie-tuk <b>la-or</b>"}],"tips": [{"label": "Complaining Is Bonding","html": "Grumbling about the heat is a <b>social ritual</b>, not a conversation about meteorology. A well-timed <span class=\"kh\">ក្ដៅណាស់!</span> to a stranger waiting out a downpour with you will get a laugh and often a chair. Note also that Cambodians divide the year into <em>hot</em>, <em>rainy</em> and a brief, treasured <em>cool</em> season around December — mention preferring the cool one and you will get instant agreement.","culture": false}],"goal": "Cambodia has two seasons and one universal complaint. Both are excellent conversation starters.","ch": 0},
{"n": 10,"title": "Numbers & Telling Time","titleKm": "លេខ និងម៉ោង","scene": "Numbers unlock prices, addresses and appointments. Learn one to ten today; the rest is arithmetic.","dialogue": [{"who": "You","kh": "ឥឡូវម៉ោងប៉ុន្មានហើយ?","ro": "eu-lov <b>MAONG</b> pon-man haoy?","en": "What time is it now?"},{"who": "Friend","kh": "ម៉ោងបួនកន្លះរសៀល។","ro": "<b>MAONG</b> buon kon-lah ro-siel.","en": "Half past four in the afternoon."},{"who": "You","kh": "តើយើងជួបគ្នាម៉ោងប៉ុន្មាន?","ro": "tae yeung chuop knie <b>MAONG</b> pon-man?","en": "What time shall we meet?"},{"who": "Friend","kh": "ម៉ោងប្រាំពីរល្ងាច បានទេ?","ro": "maong <b>PRAM</b>-pil lngiech, baan tei?","en": "Seven in the evening, alright?"},{"who": "You","kh": "បាទ បានហើយ។ ជួបគ្នាថ្ងៃស្អែក។","ro": "baat, <b>BAAN</b> haoy. chuop knie thngai sa-aek.","en": "Yes, that works. See you tomorrow."}],"sayit": "Khmer counts to five, then <b>adds</b>: six is <span class=\"ro\">pram-muoy</span> (5+1), seven <span class=\"ro\">pram-pil</span> (5+2), up to nine. Hear <span class=\"ro\">pram-</span> and you already know the number is between six and nine.","phrases": [{"en": "1 · 2 · 3 · 4 · 5","kh": "មួយ ពីរ បី បួន ប្រាំ","ro": "muoy · pii · bei · buon · <b>pram</b>"},{"en": "6 · 7 · 8 · 9 · 10","kh": "ប្រាំមួយ ប្រាំពីរ ប្រាំបី ប្រាំបួន ដប់","ro": "pram-muoy … pram-buon · <b>dop</b>"},{"en": "20 · 100 · 1,000","kh": "ម្ភៃ · មួយរយ · មួយពាន់","ro": "<b>mphey</b> · muoy <b>roy</b> · muoy <b>poan</b>"},{"en": "What time is it?","kh": "ម៉ោងប៉ុន្មានហើយ?","ro": "<b>maong</b> pon-man haoy?"},{"en": "Half past …","kh": "ម៉ោង … កន្លះ","ro": "maong … <b>kon-lah</b>"},{"en": "Morning / afternoon","kh": "ព្រឹក / រសៀល","ro": "<b>pruk</b> / ro-<b>siel</b>"},{"en": "Evening / night","kh": "ល្ងាច / យប់","ro": "<b>lngiech</b> / <b>yub</b>"},{"en": "Today / tomorrow / yesterday","kh": "ថ្ងៃនេះ / ថ្ងៃស្អែក / ម្សិលមិញ","ro": "thngai nih / thngai <b>sa-aek</b> / msel-<b>minh</b>"}],"tips": [{"label": "Read the Price Tags","html": "Khmer has its own numerals — <span class=\"kh\">១ ២ ៣ ៤ ៥ ៦ ៧ ៨ ៩ ០</span> — and they appear on market price tags, bus tickets, house numbers and government forms, often <b>instead of</b> Western digits. Ten minutes spent memorising the shapes will save you a hundred confused transactions. Note that <span class=\"kh\">៥</span> (5) and <span class=\"kh\">៨</span> (8) are the two most commonly misread by beginners.","culture": false}],"goal": "Numbers unlock prices, addresses and appointments. Learn one to ten today; the rest is arithmetic.","ch": 0},
{"n": 11,"title": "Hailing a Tuk-Tuk","titleKm": "ការហៅតុកតុក","scene": "A driver calls out to you from the kerb. Answering in Khmer changes the price before you have even sat down.","dialogue": [{"who": "Driver","kh": "តុកតុកទេ លោក? ទៅណា?","ro": "tuk-tuk tei, lowk? teuv <b>NAA</b>?","en": "Tuk-tuk, sir? Where to?"},{"who": "You","kh": "ទៅផ្សារធំថ្មី បានទេ?","ro": "teuv phsaa thom <b>THMEI</b>, baan tei?","en": "To the Central Market, is that okay?"},{"who": "Driver","kh": "បាទ បាន។ អញ្ជើញឡើង។","ro": "baat, <b>BAAN</b>. an-choeun laeung.","en": "Yes, fine. Please get in."},{"who": "You","kh": "ចាំបន្តិច តម្លៃប៉ុន្មាន?","ro": "cham bon-tech, tom-<b>LAI</b> pon-man?","en": "Hold on — how much is it?"},{"who": "Driver","kh": "បីដុល្លារ បាទ។","ro": "bei dol-<b>LAA</b>, baat.","en": "Three dollars."}],"sayit": "Settle the price <b>before</b> you climb in — <span class=\"ro\">cham bon-tech</span> (“hold on a second”) is the phrase that buys you that moment, and every Cambodian passenger uses it.","phrases": [{"en": "Where are you going?","kh": "ទៅណា?","ro": "teuv <b>naa</b>?"},{"en": "I want to go to …","kh": "ខ្ញុំចង់ទៅ …","ro": "khnyom chong <b>teuv</b> …"},{"en": "Can you take me to …?","kh": "ទៅ … បានទេ?","ro": "teuv … <b>baan</b> tei?"},{"en": "How much is it?","kh": "តម្លៃប៉ុន្មាន?","ro": "tom-<b>lai</b> pon-man?"},{"en": "Hold on a second.","kh": "ចាំបន្តិច","ro": "<b>cham</b> bon-tech"},{"en": "Motorbike taxi","kh": "ម៉ូតូឌុប","ro": "moto-<b>dup</b>"},{"en": "Are you free? <em>(available)</em>","kh": "ទំនេរទេ?","ro": "tum-<b>nei</b> tei?"},{"en": "No thanks, I’ll walk.","kh": "អត់ទេ ខ្ញុំដើរ","ro": "ot tei, khnyom <b>daeu</b>"}],"tips": [{"label": "Tuk-Tuk, Remork, Moto","html": "What tourists call a tuk-tuk, Cambodians usually call a <span class=\"kh\">រ៉ឺម៉ក</span> <span class=\"ro\">(rermok)</span> — a carriage towed behind a motorbike. The small Indian-style auto-rickshaws that arrived with the ride apps are the true <span class=\"ro\">tuk-tuk</span>, and they are cheaper. A <span class=\"ro\">moto-dup</span> — you riding pillion on a motorbike — is cheapest and fastest of all, and is how most of Phnom Penh actually moves.","culture": true}],"goal": "A driver calls out to you from the kerb. Answering in Khmer changes the price before you have even sat down.","ch": 1},
{"n": 12,"title": "Negotiating the Fare","titleKm": "ការតថ្លៃឡាន","scene": "The first price is an opening offer, not an insult. Smile, halve it, and meet in the middle.","dialogue": [{"who": "Driver","kh": "ប្រាំដុល្លារ។","ro": "<b>PRAM</b> dol-laa.","en": "Five dollars."},{"who": "You","kh": "ថ្លៃពេក! បញ្ចុះតម្លៃបានទេ?","ro": "<b>THLAI</b> peik! banh-choh tom-lai baan tei?","en": "Too expensive! Can you lower it?"},{"who": "You","kh": "បីដុល្លារ បានទេ?","ro": "bei dol-<b>LAA</b>, baan tei?","en": "Three dollars, alright?"},{"who": "Driver","kh": "បួនដុល្លារ ចុងក្រោយ។","ro": "buon dol-laa, chong-<b>KRAOY</b>.","en": "Four dollars, final."},{"who": "You","kh": "អញ្ចឹងបានហើយ។ ទៅ!","ro": "an-<b>CHOENG</b> baan haoy. teuv!","en": "Alright then. Let’s go!"}],"sayit": "<span class=\"kh\">ថ្លៃ</span> <span class=\"ro\">(thlai)</span> means <em>expensive</em>; <span class=\"kh\">តម្លៃ</span> <span class=\"ro\">(tom-lai)</span> means <em>price</em>. One syllable apart, and mixing them up is the most common bargaining slip.","phrases": [{"en": "Too expensive!","kh": "ថ្លៃពេក!","ro": "<b>thlai</b> peik!"},{"en": "Can you lower the price?","kh": "បញ្ចុះតម្លៃបានទេ?","ro": "banh-choh tom-<b>lai</b> baan tei?"},{"en": "Three dollars, okay?","kh": "បីដុល្លារ បានទេ?","ro": "bei dol-<b>laa</b>, baan tei?"},{"en": "That’s the final price.","kh": "តម្លៃចុងក្រោយ","ro": "tom-lai chong-<b>kraoy</b>"},{"en": "Alright then.","kh": "អញ្ចឹងបានហើយ","ro": "an-<b>choeng</b> baan haoy"},{"en": "Wait for me, please.","kh": "សូមចាំខ្ញុំផង","ro": "som <b>cham</b> khnyom phong"},{"en": "Return trip too","kh": "ទៅមកវិញផង","ro": "teuv mok <b>vinh</b> phong"},{"en": "I’ll pay when we arrive.","kh": "ដល់ហើយទើបបង់លុយ","ro": "dol haoy teub bong <b>luy</b>"}],"tips": [{"label": "The Round-Trip Discount","html": "The strongest card you hold is not haggling — it is <b>volume</b>. Asking a driver to wait and bring you back (<span class=\"ro\">teuv mok vinh phong</span>) often costs barely more than the one-way fare, because he keeps the fare instead of hunting a new passenger. Do this twice with the same driver and you have a regular: save his number, and you will never negotiate again.","culture": false}],"goal": "The first price is an opening offer, not an insult. Smile, halve it, and meet in the middle.","ch": 1},
{"n": 13,"title": "Directing the Driver","titleKm": "ការប្រាប់ផ្លូវអ្នកបើកបរ","scene": "Cambodian addresses are unreliable; landmarks are everything. Six words of direction will get you home.","dialogue": [{"who": "You","kh": "សូមទៅត្រង់។","ro": "som teuv <b>TRONG</b>.","en": "Please go straight."},{"who": "You","kh": "បត់ឆ្វេងនៅចំណុចនោះ។","ro": "bot <b>CHVENG</b> nov chom-noch nuh.","en": "Turn left at that corner."},{"who": "Driver","kh": "ក្រោយវត្តមែនទេ?","ro": "kraoy <b>VOAT</b> maen tei?","en": "Behind the pagoda, right?"},{"who": "You","kh": "បាទ ត្រូវហើយ។ បន្តិចទៀត។","ro": "baat, <b>TROV</b> haoy. bon-tech tiet.","en": "Yes, correct. A little further."},{"who": "You","kh": "ឈប់ទីនេះ! ដល់ហើយ។","ro": "<b>CHHUP</b> ti-nih! dol haoy.","en": "Stop here! We’ve arrived."}],"sayit": "<span class=\"kh\">ឆ្វេង</span> <span class=\"ro\">(chveng, left)</span> and <span class=\"kh\">ស្ដាំ</span> <span class=\"ro\">(sdam, right)</span> are worth over-learning. Point with your whole hand as you say them — pointing with one finger is impolite here.","phrases": [{"en": "Go straight.","kh": "ទៅត្រង់","ro": "teuv <b>trong</b>"},{"en": "Turn left / turn right","kh": "បត់ឆ្វេង / បត់ស្ដាំ","ro": "bot <b>chveng</b> / bot <b>sdam</b>"},{"en": "Stop here!","kh": "ឈប់ទីនេះ!","ro": "<b>chhup</b> ti-nih!"},{"en": "A little further","kh": "បន្តិចទៀត","ro": "bon-<b>tech</b> tiet"},{"en": "Slow down, please.","kh": "សូមបើកយឺតៗ","ro": "som baeuk <b>yoeut</b>-yoeut"},{"en": "Near / far","kh": "ជិត / ឆ្ងាយ","ro": "<b>chit</b> / <b>chhngay</b>"},{"en": "Behind the pagoda","kh": "ក្រោយវត្ត","ro": "kraoy <b>voat</b>"},{"en": "We’ve arrived.","kh": "ដល់ហើយ","ro": "<b>dol</b> haoy"}],"tips": [{"label": "Navigate by Landmark","html": "Street numbers exist in Phnom Penh but almost nobody navigates by them, and outside the capital they barely exist at all. Cambodians steer by <b>landmarks</b>: <span class=\"kh\">វត្ត</span> <span class=\"ro\">(voat, pagoda)</span>, <span class=\"kh\">ផ្សារ</span> <span class=\"ro\">(phsaa, market)</span>, a petrol station, a well-known hotel. Learn the three landmarks nearest your home and you will never be lost again — “behind the pagoda” beats any address.","culture": true}],"goal": "Cambodian addresses are unreliable; landmarks are everything. Six words of direction will get you home.","ch": 1},
{"n": 14,"title": "Using a Ride App","titleKm": "ការប្រើកម្មវិធីហៅឡាន","scene": "The app has set the price, but the driver still calls you. Here is that thirty-second phone conversation.","dialogue": [{"who": "Driver","kh": "ហាឡូ! លោកនៅឯណា?","ro": "haa-<b>LOU</b>! lowk nov ae-naa?","en": "Hello! Where are you?"},{"who": "You","kh": "ខ្ញុំនៅមុខសណ្ឋាគារ។","ro": "khnyom nov <b>MUK</b> son-thaa-kie.","en": "I’m in front of the hotel."},{"who": "Driver","kh": "ចាំបួនប្រាំនាទី។","ro": "cham buon pram <b>NIE</b>-ti.","en": "Wait four or five minutes."},{"who": "You","kh": "បាទ។ ខ្ញុំពាក់អាវក្រហម។","ro": "baat. khnyom peak aav <b>KRO-HOM</b>.","en": "Okay. I’m wearing a red shirt."},{"who": "You","kh": "ខ្ញុំបង់តាមកម្មវិធី។","ro": "khnyom bong taam kam-ma-vi-<b>THII</b>.","en": "I’m paying through the app."}],"sayit": "On the phone, lead with <b>where you are standing</b>, not your name. <span class=\"ro\">khnyom nov muk …</span> (“I’m in front of …”) is the single most useful sentence in this whole situation.","phrases": [{"en": "Where are you?","kh": "នៅឯណា?","ro": "nov <b>ae-naa</b>?"},{"en": "I’m in front of …","kh": "ខ្ញុំនៅមុខ …","ro": "khnyom nov <b>muk</b> …"},{"en": "I’m waiting here.","kh": "ខ្ញុំចាំនៅទីនេះ","ro": "khnyom <b>cham</b> nov ti-nih"},{"en": "How many minutes?","kh": "ប៉ុន្មាននាទី?","ro": "pon-man <b>nie</b>-ti?"},{"en": "I’m wearing a red shirt.","kh": "ខ្ញុំពាក់អាវក្រហម","ro": "khnyom peak aav <b>kro-hom</b>"},{"en": "I’ll pay by app.","kh": "ខ្ញុំបង់តាមកម្មវិធី","ro": "khnyom bong taam kam-ma-vi-<b>thii</b>"},{"en": "Please cancel it.","kh": "សូមលុបចោល","ro": "som <b>lup</b> chaol"},{"en": "I’ve arrived, I see you.","kh": "ខ្ញុំឃើញលោកហើយ","ro": "khnyom <b>kheunh</b> lowk haoy"}],"tips": [{"label": "The App Price Is the Real Price","html": "Apps such as PassApp, Grab and TADA fix the fare in advance, which quietly ends the whole negotiation game — and they are usually <b>cheaper than a street tuk-tuk</b> for a foreigner. Keep your phone in Khmer-friendly mode: drivers will phone rather than message, and they will speak fast. The four phrases above cover ninety per cent of those calls.","culture": false}],"goal": "The app has set the price, but the driver still calls you. Here is that thirty-second phone conversation.","ch": 1},
{"n": 15,"title": "Renting a Motorbike","titleKm": "ការជួលម៉ូតូ","scene": "Renting is easy; the paperwork and the fuel are where foreigners get caught. Ask all four questions.","dialogue": [{"who": "You","kh": "ខ្ញុំចង់ជួលម៉ូតូមួយ។","ro": "khnyom chong <b>CHUOL</b> moto muoy.","en": "I’d like to rent a motorbike."},{"who": "Owner","kh": "មួយថ្ងៃប្រាំដុល្លារ។","ro": "muoy thngai <b>PRAM</b> dol-laa.","en": "Five dollars a day."},{"who": "You","kh": "មួយខែថ្លៃប៉ុន្មាន?","ro": "muoy <b>KHAE</b> thlai pon-man?","en": "How much for a month?"},{"who": "You","kh": "មានមួកសុវត្ថិភាពទេ?","ro": "mien muok so-vat-thi-<b>PHIEP</b> tei?","en": "Is there a helmet?"},{"who": "Owner","kh": "មាន។ សូមទុកលិខិតឆ្លងដែន។","ro": "<b>MIEN</b>. som tuk li-khet chhlong-daen.","en": "Yes. Please leave your passport."}],"sayit": "<span class=\"kh\">ជួល</span> <span class=\"ro\">(chuol)</span> covers both <em>rent</em> and <em>hire</em>. Say <span class=\"ro\">chuol muoy khae</span> — “rent one month” — and the daily rate usually drops by half.","phrases": [{"en": "I want to rent a motorbike.","kh": "ខ្ញុំចង់ជួលម៉ូតូ","ro": "khnyom chong <b>chuol</b> moto"},{"en": "How much per day / month?","kh": "មួយថ្ងៃ / មួយខែ ថ្លៃប៉ុន្មាន?","ro": "muoy thngai / muoy <b>khae</b> thlai pon-man?"},{"en": "Is there a helmet?","kh": "មានមួកសុវត្ថិភាពទេ?","ro": "mien muok so-vat-thi-<b>phiep</b> tei?"},{"en": "Passport","kh": "លិខិតឆ្លងដែន","ro": "li-khet <b>chhlong</b>-daen"},{"en": "Where do I buy petrol?","kh": "ទិញសាំងនៅឯណា?","ro": "tinh <b>sang</b> nov ae-naa?"},{"en": "It’s broken down.","kh": "វាខូចហើយ","ro": "vie <b>khouch</b> haoy"},{"en": "Flat tyre","kh": "កង់បែក","ro": "kong <b>baek</b>"},{"en": "I’ll return it tomorrow.","kh": "ខ្ញុំសងវិញថ្ងៃស្អែក","ro": "khnyom <b>song</b> vinh thngai sa-aek"}],"tips": [{"label": "Never Leave Your Passport","html": "Many rental shops ask for your passport as security. <b>Offer a photocopy plus a deposit instead</b> — reputable shops accept this, and recovering a held passport during a dispute is genuinely difficult. Photograph the bike from all four sides before you ride off, scratches included, and check that the shop provides a helmet: police fine riders without one, and foreigners are stopped far more often.","culture": false}],"goal": "Renting is easy; the paperwork and the fuel are where foreigners get caught. Ask all four questions.","ch": 1},
{"n": 16,"title": "At the Bus Station","titleKm": "នៅស្ថានីយ៍ឡាន","scene": "Buying an intercity ticket. Know the departure time, the seat and whether it stops where you think.","dialogue": [{"who": "You","kh": "សុំសំបុត្រទៅសៀមរាបមួយ។","ro": "som <b>SOM-BOT</b> teuv siem-riep muoy.","en": "One ticket to Siem Reap, please."},{"who": "Clerk","kh": "ចេញម៉ោងប្រាំបីព្រឹក។","ro": "chenh maong <b>PRAM</b>-bei pruk.","en": "It leaves at eight in the morning."},{"who": "You","kh": "ធ្វើដំណើរប៉ុន្មានម៉ោង?","ro": "thveu dom-<b>NAEU</b> pon-man maong?","en": "How many hours is the journey?"},{"who": "Clerk","kh": "ប្រាំមួយម៉ោង។ ដប់ពីរដុល្លារ។","ro": "<b>PRAM</b>-muoy maong. dop-pii dol-laa.","en": "Six hours. Twelve dollars."},{"who": "You","kh": "សុំកៅអីជាប់បង្អួច។","ro": "som kav-ei <b>CHOAB</b> bong-uoch.","en": "A window seat, please."}],"sayit": "<span class=\"kh\">ចេញ</span> <span class=\"ro\">(chenh)</span> means <em>to leave / depart</em> and <span class=\"kh\">ដល់</span> <span class=\"ro\">(dol)</span> means <em>to arrive</em>. Two words that answer nearly every travel question you will ever ask.","phrases": [{"en": "One ticket to …","kh": "សុំសំបុត្រទៅ … មួយ","ro": "som <b>som-bot</b> teuv … muoy"},{"en": "What time does it leave?","kh": "ចេញម៉ោងប៉ុន្មាន?","ro": "<b>chenh</b> maong pon-man?"},{"en": "What time does it arrive?","kh": "ដល់ម៉ោងប៉ុន្មាន?","ro": "<b>dol</b> maong pon-man?"},{"en": "How many hours?","kh": "ប៉ុន្មានម៉ោង?","ro": "pon-man <b>maong</b>?"},{"en": "A window seat, please.","kh": "សុំកៅអីជាប់បង្អួច","ro": "som kav-ei <b>choab</b> bong-uoch"},{"en": "Is it air-conditioned?","kh": "មានម៉ាស៊ីនត្រជាក់ទេ?","ro": "mien maa-sin tro-<b>cheak</b> tei?"},{"en": "Which platform / where?","kh": "ចេញនៅឯណា?","ro": "chenh nov <b>ae-naa</b>?"},{"en": "Round trip","kh": "ទៅមកវិញ","ro": "teuv <b>mok</b> vinh"}],"tips": [{"label": "Buy the Day Before","html": "Popular routes — Phnom Penh to Siem Reap, Sihanoukville, Battambang — sell out on weekends and vanish entirely around <b>Khmer New Year and Pchum Ben</b>, when the whole country travels home at once. Buy a day ahead, arrive thirty minutes early, and keep your ticket visible: seats are assigned but rarely enforced, and the polite passenger who shows up last stands.","culture": false}],"goal": "Buying an intercity ticket. Know the departure time, the seat and whether it stops where you think.","ch": 1},
{"n": 17,"title": "On a Long-Distance Bus","titleKm": "នៅលើឡានក្រុង","scene": "Six hours, one rest stop, and a seat that may already have someone in it. Sort it out politely.","dialogue": [{"who": "You","kh": "សូមទោស នេះកៅអីខ្ញុំ។","ro": "som toh, nih <b>KAV-EI</b> khnyom.","en": "Excuse me, this is my seat."},{"who": "Passenger","kh": "អូ សូមទោស! ខ្ញុំប្ដូរ។","ro": "ouh, som <b>TOH</b>! khnyom bdo.","en": "Oh, sorry! I’ll move."},{"who": "You","kh": "តើឈប់សម្រាកនៅឯណា?","ro": "tae chhup som-<b>RAAK</b> nov ae-naa?","en": "Where do we stop for a break?"},{"who": "Driver","kh": "ឈប់កម្ពង់ធំ សាមសិបនាទី។","ro": "chhup kom-pong-<b>THOM</b>, saam-sep nie-ti.","en": "We stop at Kampong Thom, thirty minutes."},{"who": "You","kh": "សូមប្រាប់ខ្ញុំពេលដល់។","ro": "som <b>BRAB</b> khnyom peil dol.","en": "Please tell me when we arrive."}],"sayit": "<span class=\"kh\">សូមប្រាប់ខ្ញុំពេលដល់</span> <span class=\"ro\">(som brab khnyom peil dol)</span> — “tell me when we arrive” — is worth memorising whole. Say it to the driver’s assistant, not the driver, and you will be woken at the right town.","phrases": [{"en": "This is my seat.","kh": "នេះកៅអីខ្ញុំ","ro": "nih <b>kav-ei</b> khnyom"},{"en": "Where do we stop?","kh": "ឈប់សម្រាកនៅឯណា?","ro": "chhup som-<b>raak</b> nov ae-naa?"},{"en": "How long is the stop?","kh": "ឈប់ប៉ុន្មាននាទី?","ro": "chhup pon-man <b>nie</b>-ti?"},{"en": "Please tell me when we arrive.","kh": "សូមប្រាប់ខ្ញុំពេលដល់","ro": "som <b>brab</b> khnyom peil dol"},{"en": "Where is the toilet?","kh": "បង្គន់នៅឯណា?","ro": "bong-<b>kon</b> nov ae-naa?"},{"en": "I feel carsick.","kh": "ខ្ញុំវិលមុខ","ro": "khnyom <b>vil</b> muk"},{"en": "Could you close the curtain?","kh": "ជួយបិទវាំងននផង","ro": "chuoy <b>bet</b> veang-non phong"},{"en": "My bag is underneath.","kh": "កាបូបខ្ញុំនៅខាងក្រោម","ro": "kaa-<b>boub</b> khnyom nov khang-kraom"}],"tips": [{"label": "The Assistant Runs the Bus","html": "Every intercity bus has a young assistant who loads luggage, collects tickets and shouts the stops. <b>He is the person to ask</b>, not the driver. Learn his job title — <span class=\"kh\">ជំនួយការ</span> <span class=\"ro\">(chum-nuoy-kaa)</span> — or simply catch his eye with <span class=\"ro\">bong</span>. Tell him your destination when you board and he will make sure you are off the bus at the right place.","culture": false}],"goal": "Six hours, one rest stop, and a seat that may already have someone in it. Sort it out politely.","ch": 1},
{"n": 18,"title": "Ferries & Boats","titleKm": "ទូក និងសាឡាង","scene": "Crossing the Mekong, or heading out to an island. Ask about the life jackets — politely, but ask.","dialogue": [{"who": "You","kh": "ទូកចេញម៉ោងប៉ុន្មាន?","ro": "<b>TOUK</b> chenh maong pon-man?","en": "What time does the boat leave?"},{"who": "Boatman","kh": "ម៉ោងប្រាំបួនកន្លះ។","ro": "maong <b>PRAM</b>-buon kon-lah.","en": "Half past nine."},{"who": "You","kh": "ជិះប៉ុន្មានម៉ោងទៅកោះ?","ro": "<b>CHIH</b> pon-man maong teuv koh?","en": "How many hours to the island?"},{"who": "Boatman","kh": "មួយម៉ោងកន្លះ។","ro": "muoy maong <b>KON-LAH</b>.","en": "An hour and a half."},{"who": "You","kh": "មានអាវសង្គ្រោះទេ?","ro": "mien aav song-<b>KROH</b> tei?","en": "Are there life jackets?"}],"sayit": "<span class=\"kh\">ជិះ</span> <span class=\"ro\">(chih)</span> is the verb for riding anything you sit on — boat, bus, bike, horse, elephant. <span class=\"ro\">chih touk</span>, <span class=\"ro\">chih moto</span>, <span class=\"ro\">chih laan</span>.","phrases": [{"en": "Boat","kh": "ទូក","ro": "<b>touk</b>"},{"en": "Island","kh": "កោះ","ro": "<b>koh</b>"},{"en": "River / sea","kh": "ទន្លេ / សមុទ្រ","ro": "ton-<b>lei</b> / sa-<b>mot</b>"},{"en": "What time does the boat leave?","kh": "ទូកចេញម៉ោងប៉ុន្មាន?","ro": "touk <b>chenh</b> maong pon-man?"},{"en": "Are there life jackets?","kh": "មានអាវសង្គ្រោះទេ?","ro": "mien aav song-<b>kroh</b> tei?"},{"en": "Is the sea rough today?","kh": "ថ្ងៃនេះរលកខ្លាំងទេ?","ro": "thngai nih ro-<b>lok</b> khlang tei?"},{"en": "The last boat back","kh": "ទូកចុងក្រោយត្រឡប់","ro": "touk chong-<b>kraoy</b> tro-lop"},{"en": "I get seasick.","kh": "ខ្ញុំពុលទូក","ro": "khnyom <b>pul</b> touk"}],"tips": [{"label": "Ask About the Last Boat First","html": "Island and river services run to the weather and the number of passengers, not to the timetable painted on the jetty. Before you board <b>anything</b>, ask <span class=\"ro\">touk chong-kraoy tro-lop maong pon-man?</span> — “what time is the last boat back?” — and then take the one before it. In the rainy season a cancelled afternoon crossing can strand you overnight, and the guesthouses know it.","culture": false}],"goal": "Crossing the Mekong, or heading out to an island. Ask about the life jackets — politely, but ask.","ch": 1},
{"n": 19,"title": "Airport & Immigration","titleKm": "ព្រលានយន្តហោះ និងអន្តោប្រវេសន៍","scene": "Immigration is conducted in English, but a Khmer greeting at the counter costs nothing and often shortens things.","dialogue": [{"who": "Officer","kh": "សូមលិខិតឆ្លងដែន។","ro": "som li-khet <b>CHHLONG</b>-daen.","en": "Passport, please."},{"who": "You","kh": "នេះបាទ។ ជម្រាបសួរ។","ro": "nih <b>BAAT</b>. chom-riep suor.","en": "Here you are. Hello."},{"who": "Officer","kh": "មកធ្វើអ្វី? ស្នាក់នៅប៉ុន្មានថ្ងៃ?","ro": "mok <b>THVEU</b> a-vei? snak-nov pon-man thngai?","en": "Why are you here? How many days?"},{"who": "You","kh": "មកទេសចរណ៍ ដប់បួនថ្ងៃ។","ro": "mok teih-sa-<b>CHOA</b>, dop-buon thngai.","en": "Tourism, fourteen days."},{"who": "You","kh": "ខ្ញុំស្នាក់នៅសណ្ឋាគារភ្នំពេញ។","ro": "khnyom <b>SNAK</b>-nov son-thaa-kie phnom-penh.","en": "I’m staying at a hotel in Phnom Penh."}],"sayit": "<span class=\"kh\">ស្នាក់នៅ</span> <span class=\"ro\">(snak-nov)</span> means <em>to stay / lodge</em>, as opposed to <span class=\"kh\">រស់នៅ</span> <span class=\"ro\">(ruoh-nov)</span>, <em>to live</em>. Officials care a great deal about which one you say.","phrases": [{"en": "Passport","kh": "លិខិតឆ្លងដែន","ro": "li-khet <b>chhlong</b>-daen"},{"en": "Visa","kh": "ទិដ្ឋាការ","ro": "tet-thaa-<b>kaa</b>"},{"en": "I’m here for tourism.","kh": "ខ្ញុំមកទេសចរណ៍","ro": "khnyom mok teih-sa-<b>choa</b>"},{"en": "I’m here for work.","kh": "ខ្ញុំមកធ្វើការ","ro": "khnyom mok thveu <b>kaa</b>"},{"en": "Fourteen days","kh": "ដប់បួនថ្ងៃ","ro": "dop-<b>buon</b> thngai"},{"en": "Where is the baggage claim?","kh": "យកកាបូបនៅឯណា?","ro": "yok kaa-<b>boub</b> nov ae-naa?"},{"en": "My bag hasn’t arrived.","kh": "កាបូបខ្ញុំមិនទាន់មក","ro": "kaa-boub khnyom min <b>toan</b> mok"},{"en": "Where do I get a taxi?","kh": "ជិះតាក់ស៊ីនៅឯណា?","ro": "chih taak-<b>sii</b> nov ae-naa?"}],"tips": [{"label": "Have the Exact Fee Ready","html": "Visa-on-arrival is paid in <b>US dollars, in cash</b>, and the counter rarely gives change gracefully. Bring the exact amount plus a passport photo, and keep small notes separate from large ones. If anyone at the airport asks for an extra “processing fee” beyond the posted price, a calm <span class=\"ro\">som toh, khnyom min yul tei</span> — “sorry, I don’t understand” — with a smile is remarkably effective.","culture": false}],"goal": "Immigration is conducted in English, but a Khmer greeting at the counter costs nothing and often shortens things.","ch": 1},
{"n": 20,"title": "Asking for Directions","titleKm": "ការសួរផ្លូវ","scene": "Lost on foot. Ask a shopkeeper rather than a passer-by — they know the street and they are not in a hurry.","dialogue": [{"who": "You","kh": "សូមទោស ផ្សារនៅឯណា?","ro": "som toh, <b>PHSAA</b> nov ae-naa?","en": "Excuse me, where is the market?"},{"who": "Shopkeeper","kh": "ទៅត្រង់ រួចបត់ស្ដាំ។","ro": "teuv <b>TRONG</b>, ruoch bot sdam.","en": "Go straight, then turn right."},{"who": "You","kh": "ឆ្ងាយទេ? ដើរបានទេ?","ro": "<b>CHHNGAY</b> tei? daeu baan tei?","en": "Is it far? Can I walk?"},{"who": "Shopkeeper","kh": "ជិតណាស់ ដប់នាទី។","ro": "<b>CHIT</b> nas, dop nie-ti.","en": "Very close, ten minutes."},{"who": "You","kh": "អរគុណច្រើន បង!","ro": "or-<b>KUN</b> chraen, bong!","en": "Thank you very much!"}],"sayit": "Open with <span class=\"kh\">សូមទោស</span> <span class=\"ro\">(som toh)</span> every single time. Walking up and launching straight into a question reads as abrupt, even when your Khmer is otherwise perfect.","phrases": [{"en": "Where is …?","kh": "… នៅឯណា?","ro": "… nov <b>ae-naa</b>?"},{"en": "Is it far?","kh": "ឆ្ងាយទេ?","ro": "<b>chhngay</b> tei?"},{"en": "Can I walk there?","kh": "ដើរបានទេ?","ro": "<b>daeu</b> baan tei?"},{"en": "Market / pagoda / hospital","kh": "ផ្សារ / វត្ត / មន្ទីរពេទ្យ","ro": "phsaa / voat / mon-ti-<b>peit</b>"},{"en": "Toilet / bank / post office","kh": "បង្គន់ / ធនាគារ / ប្រៃសណីយ៍","ro": "bong-kon / thie-nie-<b>kie</b> / prai-sa-<b>nii</b>"},{"en": "Straight, then right","kh": "ទៅត្រង់ រួចបត់ស្ដាំ","ro": "teuv trong, ruoch bot <b>sdam</b>"},{"en": "I’m lost.","kh": "ខ្ញុំវង្វេងផ្លូវ","ro": "khnyom vong-<b>veng</b> phlov"},{"en": "Please show me on the map.","kh": "សូមបង្ហាញលើផែនទី","ro": "som bong-<b>hanh</b> leu phaen-ti"}],"tips": [{"label": "Nobody Will Tell You They Don’t Know","html": "Saying “I don’t know” to a guest feels unhelpful, so a person who is unsure will often <b>point anyway</b> — confidently, and sometimes wrongly. The fix is simple: ask two people, a hundred metres apart, and go with the answer they agree on. Better still, show the place on your phone map; a picture removes the pressure to guess entirely.","culture": true}],"goal": "Lost on foot. Ask a shopkeeper rather than a passer-by — they know the street and they are not in a hurry.","ch": 1},
{"n": 21,"title": "Getting a Table","titleKm": "ការរកតុអង្គុយ","scene": "You walk into a busy local restaurant. Nobody comes to seat you — you announce yourself instead.","dialogue": [{"who": "You","kh": "សូមទោស មានតុទំនេរទេ?","ro": "som toh, mien <b>TOK</b> tum-nei tei?","en": "Excuse me, is there a free table?"},{"who": "Waiter","kh": "មាន បាទ។ ប៉ុន្មាននាក់?","ro": "<b>MIEN</b>, baat. pon-man neak?","en": "Yes. How many people?"},{"who": "You","kh": "ពីរនាក់ បាទ។","ro": "<b>PII</b> neak, baat.","en": "Two people."},{"who": "You","kh": "សុំតុនៅខាងក្រៅបានទេ?","ro": "som tok nov khang-<b>KRAV</b> baan tei?","en": "Could we sit outside?"},{"who": "Waiter","kh": "អញ្ជើញ។ នេះម៉ឺនុយ។","ro": "an-<b>CHOEUN</b>. nih meu-nuy.","en": "Please. Here’s the menu."}],"sayit": "People are counted with <span class=\"kh\">នាក់</span> <span class=\"ro\">(neak)</span>: <span class=\"ro\">pii neak</span>, <span class=\"ro\">bei neak</span>. Say the number first, then the counter — never the other way round.","phrases": [{"en": "Is there a free table?","kh": "មានតុទំនេរទេ?","ro": "mien <b>tok</b> tum-nei tei?"},{"en": "How many people?","kh": "ប៉ុន្មាននាក់?","ro": "pon-man <b>neak</b>?"},{"en": "Two people","kh": "ពីរនាក់","ro": "<b>pii</b> neak"},{"en": "Menu","kh": "ម៉ឺនុយ","ro": "<b>meu</b>-nuy"},{"en": "Inside / outside","kh": "ខាងក្នុង / ខាងក្រៅ","ro": "khang-<b>knong</b> / khang-<b>krav</b>"},{"en": "Is this seat taken?","kh": "កៅអីនេះមានគេអង្គុយទេ?","ro": "kav-ei nih mien kei <b>ong-kuy</b> tei?"},{"en": "We’ll wait.","kh": "យើងចាំបាន","ro": "yeung <b>cham</b> baan"},{"en": "Do you have air-con?","kh": "មានម៉ាស៊ីនត្រជាក់ទេ?","ro": "mien maa-sin tro-<b>cheak</b> tei?"}],"tips": [{"label": "Nobody Seats You","html": "In most Cambodian restaurants there is no host at the door. You <b>walk in, find a table and sit down</b>; staff arrive once you are settled. To call a waiter, raise a hand and say <span class=\"ro\">bong!</span> — it is normal, not rude. What <em>is</em> rude is clicking your fingers or calling out <span class=\"ro\">“hey”</span>. And the plastic-stool place with no menu is often the best food on the street.","culture": true}],"goal": "You walk into a busy local restaurant. Nobody comes to seat you — you announce yourself instead.","ch": 2},
{"n": 22,"title": "Ordering Food","titleKm": "ការកុម្ម៉ង់ម្ហូប","scene": "One word — <em>som</em> — plus the name of a dish is a complete, polite order. Everything else is decoration.","dialogue": [{"who": "Waiter","kh": "ញ៉ាំអ្វីដែរ បង?","ro": "<b>NYAM</b> a-vei dae, bong?","en": "What will you have?"},{"who": "You","kh": "សុំបាយឆាសាច់មាន់មួយ។","ro": "som bay-<b>CHHAA</b> sach moan muoy.","en": "One chicken fried rice, please."},{"who": "You","kh": "មានអាម៉ុកទេ?","ro": "mien <b>AA-MOK</b> tei?","en": "Do you have amok?"},{"who": "Waiter","kh": "មាន បាទ។ ត្រី ឬសាច់មាន់?","ro": "<b>MIEN</b>, baat. trei reu sach moan?","en": "Yes. Fish or chicken?"},{"who": "You","kh": "ត្រី បាទ។ អស់ប៉ុណ្ណោះ។","ro": "<b>TREI</b>, baat. oh pon-noh.","en": "Fish. That’s all."}],"sayit": "Quantity goes <b>last</b>: <span class=\"ro\">som bay-chhaa muoy</span> is “please, fried rice, one”. Front-loading the number the English way — “one fried rice” — is understood, but marks you instantly.","phrases": [{"en": "I’d like … <em>(one)</em>","kh": "សុំ … មួយ","ro": "<b>som</b> … muoy"},{"en": "Do you have …?","kh": "មាន … ទេ?","ro": "<b>mien</b> … tei?"},{"en": "Rice / fried rice","kh": "បាយ / បាយឆា","ro": "<b>bay</b> / bay-<b>chhaa</b>"},{"en": "Noodle soup","kh": "គុយទាវ","ro": "kuy-<b>tiev</b>"},{"en": "Chicken / pork / beef","kh": "សាច់មាន់ / សាច់ជ្រូក / សាច់គោ","ro": "sach <b>moan</b> / sach <b>chruk</b> / sach <b>kou</b>"},{"en": "Fish / prawn / vegetables","kh": "ត្រី / បង្គា / បន្លែ","ro": "<b>trei</b> / bong-<b>kie</b> / bon-<b>lae</b>"},{"en": "What do you recommend?","kh": "មុខណាឆ្ងាញ់?","ro": "muk naa <b>chhngañ</b>?"},{"en": "That’s all, thank you.","kh": "អស់ប៉ុណ្ណោះ អរគុណ","ro": "oh <b>pon-noh</b>, or-kun"}],"tips": [{"label": "Order the Way Cambodians Do","html": "A Khmer meal is <b>shared</b>: two or three dishes land in the middle with a communal bowl of rice, and everybody takes small amounts onto their own plate. Ordering one dish each, Western style, produces a strange table. Ask <span class=\"ro\">muk naa chhngañ?</span> — “which dish is delicious?” — and let the waiter build the meal. You will eat better and spend less.","culture": false}],"goal": "One word — som — plus the name of a dish is a complete, polite order. Everything else is decoration.","ch": 2},
{"n": 23,"title": "Drinks & Coffee","titleKm": "ភេសជ្ជៈ និងកាហ្វេ","scene": "Khmer iced coffee is sweet, strong and served with condensed milk unless you say otherwise. Say otherwise early.","dialogue": [{"who": "You","kh": "សុំកាហ្វេទឹកកកមួយ។","ro": "som kaa-fei <b>TUK-KOK</b> muoy.","en": "One iced coffee, please."},{"who": "Seller","kh": "ដាក់ទឹកដោះគោទេ?","ro": "dak tuk-doh-<b>KOU</b> tei?","en": "With milk?"},{"who": "You","kh": "អត់ទេ ហើយកុំដាក់ស្ករច្រើន។","ro": "ot tei, haoy kom dak <b>SKO</b> chraen.","en": "No, and not much sugar."},{"who": "You","kh": "សុំទឹកសុទ្ធមួយដបទៀត។","ro": "som tuk <b>SOT</b> muoy dop tiet.","en": "And one bottle of water."},{"who": "Seller","kh": "បាទ ចាំបន្តិច។","ro": "baat, <b>CHAM</b> bon-tech.","en": "Yes, one moment."}],"sayit": "<span class=\"kh\">កុំ</span> <span class=\"ro\">(kom)</span> is “don’t” and goes before the verb: <span class=\"ro\">kom dak sko</span> — “don’t put sugar”. It is direct without being rude, which is exactly what you want when ordering.","phrases": [{"en": "Water / bottled water","kh": "ទឹក / ទឹកសុទ្ធ","ro": "<b>tuk</b> / tuk <b>sot</b>"},{"en": "Ice","kh": "ទឹកកក","ro": "tuk-<b>kok</b>"},{"en": "Coffee / tea","kh": "កាហ្វេ / តែ","ro": "kaa-<b>fei</b> / <b>tae</b>"},{"en": "Iced coffee with milk","kh": "កាហ្វេទឹកដោះគោទឹកកក","ro": "kaa-fei tuk-doh-<b>kou</b> tuk-kok"},{"en": "Not much sugar","kh": "កុំដាក់ស្ករច្រើន","ro": "kom dak <b>sko</b> chraen"},{"en": "No ice, please.","kh": "កុំដាក់ទឹកកក","ro": "kom dak <b>tuk-kok</b>"},{"en": "Beer / fruit shake","kh": "ស្រាបៀរ / ទឹកក្រឡុក","ro": "sraa-<b>bier</b> / tuk kro-<b>lok</b>"},{"en": "One more, please.","kh": "សុំមួយទៀត","ro": "som muoy <b>tiet</b>"}],"tips": [{"label": "Sweet Is the Default","html": "Cambodian coffee arrives with a thick layer of condensed milk at the bottom and sugar on top of that. If you want it plain, say so <b>before</b> the glass is built — afterwards nothing can be done. Ask for <span class=\"kh\">កាហ្វេខ្មៅ</span> <span class=\"ro\">(kaa-fei khmav)</span>, “black coffee”, and add <span class=\"ro\">kom dak sko</span>. Ice in reputable shops is factory-made and safe; the cylindrical kind with a hole through the middle is the one to trust.","culture": false}],"goal": "Khmer iced coffee is sweet, strong and served with condensed milk unless you say otherwise. Say otherwise early.","ch": 2},
{"n": 24,"title": "“Not Spicy, Please”","titleKm": "សុំកុំឲ្យហឹរ","scene": "Khmer food is milder than Thai, but the chilli dish on the table is not. Set your limits at the point of order.","dialogue": [{"who": "You","kh": "សុំកុំឲ្យហឹរ បាទ។","ro": "som kom aoy <b>HOEU</b>, baat.","en": "Not spicy, please."},{"who": "Waiter","kh": "មិនហឹរសោះ ឬហឹរបន្តិច?","ro": "min hoeu <b>SOH</b> reu hoeu bon-tech?","en": "Not at all, or a little spicy?"},{"who": "You","kh": "ហឹរបន្តិចបាន។","ro": "hoeu <b>BON-TECH</b> baan.","en": "A little is fine."},{"who": "You","kh": "ខ្ញុំមិនញ៉ាំម្ទេសទេ។","ro": "khnyom min nyam <b>MTEIH</b> tei.","en": "I don’t eat chilli."},{"who": "Waiter","kh": "បាទ យល់ហើយ។","ro": "baat, <b>YUL</b> haoy.","en": "Yes, understood."}],"sayit": "<span class=\"kh\">ហឹរ</span> <span class=\"ro\">(hoeu)</span> is <em>spicy-hot</em>; <span class=\"kh\">ក្ដៅ</span> <span class=\"ro\">(kdav)</span> is <em>hot in temperature</em>. Asking for food that is not <span class=\"ro\">kdav</span> will get you a cold plate.","phrases": [{"en": "Not spicy, please.","kh": "សុំកុំឲ្យហឹរ","ro": "som kom aoy <b>hoeu</b>"},{"en": "A little spicy is fine.","kh": "ហឹរបន្តិចបាន","ro": "hoeu <b>bon-tech</b> baan"},{"en": "Chilli","kh": "ម្ទេស","ro": "<b>mteih</b>"},{"en": "Sweet / salty / sour","kh": "ផ្អែម / ប្រៃ / ជូរ","ro": "<b>phaem</b> / <b>prai</b> / <b>chou</b>"},{"en": "Too salty","kh": "ប្រៃពេក","ro": "<b>prai</b> peik"},{"en": "No fish sauce, please.","kh": "កុំដាក់ទឹកត្រី","ro": "kom dak <b>tuk-trei</b>"},{"en": "No MSG, please.","kh": "កុំដាក់ប៊ីចេង","ro": "kom dak <b>bii-cheng</b>"},{"en": "Just a little, please.","kh": "សុំតិចៗ","ro": "som <b>tech</b>-tech"}],"tips": [{"label": "Season at the Table","html": "Khmer cooking is built to be <b>adjusted by the eater</b>, which is why every table carries chilli, fish sauce, sugar, lime and pepper. Ordering mild and then seasoning your own bowl is completely normal and slightly insults nobody. The famous exception is <span class=\"kh\">ទឹកត្រី</span> <span class=\"ro\">(tuk-trei, fermented fish sauce)</span> — it is already inside almost every dish, so a genuine fish allergy needs stating clearly and early.","culture": false}],"goal": "Khmer food is milder than Thai, but the chilli dish on the table is not. Set your limits at the point of order.","ch": 2},
{"n": 25,"title": "Street Food Stalls","titleKm": "ម្ហូបតាមចិញ្ចើមផ្លូវ","scene": "No menu, no prices, no English. Point, ask, and eat some of the best food in the country.","dialogue": [{"who": "You","kh": "នេះហៅថាអ្វី?","ro": "nih hav thaa <b>A-VEI</b>?","en": "What is this called?"},{"who": "Seller","kh": "នំបញ្ចុក បង។ ឆ្ងាញ់ណាស់!","ro": "num <b>BON-CHOK</b>, bong. chhngañ nas!","en": "Num banh chok. Very tasty!"},{"who": "You","kh": "មួយចានប៉ុន្មាន?","ro": "muoy <b>CHAAN</b> pon-man?","en": "How much for one plate?"},{"who": "Seller","kh": "បីពាន់រៀល។","ro": "bei <b>POAN</b> riel.","en": "Three thousand riel."},{"who": "You","kh": "សុំមួយចាន យកទៅផ្ទះ។","ro": "som muoy chaan, <b>YOK</b> teuv phteah.","en": "One plate, to take away."}],"sayit": "<span class=\"kh\">យកទៅផ្ទះ</span> <span class=\"ro\">(yok teuv phteah)</span> literally means “take it home” and is how Cambodians say <em>takeaway</em>. Your food arrives in a plastic bag tied with an elastic band.","phrases": [{"en": "What is this called?","kh": "នេះហៅថាអ្វី?","ro": "nih hav thaa <b>a-vei</b>?"},{"en": "How much for one plate?","kh": "មួយចានប៉ុន្មាន?","ro": "muoy <b>chaan</b> pon-man?"},{"en": "Takeaway","kh": "យកទៅផ្ទះ","ro": "<b>yok</b> teuv phteah"},{"en": "Eat here","kh": "ញ៉ាំនៅទីនេះ","ro": "<b>nyam</b> nov ti-nih"},{"en": "Is it delicious?","kh": "ឆ្ងាញ់ទេ?","ro": "<b>chhngañ</b> tei?"},{"en": "I’ll have the same as him.","kh": "សុំដូចគាត់","ro": "som <b>douch</b> koat"},{"en": "Grilled / fried / boiled","kh": "អាំង / បំពង / ស្ងោរ","ro": "<b>ang</b> / bom-<b>pong</b> / <b>sngo</b>"},{"en": "Two, please.","kh": "សុំពីរ","ro": "som <b>pii</b>"}],"tips": [{"label": "Follow the Queue","html": "The safest stall is the <b>busiest</b> one — high turnover means nothing sits warm for hours. Look for a crowd of Cambodians rather than a sign in English, and eat where the cooking happens in front of you. <span class=\"ro\">Som douch koat</span> — “the same as him” — is the single most useful sentence at a stall, and it usually gets you the thing the regulars actually come for.","culture": false}],"goal": "No menu, no prices, no English. Point, ask, and eat some of the best food in the country.","ch": 2},
{"n": 26,"title": "Asking for the Bill","titleKm": "ការសុំគិតលុយ","scene": "Finished eating. Three words end the meal, and a fourth checks the arithmetic.","dialogue": [{"who": "You","kh": "សុំគិតលុយផង!","ro": "som ket <b>LUY</b> phong!","en": "The bill, please!"},{"who": "Waiter","kh": "សរុបដប់ប្រាំដុល្លារ។","ro": "sa-<b>ROP</b> dop-pram dol-laa.","en": "Fifteen dollars in total."},{"who": "You","kh": "សូមមើលវិក្កយបត្របន្តិច។","ro": "som meul vik-<b>KAY</b>-bot bon-tech.","en": "May I see the bill?"},{"who": "You","kh": "បង់តាមកាតបានទេ?","ro": "bong taam <b>KAAT</b> baan tei?","en": "Can I pay by card?"},{"who": "Waiter","kh": "សុំទោស សុំសាច់ប្រាក់។","ro": "som toh, som sach-<b>BRAK</b>.","en": "Sorry, cash only."}],"sayit": "<span class=\"kh\">គិតលុយ</span> <span class=\"ro\">(ket luy)</span> literally means “count the money”. Add <span class=\"ro\">phong</span> at the end and a raised hand, and it is warm rather than brusque.","phrases": [{"en": "The bill, please.","kh": "សុំគិតលុយផង","ro": "som ket <b>luy</b> phong"},{"en": "How much in total?","kh": "សរុបប៉ុន្មាន?","ro": "sa-<b>rop</b> pon-man?"},{"en": "Can I pay by card?","kh": "បង់តាមកាតបានទេ?","ro": "bong taam <b>kaat</b> baan tei?"},{"en": "Cash","kh": "សាច់ប្រាក់","ro": "sach-<b>brak</b>"},{"en": "I think this is wrong.","kh": "ខ្ញុំគិតថាខុស","ro": "khnyom ket thaa <b>khoh</b>"},{"en": "We’ll pay separately.","kh": "យើងបង់ដាច់ដោយឡែក","ro": "yeung bong <b>dach</b> daoy-laek"},{"en": "Keep the change.","kh": "មិនបាច់អាប់ទេ","ro": "min <b>bach</b> ap tei"},{"en": "It was delicious, thank you.","kh": "ឆ្ងាញ់ណាស់ អរគុណ","ro": "<b>chhngañ</b> nas, or-kun"}],"tips": [{"label": "Dollars In, Riel Out","html": "Cambodia runs on two currencies at once. You pay in <b>US dollars</b> and receive change under one dollar in <b>riel</b>, at a fixed rate of about 4,000 riel to the dollar. So a $3.50 bill settled with a $5 note comes back as one dollar and 2,000 riel. Refuse torn or heavily marked dollar notes — shops will refuse them from you later.","culture": false}],"goal": "Finished eating. Three words end the meal, and a fourth checks the arithmetic.","ch": 2},
{"n": 27,"title": "Praising & Complaining","titleKm": "ការសរសើរ និងការត្អូញត្អែរ","scene": "One compliment will be remembered for months. One complaint, made gently, will be fixed immediately.","dialogue": [{"who": "You","kh": "ឆ្ងាញ់ណាស់! ធ្វើពូកែម៉ែន។","ro": "<b>CHHNGAÑ</b> nas! thveu pu-kae maen.","en": "Delicious! Really well made."},{"who": "Cook","kh": "អរគុណ បង។ ញ៉ាំបន្ថែមទេ?","ro": "or-<b>KUN</b>, bong. nyam bon-thaem tei?","en": "Thank you. Would you like more?"},{"who": "You","kh": "សូមទោស នេះមិនមែនអ្វីដែលខ្ញុំសុំ។","ro": "som toh, nih min maen a-vei dael khnyom <b>SOM</b>.","en": "Sorry, this isn’t what I ordered."},{"who": "Waiter","kh": "អូ សូមទោស! ខ្ញុំប្ដូរឲ្យ។","ro": "ouh, som <b>TOH</b>! khnyom bdo aoy.","en": "Oh, sorry! I’ll change it."},{"who": "You","kh": "អត់អីទេ អរគុណ។","ro": "ot ei <b>TEI</b>, or-kun.","en": "No problem, thank you."}],"sayit": "<span class=\"kh\">ឆ្ងាញ់</span> <span class=\"ro\">(chhngañ)</span> ends in the <em>ny</em> of <em>canyon</em>, closed off without release. It is the highest praise you can pay a Cambodian cook, and it costs one syllable.","phrases": [{"en": "Delicious!","kh": "ឆ្ងាញ់ណាស់!","ro": "<b>chhngañ</b> nas!"},{"en": "I’m full, thank you.","kh": "ខ្ញុំឆ្អែតហើយ អរគុណ","ro": "khnyom <b>chha-aet</b> haoy"},{"en": "This isn’t what I ordered.","kh": "នេះមិនមែនអ្វីដែលខ្ញុំសុំ","ro": "nih min maen a-vei dael khnyom <b>som</b>"},{"en": "It’s cold.","kh": "វាត្រជាក់ហើយ","ro": "vie tro-<b>cheak</b> haoy"},{"en": "It’s not cooked enough.","kh": "វាមិនទាន់ឆ្អិន","ro": "vie min toan <b>chha-en</b>"},{"en": "Could you reheat it?","kh": "ជួយកម្ដៅវាឡើងវិញ","ro": "chuoy kom-<b>dav</b> vie laeung vinh"},{"en": "Still waiting for my food.","kh": "ខ្ញុំនៅចាំម្ហូបនៅឡើយ","ro": "khnyom nov <b>cham</b> mhoub nov-laeuy"},{"en": "Would you like more?","kh": "ញ៉ាំបន្ថែមទេ?","ro": "nyam bon-<b>thaem</b> tei?"}],"tips": [{"label": "Complain Softly, Get More","html": "Raising your voice in a Cambodian restaurant loses you the argument instantly — the staff will smile, freeze, and quietly stop helping. Public anger causes a loss of face on both sides. Open every complaint with <span class=\"ro\">som toh</span>, keep your tone flat and friendly, and you will usually get the dish replaced <b>and</b> something free. The soft approach is not politeness here; it is the effective one.","culture": true}],"goal": "One compliment will be remembered for months. One complaint, made gently, will be fixed immediately.","ch": 2},
{"n": 28,"title": "Vegetarian & Allergies","titleKm": "អាហារបួស និងអាឡែស៊ី","scene": "“Vegetarian” is not a familiar category here. Be concrete: name what you cannot eat, one item at a time.","dialogue": [{"who": "You","kh": "ខ្ញុំញ៉ាំបួស។ មានម្ហូបបួសទេ?","ro": "khnyom nyam <b>BUOH</b>. mien mhoub buoh tei?","en": "I’m vegetarian. Do you have vegetarian food?"},{"who": "Waiter","kh": "មាន បន្លែឆា។","ro": "<b>MIEN</b>, bon-lae chhaa.","en": "Yes, stir-fried vegetables."},{"who": "You","kh": "កុំដាក់សាច់ និងទឹកត្រី។","ro": "kom dak <b>SACH</b> ning tuk-trei.","en": "No meat and no fish sauce."},{"who": "You","kh": "ខ្ញុំមានអាឡែស៊ីនឹងសណ្ដែកដី។","ro": "khnyom mien aa-lae-<b>SII</b> neung son-daek-dei.","en": "I’m allergic to peanuts."},{"who": "Waiter","kh": "បាទ ខ្ញុំនឹងប្រាប់ចុងភៅ។","ro": "baat, khnyom neung <b>BRAB</b> chong-phov.","en": "Yes, I’ll tell the cook."}],"sayit": "<span class=\"kh\">បួស</span> <span class=\"ro\">(buoh)</span> carries a Buddhist sense — food fit for a monk on holy days. Saying <span class=\"ro\">khnyom nyam buoh</span> is understood immediately, where the English word “vegetarian” often is not.","phrases": [{"en": "I’m vegetarian.","kh": "ខ្ញុំញ៉ាំបួស","ro": "khnyom nyam <b>buoh</b>"},{"en": "I don’t eat meat.","kh": "ខ្ញុំមិនញ៉ាំសាច់ទេ","ro": "khnyom min nyam <b>sach</b> tei"},{"en": "No fish sauce","kh": "កុំដាក់ទឹកត្រី","ro": "kom dak <b>tuk-trei</b>"},{"en": "I’m allergic to …","kh": "ខ្ញុំមានអាឡែស៊ីនឹង …","ro": "khnyom mien aa-lae-<b>sii</b> neung …"},{"en": "Peanuts / shellfish","kh": "សណ្ដែកដី / គ្រឿងសមុទ្រ","ro": "son-daek-<b>dei</b> / kroeung sa-<b>mot</b>"},{"en": "Egg / milk","kh": "ស៊ុត / ទឹកដោះគោ","ro": "<b>sot</b> / tuk-doh-<b>kou</b>"},{"en": "It could make me very ill.","kh": "វាអាចធ្វើឲ្យខ្ញុំឈឺធ្ងន់","ro": "vie ach thveu aoy khnyom <b>chheu</b> thngon"},{"en": "Does this contain …?","kh": "នេះមាន … ទេ?","ro": "nih <b>mien</b> … tei?"}],"tips": [{"label": "Name the Ingredient, Not the Diet","html": "Categories travel badly; ingredients do not. “Vegetarian” may still arrive with chicken stock or a spoon of fish sauce, because those are seasonings rather than <em>meat</em> in the local sense. Say instead: <b>no pork, no chicken, no fish, no fish sauce</b> — four short phrases, listed one by one. For a serious allergy, have a Cambodian friend write it in Khmer on a card and show that; it removes every gap in pronunciation.","culture": false}],"goal": "“Vegetarian” is not a familiar category here. Be concrete: name what you cannot eat, one item at a time.","ch": 2},
{"n": 29,"title": "Ordering Delivery","titleKm": "ការកុម្ម៉ង់ដឹកជញ្ជូន","scene": "The app is in English but the rider is not. He will call when he reaches your street — be ready.","dialogue": [{"who": "Rider","kh": "ហាឡូ! ខ្ញុំដល់ហើយ។ ផ្ទះលេខប៉ុន្មាន?","ro": "haa-lou! khnyom <b>DOL</b> haoy. phteah leik pon-man?","en": "Hello! I’m here. What house number?"},{"who": "You","kh": "ផ្ទះលេខសែសិបប្រាំ។","ro": "phteah leik sae-sep <b>PRAM</b>.","en": "House number forty-five."},{"who": "You","kh": "នៅជាប់ហាងកាហ្វេ។","ro": "nov <b>CHOAB</b> hang kaa-fei.","en": "Next to the coffee shop."},{"who": "Rider","kh": "ចុះមកទទួលបានទេ?","ro": "choh mok <b>TO-TUOL</b> baan tei?","en": "Can you come down to collect it?"},{"who": "You","kh": "បាទ ចាំពីរនាទី។","ro": "baat, <b>CHAM</b> pii nie-ti.","en": "Yes, give me two minutes."}],"sayit": "<span class=\"kh\">ជាប់</span> <span class=\"ro\">(choab)</span> means “attached to / right next to”. <span class=\"ro\">nov choab …</span> is far more useful to a rider than any street name.","phrases": [{"en": "Delivery","kh": "ដឹកជញ្ជូន","ro": "deuk chon-<b>choun</b>"},{"en": "House number …","kh": "ផ្ទះលេខ …","ro": "phteah <b>leik</b> …"},{"en": "Next to the coffee shop","kh": "នៅជាប់ហាងកាហ្វេ","ro": "nov <b>choab</b> hang kaa-fei"},{"en": "Opposite the pagoda","kh": "នៅទល់មុខវត្ត","ro": "nov tol-<b>muk</b> voat"},{"en": "I’ll come down.","kh": "ខ្ញុំចុះមក","ro": "khnyom <b>choh</b> mok"},{"en": "Please leave it at the gate.","kh": "សូមទុកនៅមុខច្រកទ្វារ","ro": "som <b>tuk</b> nov muk chrok-tvie"},{"en": "How long will it take?","kh": "ត្រូវចំណាយពេលប៉ុន្មាន?","ro": "trov chom-nay peil <b>pon-man</b>?"},{"en": "I already paid online.","kh": "ខ្ញុំបង់លុយរួចហើយ","ro": "khnyom bong luy <b>ruoch</b> haoy"}],"tips": [{"label": "Save Your Address in Khmer","html": "Type your address in Khmer script into your phone’s notes once, with the nearest landmark, and paste it into every delivery order afterwards. Riders navigate by <b>landmark plus phone call</b>, not by GPS pin — pins in Phnom Penh are frequently thirty metres and one alley wrong. Adding <span class=\"ro\">nov choab …</span> (“next to …”) to the order note saves the call altogether.","culture": false}],"goal": "The app is in English but the rider is not. He will call when he reaches your street — be ready.","ch": 2},
{"n": 30,"title": "A Guest at a Khmer Meal","titleKm": "ជាភ្ញៀវក្នុងអាហារខ្មែរ","scene": "You have been invited to eat at a family home. What you say at the table matters more than what you eat.","dialogue": [{"who": "Host","kh": "អញ្ជើញពិសាអាហារ!","ro": "an-choeun pi-<b>SAA</b> aa-haa!","en": "Please, help yourself to the food!"},{"who": "You","kh": "អរគុណ។ ម្ហូបឆ្ងាញ់ណាស់។","ro": "or-kun. mhoub <b>CHHNGAÑ</b> nas.","en": "Thank you. The food is delicious."},{"who": "Host","kh": "ញ៉ាំបន្ថែមទៀតទៅ!","ro": "nyam bon-<b>THAEM</b> tiet teuv!","en": "Have some more!"},{"who": "You","kh": "ខ្ញុំឆ្អែតហើយ អរគុណច្រើន។","ro": "khnyom <b>CHHA-AET</b> haoy, or-kun chraen.","en": "I’m full, thank you very much."},{"who": "You","kh": "អរគុណសម្រាប់ការអញ្ជើញ។","ro": "or-kun som-rap kaa an-<b>CHOEUN</b>.","en": "Thank you for the invitation."}],"sayit": "<span class=\"kh\">ពិសា</span> <span class=\"ro\">(pisaa)</span> is the polite word for <em>to eat</em>, used for guests and elders; <span class=\"kh\">ញ៉ាំ</span> <span class=\"ro\">(nyam)</span> is the everyday one. Hearing <span class=\"ro\">pisaa</span> means you are being honoured.","phrases": [{"en": "Please, help yourself.","kh": "អញ្ជើញពិសា","ro": "an-choeun pi-<b>saa</b>"},{"en": "The food is delicious.","kh": "ម្ហូបឆ្ងាញ់ណាស់","ro": "mhoub <b>chhngañ</b> nas"},{"en": "Have some more!","kh": "ញ៉ាំបន្ថែមទៀត","ro": "nyam bon-<b>thaem</b> tiet"},{"en": "I’m full, thank you.","kh": "ខ្ញុំឆ្អែតហើយ","ro": "khnyom <b>chha-aet</b> haoy"},{"en": "Thank you for inviting me.","kh": "អរគុណសម្រាប់ការអញ្ជើញ","ro": "or-kun som-rap kaa an-<b>choeun</b>"},{"en": "Who cooked this?","kh": "អ្នកណាធ្វើម្ហូបនេះ?","ro": "neak-naa thveu <b>mhoub</b> nih?"},{"en": "May I help you?","kh": "ខ្ញុំជួយបានទេ?","ro": "khnyom <b>chuoy</b> baan tei?"},{"en": "I should go home now.","kh": "ខ្ញុំសុំលាទៅផ្ទះ","ro": "khnyom som <b>lie</b> teuv phteah"}],"tips": [{"label": "Let the Eldest Start","html": "Wait for the oldest person at the table to lift their spoon before you touch yours, and serve <b>them</b> before yourself if a dish is near you. Take small portions from the shared bowls onto your own plate rather than eating out of the middle. You will be pressed to eat more long after you are full — <span class=\"ro\">khnyom chha-aet haoy</span> with a hand over the bowl is the accepted way to stop, and it may take saying twice.","culture": true}],"goal": "You have been invited to eat at a family home. What you say at the table matters more than what you eat.","ch": 2},
{"n": 31,"title": "At the Market","titleKm": "នៅផ្សារ","scene": "The wet market opens at five and empties by nine. Bring small notes and a bag, and speak first.","dialogue": [{"who": "You","kh": "បង សណ្ដែកបារាំងមួយគីឡូប៉ុន្មាន?","ro": "bong, son-daek baa-rang muoy ki-<b>LOU</b> pon-man?","en": "How much is a kilo of potatoes?"},{"who": "Seller","kh": "បួនពាន់រៀល បង។","ro": "<b>BUON</b> poan riel, bong.","en": "Four thousand riel."},{"who": "You","kh": "សុំពីរគីឡូ។ ស្រស់ទេ?","ro": "som pii ki-lou. <b>SROH</b> tei?","en": "Two kilos, please. Is it fresh?"},{"who": "Seller","kh": "ស្រស់ណាស់ ទើបមកពីព្រឹក។","ro": "<b>SROH</b> nas, teub mok pii pruk.","en": "Very fresh, it came this morning."},{"who": "You","kh": "សុំបន្ថែមម្ទេសបន្តិចផង។","ro": "som bon-<b>THAEM</b> mteih bon-tech phong.","en": "Add a few chillies too, please."}],"sayit": "Open with <span class=\"ro\">bong</span> before the question. Walking up and firing <span class=\"ro\">pon-man?</span> at a seller sounds like an interrogation; one warm syllable in front changes the whole exchange.","phrases": [{"en": "How much per kilo?","kh": "មួយគីឡូប៉ុន្មាន?","ro": "muoy ki-<b>lou</b> pon-man?"},{"en": "Vegetables / fruit","kh": "បន្លែ / ផ្លែឈើ","ro": "bon-<b>lae</b> / phlae-<b>chheu</b>"},{"en": "Is it fresh?","kh": "ស្រស់ទេ?","ro": "<b>sroh</b> tei?"},{"en": "Two kilos, please.","kh": "សុំពីរគីឡូ","ro": "som pii ki-<b>lou</b>"},{"en": "A little more / a little less","kh": "បន្ថែមបន្តិច / បន្ថយបន្តិច","ro": "bon-<b>thaem</b> / bon-<b>thoy</b> bon-tech"},{"en": "I don’t want a bag.","kh": "មិនបាច់ថង់ទេ","ro": "min bach <b>thong</b> tei"},{"en": "Where do they sell fish?","kh": "លក់ត្រីនៅឯណា?","ro": "luok <b>trei</b> nov ae-naa?"},{"en": "That’s all, thank you.","kh": "អស់ប៉ុណ្ណោះ អរគុណ","ro": "oh <b>pon-noh</b>, or-kun"}],"tips": [{"label": "Find One Seller and Stay","html": "Cambodian markets run on relationships, not on comparison shopping. Buy from the <b>same vegetable seller every week</b> and within a month you will be given the good tomatoes without asking, quoted the local price automatically, and handed free herbs. Learn her name, greet her before you buy, and the market stops being a place you negotiate and becomes a place you are known.","culture": true}],"goal": "The wet market opens at five and empties by nine. Bring small notes and a bag, and speak first.","ch": 3},
{"n": 32,"title": "Bargaining","titleKm": "ការតថ្លៃ","scene": "Bargaining is a conversation, not a fight. Smile the whole way through and be ready to walk.","dialogue": [{"who": "Seller","kh": "ម្ភៃដុល្លារ បង។","ro": "<b>MPHEY</b> dol-laa, bong.","en": "Twenty dollars."},{"who": "You","kh": "អូ ថ្លៃណាស់! ចុះថ្លៃបានទេ?","ro": "ouh, <b>THLAI</b> nas! choh thlai baan tei?","en": "Oh, that’s expensive! Can you come down?"},{"who": "You","kh": "ដប់ដុល្លារបានទេ?","ro": "<b>DOP</b> dol-laa baan tei?","en": "Ten dollars, alright?"},{"who": "Seller","kh": "មិនបានទេ បង។ ដប់ប្រាំ។","ro": "min baan tei, bong. <b>DOP</b>-pram.","en": "Not possible. Fifteen."},{"who": "You","kh": "ដប់ពីរ ខ្ញុំយក។","ro": "<b>DOP</b>-pii, khnyom yok.","en": "Twelve and I’ll take it."}],"sayit": "The magic word is <span class=\"ro\">baan tei?</span> — “is that possible?” Attach it to any number and you have made an offer without ever sounding demanding.","phrases": [{"en": "That’s expensive!","kh": "ថ្លៃណាស់!","ro": "<b>thlai</b> nas!"},{"en": "Can you come down?","kh": "ចុះថ្លៃបានទេ?","ro": "choh <b>thlai</b> baan tei?"},{"en": "Ten dollars, alright?","kh": "ដប់ដុល្លារបានទេ?","ro": "<b>dop</b> dol-laa baan tei?"},{"en": "Cheap / expensive","kh": "ថោក / ថ្លៃ","ro": "<b>thaok</b> / <b>thlai</b>"},{"en": "I’ll take it.","kh": "ខ្ញុំយក","ro": "khnyom <b>yok</b>"},{"en": "I’ll think about it.","kh": "ខ្ញុំគិតសិន","ro": "khnyom <b>ket</b> sen"},{"en": "What’s your best price?","kh": "តម្លៃចុងក្រោយប៉ុន្មាន?","ro": "tom-lai chong-<b>kraoy</b> pon-man?"},{"en": "If I buy two?","kh": "បើទិញពីរវិញ?","ro": "baeu <b>tinh</b> pii vinh?"}],"tips": [{"label": "Walking Away Is the Real Offer","html": "Say <span class=\"ro\">khnyom ket sen</span> — “let me think about it” — and start walking. If your price was workable you will be called back within five steps; if you are not called back, it genuinely was too low. This is understood as part of the game by both sides. What is <b>not</b> acceptable is bargaining hard and then not buying: settle a price only on something you actually intend to take.","culture": false}],"goal": "Bargaining is a conversation, not a fight. Smile the whole way through and be ready to walk.","ch": 3},
{"n": 33,"title": "Asking the Price","titleKm": "ការសួរតម្លៃ","scene": "Two words get you a number. The rest of this page teaches you to understand the answer.","dialogue": [{"who": "You","kh": "នេះថ្លៃប៉ុន្មាន?","ro": "nih <b>THLAI</b> pon-man?","en": "How much is this?"},{"who": "Seller","kh": "មួយម៉ឺនរៀល។","ro": "muoy <b>MEUN</b> riel.","en": "Ten thousand riel."},{"who": "You","kh": "សូមទោស ប៉ុន្មានដុល្លារ?","ro": "som toh, pon-man <b>DOL-LAA</b>?","en": "Sorry, how much in dollars?"},{"who": "Seller","kh": "ពីរដុល្លារកន្លះ។","ro": "pii dol-laa <b>KON-LAH</b>.","en": "Two dollars fifty."},{"who": "You","kh": "សូមសរសេរតម្លៃឲ្យខ្ញុំ។","ro": "som sor-sei tom-<b>LAI</b> aoy khnyom.","en": "Please write the price down for me."}],"sayit": "Riel are quoted in thousands and ten-thousands: <span class=\"ro\">muoy poan</span> is 1,000 and <span class=\"kh\">មួយម៉ឺន</span> <span class=\"ro\">(muoy meun)</span> is 10,000. Miss <span class=\"ro\">meun</span> and you will hear the price as ten times too little.","phrases": [{"en": "How much is this?","kh": "នេះថ្លៃប៉ុន្មាន?","ro": "nih <b>thlai</b> pon-man?"},{"en": "1,000 / 10,000 riel","kh": "មួយពាន់ / មួយម៉ឺន រៀល","ro": "muoy <b>poan</b> / muoy <b>meun</b> riel"},{"en": "How much in dollars?","kh": "ប៉ុន្មានដុល្លារ?","ro": "pon-man <b>dol-laa</b>?"},{"en": "Two dollars fifty","kh": "ពីរដុល្លារកន្លះ","ro": "pii dol-laa <b>kon-lah</b>"},{"en": "Please write it down.","kh": "សូមសរសេរឲ្យខ្ញុំ","ro": "som sor-<b>sei</b> aoy khnyom"},{"en": "Is the price fixed?","kh": "តម្លៃថេរទេ?","ro": "tom-lai <b>thei</b> tei?"},{"en": "Do you have change?","kh": "មានលុយអាប់ទេ?","ro": "mien luy <b>ap</b> tei?"},{"en": "May I have a receipt?","kh": "សុំបង្កាន់ដៃផង","ro": "som bong-<b>kan</b>-dai phong"}],"tips": [{"label": "Carry Small Notes","html": "Handing a $50 note to a market seller for a $2 purchase will stop the transaction entirely — nobody at street level holds that much change, and you will be sent to break it yourself. Keep <b>ones, fives and riel notes</b> in a separate pocket. In supermarkets and petrol stations, large notes are fine; everywhere else, the small money is what makes you easy to serve.","culture": false}],"goal": "Two words get you a number. The rest of this page teaches you to understand the answer.","ch": 3},
{"n": 34,"title": "Clothes, Sizes & Colours","titleKm": "សម្លៀកបំពាក់ ទំហំ និងពណ៌","scene": "Sizes run small and there is rarely a changing room. Ask to try, and ask about the colour.","dialogue": [{"who": "You","kh": "សុំមើលអាវនោះបន្តិច។","ro": "som meul <b>AAV</b> nuh bon-tech.","en": "May I look at that shirt?"},{"who": "Seller","kh": "អញ្ជើញ បង។ ទំហំណា?","ro": "an-choeun, bong. <b>TUM-HOM</b> naa?","en": "Please. Which size?"},{"who": "You","kh": "សុំធំជាងនេះបន្តិច។","ro": "som <b>THOM</b> chieng nih bon-tech.","en": "A bit bigger than this, please."},{"who": "You","kh": "មានពណ៌ខៀវទេ?","ro": "mien poa <b>KHIEV</b> tei?","en": "Do you have it in blue?"},{"who": "You","kh": "សាកល្បងបានទេ?","ro": "saak-<b>LORNG</b> baan tei?","en": "May I try it on?"}],"sayit": "Comparatives use <span class=\"kh\">ជាង</span> <span class=\"ro\">(chieng)</span> after the adjective: <span class=\"ro\">thom chieng nih</span> — “bigger than this”, literally “big more-than this”.","phrases": [{"en": "Shirt / trousers / shoes","kh": "អាវ / ខោ / ស្បែកជើង","ro": "<b>aav</b> / <b>khao</b> / sbaek-<b>choeung</b>"},{"en": "Big / small","kh": "ធំ / តូច","ro": "<b>thom</b> / <b>touch</b>"},{"en": "A bit bigger, please.","kh": "សុំធំជាងនេះបន្តិច","ro": "som <b>thom</b> chieng nih bon-tech"},{"en": "May I try it on?","kh": "សាកល្បងបានទេ?","ro": "saak-<b>lorng</b> baan tei?"},{"en": "Red / blue / black / white","kh": "ក្រហម / ខៀវ / ខ្មៅ / ស","ro": "kro-<b>hom</b> / <b>khiev</b> / <b>khmav</b> / <b>saw</b>"},{"en": "It’s too tight / too loose.","kh": "តឹងពេក / ធំពេក","ro": "<b>teung</b> peik / <b>thom</b> peik"},{"en": "It suits you.","kh": "សមនឹងអ្នកណាស់","ro": "<b>som</b> neung neak nas"},{"en": "Is this cotton?","kh": "នេះកប្បាសមែនទេ?","ro": "nih kop-<b>baah</b> maen tei?"}],"tips": [{"label": "Have It Altered","html": "Tailoring is cheap and everywhere. A market shirt that almost fits can be taken in for a dollar or two by the <span class=\"kh\">ជាងកាត់ដេរ</span> <span class=\"ro\">(chieng kat-dei, tailor)</span> sitting three stalls away — often on the spot. This is why Cambodians buy clothes that are slightly loose rather than slightly tight, and why <span class=\"ro\">thom chieng nih bon-tech</span> is the more useful of the two size phrases above.","culture": false}],"goal": "Sizes run small and there is rarely a changing room. Ask to try, and ask about the colour.","ch": 3},
{"n": 35,"title": "At the Minimart","titleKm": "នៅហាងលក់ទំនិញ","scene": "Fixed prices, air conditioning, and one question you will ask constantly: where is it?","dialogue": [{"who": "You","kh": "សូមទោស មានទឹកសុទ្ធធំទេ?","ro": "som toh, mien tuk <b>SOT</b> thom tei?","en": "Excuse me, do you have large bottled water?"},{"who": "Staff","kh": "មាន នៅជួរខាងក្រោយ។","ro": "<b>MIEN</b>, nov chuo khang-kraoy.","en": "Yes, in the row at the back."},{"who": "You","kh": "សាប៊ូនៅជួរណា?","ro": "saa-<b>BUU</b> nov chuo naa?","en": "Which aisle is the soap in?"},{"who": "Staff","kh": "ជួរទីពីរ បង។","ro": "chuo ti <b>PII</b>, bong.","en": "Aisle two."},{"who": "You","kh": "មិនបាច់ថង់ទេ អរគុណ។","ro": "min bach <b>THONG</b> tei, or-kun.","en": "No bag needed, thank you."}],"sayit": "<span class=\"kh\">មាន … ទេ?</span> <span class=\"ro\">(mien … tei?)</span> — “do you have …?” — is the workhorse shopping question. Slot any noun into the middle and you can shop anywhere in the country.","phrases": [{"en": "Do you have …?","kh": "មាន … ទេ?","ro": "<b>mien</b> … tei?"},{"en": "Which aisle?","kh": "នៅជួរណា?","ro": "nov <b>chuo</b> naa?"},{"en": "Soap / shampoo","kh": "សាប៊ូ / ទឹកកក់សក់","ro": "saa-<b>buu</b> / tuk kok <b>sok</b>"},{"en": "Toilet paper","kh": "ក្រដាសអនាម័យ","ro": "kro-<b>daah</b> a-nie-may"},{"en": "Bread / eggs / milk","kh": "នំបុ័ង / ស៊ុត / ទឹកដោះគោ","ro": "num-<b>pang</b> / <b>sot</b> / tuk-doh-<b>kou</b>"},{"en": "No bag, thank you.","kh": "មិនបាច់ថង់ទេ","ro": "min bach <b>thong</b> tei"},{"en": "Is this on sale?","kh": "នេះបញ្ចុះតម្លៃទេ?","ro": "nih banh-choh tom-<b>lai</b> tei?"},{"en": "When does it expire?","kh": "ផុតកំណត់ពេលណា?","ro": "<b>phot</b> kom-not peil naa?"}],"tips": [{"label": "Check the Date on Dairy","html": "Power cuts are common and the cold chain is not always unbroken, so milk, yoghurt and imported cheese deserve a glance at the date — <span class=\"kh\">ផុតកំណត់</span> <span class=\"ro\">(phot kom-not)</span>, “expiry”. Minimart prices are fixed and marked, so no bargaining happens here; that is precisely what makes them a comfortable place to practise your Khmer without any money riding on the outcome.","culture": false}],"goal": "Fixed prices, air conditioning, and one question you will ask constantly: where is it?","ch": 3},
{"n": 36,"title": "At the Pharmacy","titleKm": "នៅឱសថស្ថាន","scene": "Pharmacists here diagnose as well as dispense. Describe the symptom simply and let them suggest.","dialogue": [{"who": "You","kh": "ខ្ញុំឈឺក្បាល និងក្ដៅខ្លួន។","ro": "khnyom chheu <b>KBAAL</b> ning kdav kluon.","en": "I have a headache and a fever."},{"who": "Pharmacist","kh": "ប៉ុន្មានថ្ងៃហើយ?","ro": "pon-man <b>THNGAI</b> haoy?","en": "For how many days?"},{"who": "You","kh": "ពីរថ្ងៃហើយ។","ro": "<b>PII</b> thngai haoy.","en": "Two days now."},{"who": "Pharmacist","kh": "ញ៉ាំមួយគ្រាប់ បីដងក្នុងមួយថ្ងៃ។","ro": "nyam muoy <b>KROAB</b>, bei dong knong muoy thngai.","en": "Take one tablet, three times a day."},{"who": "You","kh": "ញ៉ាំមុន ឬក្រោយអាហារ?","ro": "nyam <b>MUN</b> reu kraoy aa-haa?","en": "Before or after food?"}],"sayit": "<span class=\"kh\">ឈឺ</span> <span class=\"ro\">(chheu)</span> means “to hurt / be sick” and takes the body part straight after it: <span class=\"ro\">chheu kbaal</span> (head), <span class=\"ro\">chheu poh</span> (stomach), <span class=\"ro\">chheu thmenh</span> (tooth).","phrases": [{"en": "Medicine","kh": "ថ្នាំ","ro": "<b>thnam</b>"},{"en": "I have a headache.","kh": "ខ្ញុំឈឺក្បាល","ro": "khnyom chheu <b>kbaal</b>"},{"en": "I have a fever.","kh": "ខ្ញុំក្ដៅខ្លួន","ro": "khnyom <b>kdav</b> kluon"},{"en": "Stomach ache / diarrhoea","kh": "ឈឺពោះ / រាគ","ro": "chheu <b>poh</b> / <b>riek</b>"},{"en": "Painkiller","kh": "ថ្នាំបំបាត់ការឈឺចាប់","ro": "thnam bom-<b>bat</b> kaa chheu-chap"},{"en": "How many times a day?","kh": "ញ៉ាំប៉ុន្មានដងក្នុងមួយថ្ងៃ?","ro": "nyam pon-man <b>dong</b> knong muoy thngai?"},{"en": "Before / after food","kh": "មុន / ក្រោយអាហារ","ro": "<b>mun</b> / <b>kraoy</b> aa-haa"},{"en": "Mosquito repellent","kh": "ថ្នាំបាញ់មូស","ro": "thnam banh <b>muuh</b>"}],"tips": [{"label": "Ask for the Box","html": "Cambodian pharmacies often dispense loose tablets in a small plastic bag with the dosage written on it, and antibiotics are sold without a prescription. Ask for <b>the original box</b> so you can read the drug name and strength — <span class=\"ro\">som yok bratab phong</span>, “the packet too, please”. If symptoms last more than three days, or involve a high fever, go to a clinic rather than back to the pharmacy: dengue is common and needs a blood test.","culture": false}],"goal": "Pharmacists here diagnose as well as dispense. Describe the symptom simply and let them suggest.","ch": 3},
{"n": 37,"title": "Riel & Dollars","titleKm": "រៀល និងដុល្លារ","scene": "Two currencies, one wallet. Understand the exchange and you stop losing small amounts all day long.","dialogue": [{"who": "You","kh": "ខ្ញុំចង់ប្ដូរលុយ។","ro": "khnyom chong <b>BDO</b> luy.","en": "I want to change money."},{"who": "Changer","kh": "ប្ដូរប៉ុន្មានដុល្លារ?","ro": "bdo pon-man <b>DOL-LAA</b>?","en": "How many dollars?"},{"who": "You","kh": "ហាសិបដុល្លារ។ អត្រាប៉ុន្មាន?","ro": "haa-sep dol-laa. <b>AT-TRAA</b> pon-man?","en": "Fifty dollars. What’s the rate?"},{"who": "Changer","kh": "មួយដុល្លារបួនពាន់រៀល។","ro": "muoy dol-laa <b>BUON</b> poan riel.","en": "Four thousand riel to the dollar."},{"who": "You","kh": "សុំលុយតូចៗផង។","ro": "som luy <b>TOUCH</b>-touch phong.","en": "Small notes, please."}],"sayit": "<span class=\"kh\">លុយតូចៗ</span> <span class=\"ro\">(luy touch-touch)</span> — literally “small small money” — is how you ask for small denominations. It is the most practically useful request on this page.","phrases": [{"en": "I want to change money.","kh": "ខ្ញុំចង់ប្ដូរលុយ","ro": "khnyom chong <b>bdo</b> luy"},{"en": "What is the rate?","kh": "អត្រាប្ដូរប្រាក់ប៉ុន្មាន?","ro": "<b>at-traa</b> bdo brak pon-man?"},{"en": "Riel / dollars","kh": "រៀល / ដុល្លារ","ro": "<b>riel</b> / dol-<b>laa</b>"},{"en": "Small notes, please.","kh": "សុំលុយតូចៗផង","ro": "som luy <b>touch</b>-touch phong"},{"en": "Do you have change?","kh": "មានលុយអាប់ទេ?","ro": "mien luy <b>ap</b> tei?"},{"en": "This note is torn.","kh": "ក្រដាសប្រាក់នេះរហែក","ro": "kro-daah brak nih ro-<b>haek</b>"},{"en": "I’ll pay in riel.","kh": "ខ្ញុំបង់ជារៀល","ro": "khnyom bong chie <b>riel</b>"},{"en": "You gave me the wrong change.","kh": "អ្នកអាប់លុយខុស","ro": "neak ap luy <b>khoh</b>"}],"tips": [{"label": "The 4,000 Rule","html": "The rate is pegged at roughly <b>4,000 riel to one dollar</b> and barely moves, so the arithmetic is easy: 2,000 riel is fifty cents, 10,000 riel is $2.50. Dollars handle the large amounts, riel handles everything under a dollar — there are no US coins in circulation at all. Torn or ink-marked dollar bills are routinely refused, so inspect the notes you are given <em>before</em> you walk away.","culture": false}],"goal": "Two currencies, one wallet. Understand the exchange and you stop losing small amounts all day long.","ch": 3},
{"n": 38,"title": "Bank & ATM Problems","titleKm": "បញ្ហាធនាគារ និងម៉ាស៊ីនអេធីអឹម","scene": "The machine swallowed your card, or refuses to pay. Go inside and explain it in five sentences.","dialogue": [{"who": "You","kh": "សូមទោស ម៉ាស៊ីនលេបកាតខ្ញុំ។","ro": "som toh, maa-sin <b>LEIP</b> kaat khnyom.","en": "Excuse me, the machine swallowed my card."},{"who": "Teller","kh": "សុំមើលលិខិតឆ្លងដែនបន្តិច។","ro": "som meul li-khet <b>CHHLONG</b>-daen bon-tech.","en": "May I see your passport?"},{"who": "You","kh": "នេះបាទ។ ខ្ញុំដកលុយមិនបាន។","ro": "nih baat. khnyom <b>DOK</b> luy min baan.","en": "Here. I couldn’t withdraw money."},{"who": "Teller","kh": "សុំចាំម្ភៃនាទី។","ro": "som cham <b>MPHEY</b> nie-ti.","en": "Please wait twenty minutes."},{"who": "You","kh": "គិតកម្រៃប៉ុន្មាន?","ro": "ket kom-<b>RAI</b> pon-man?","en": "How much is the fee?"}],"sayit": "<span class=\"kh\">ដក</span> <span class=\"ro\">(dok)</span> is “to withdraw” and <span class=\"kh\">ដាក់</span> <span class=\"ro\">(dak)</span> is “to deposit / put in”. One vowel apart, opposite meanings — worth drilling before you stand at a counter.","phrases": [{"en": "Bank","kh": "ធនាគារ","ro": "thie-nie-<b>kie</b>"},{"en": "I want to withdraw money.","kh": "ខ្ញុំចង់ដកលុយ","ro": "khnyom chong <b>dok</b> luy"},{"en": "The machine took my card.","kh": "ម៉ាស៊ីនលេបកាតខ្ញុំ","ro": "maa-sin <b>leip</b> kaat khnyom"},{"en": "The ATM is out of order.","kh": "ម៉ាស៊ីនខូច","ro": "maa-sin <b>khouch</b>"},{"en": "How much is the fee?","kh": "គិតកម្រៃប៉ុន្មាន?","ro": "ket kom-<b>rai</b> pon-man?"},{"en": "I want to open an account.","kh": "ខ្ញុំចង់បើកគណនី","ro": "khnyom chong baeuk ko-na-<b>nii</b>"},{"en": "Transfer money","kh": "ផ្ទេរប្រាក់","ro": "phtei <b>brak</b>"},{"en": "My card doesn’t work.","kh": "កាតខ្ញុំប្រើមិនបាន","ro": "kaat khnyom braeu min <b>baan</b>"}],"tips": [{"label": "Withdraw Dollars, Not Riel","html": "Most Cambodian ATMs let you choose the currency. Take <b>dollars</b> — riel withdrawals come out in large notes that small shops cannot break. Machines also charge a flat fee of around $4 to $5 per withdrawal regardless of amount, so take out more, less often. Choose an ATM inside a bank branch during opening hours: if it eats your card at 9 p.m. on a Friday, nobody can open it until Monday.","culture": false}],"goal": "The machine swallowed your card, or refuses to pay. Go inside and explain it in five sentences.","ch": 3},
{"n": 39,"title": "SIM Cards & Top-Up","titleKm": "ស៊ីមកាត និងការបញ្ចូលទឹកប្រាក់","scene": "A local SIM costs a couple of dollars and changes everything. Buy it from a shop, not a street table.","dialogue": [{"who": "You","kh": "ខ្ញុំចង់ទិញស៊ីមកាតមួយ។","ro": "khnyom chong tinh <b>SIM</b>-kaat muoy.","en": "I’d like to buy a SIM card."},{"who": "Staff","kh": "សុំលិខិតឆ្លងដែនផង។","ro": "som li-khet <b>CHHLONG</b>-daen phong.","en": "Your passport, please."},{"who": "You","kh": "មានកញ្ចប់អ៊ីនធឺណិតទេ?","ro": "mien kon-chop in-thoe-<b>NET</b> tei?","en": "Do you have an internet package?"},{"who": "Staff","kh": "មួយខែប្រាំដុល្លារ។","ro": "muoy khae <b>PRAM</b> dol-laa.","en": "Five dollars a month."},{"who": "You","kh": "សុំបញ្ចូលទឹកប្រាក់ដប់ដុល្លារ។","ro": "som banh-<b>CHOUL</b> tuk-brak dop dol-laa.","en": "Please top up ten dollars."}],"sayit": "Topping up is <span class=\"kh\">បញ្ចូលទឹកប្រាក់</span> <span class=\"ro\">(banh-choul tuk-brak)</span> — literally “pour in water-money”. Shops with a phone-company sign outside will do it in fifteen seconds.","phrases": [{"en": "SIM card","kh": "ស៊ីមកាត","ro": "<b>sim</b>-kaat"},{"en": "Please top up …","kh": "សុំបញ្ចូលទឹកប្រាក់ …","ro": "som banh-<b>choul</b> tuk-brak …"},{"en": "Internet package","kh": "កញ្ចប់អ៊ីនធឺណិត","ro": "kon-chop in-thoe-<b>net</b>"},{"en": "How many gigabytes?","kh": "ប៉ុន្មានជីកា?","ro": "pon-man <b>chii-kaa</b>?"},{"en": "My phone number is …","kh": "លេខទូរស័ព្ទខ្ញុំគឺ …","ro": "leik tuu-ra-<b>sap</b> khnyom keu …"},{"en": "There’s no signal.","kh": "គ្មានសេវាទេ","ro": "kmien <b>sei-vie</b> tei"},{"en": "The internet is slow.","kh": "អ៊ីនធឺណិតយឺត","ro": "in-thoe-net <b>yoeut</b>"},{"en": "What’s the Wi-Fi password?","kh": "លេខសម្ងាត់វ៉ាយហ្វាយអ្វី?","ro": "leik som-<b>ngat</b> wai-fai a-vei?"}],"tips": [{"label": "Buy It in the Shop, Not the Street","html": "SIM registration is legally tied to a passport, and a card sold pre-registered under a stranger’s name can be cut off without warning. Go to a branded Smart, Cellcard or Metfone shop, hand over your passport, and have them register it to <b>you</b>. Data is extremely cheap by international standards — a few dollars buys a generous monthly package — and coverage is good in towns, patchy on rural roads.","culture": false}],"goal": "A local SIM costs a couple of dollars and changes everything. Buy it from a shop, not a street table.","ch": 3},
{"n": 40,"title": "Returns & Exchanges","titleKm": "ការប្ដូរ និងសងទំនិញវិញ","scene": "Refunds are rare; exchanges are usually possible. Keep the receipt and go back quickly.","dialogue": [{"who": "You","kh": "ខ្ញុំចង់ប្ដូរអាវនេះ។","ro": "khnyom chong <b>BDO</b> aav nih.","en": "I’d like to exchange this shirt."},{"who": "Staff","kh": "មានបង្កាន់ដៃទេ?","ro": "mien bong-<b>KAN</b>-dai tei?","en": "Do you have the receipt?"},{"who": "You","kh": "មាន នេះបាទ។ វាតូចពេក។","ro": "mien, nih baat. vie <b>TOUCH</b> peik.","en": "Yes, here. It’s too small."},{"who": "Staff","kh": "ប្ដូរបាន តែសងលុយវិញមិនបានទេ។","ro": "<b>BDO</b> baan, tae song luy vinh min baan tei.","en": "Exchange yes, but no refund."},{"who": "You","kh": "អញ្ចឹងសុំធំជាងនេះ។","ro": "an-choeng som <b>THOM</b> chieng nih.","en": "Then a bigger one, please."}],"sayit": "<span class=\"kh\">ប្ដូរ</span> <span class=\"ro\">(bdo)</span> is “to exchange”; <span class=\"kh\">សងលុយវិញ</span> <span class=\"ro\">(song luy vinh)</span> is “to give the money back”. Ask for the first — the second rarely exists here.","phrases": [{"en": "I’d like to exchange this.","kh": "ខ្ញុំចង់ប្ដូរវា","ro": "khnyom chong <b>bdo</b> vie"},{"en": "Receipt","kh": "បង្កាន់ដៃ","ro": "bong-<b>kan</b>-dai"},{"en": "Can I have a refund?","kh": "សងលុយវិញបានទេ?","ro": "<b>song</b> luy vinh baan tei?"},{"en": "It’s broken / faulty.","kh": "វាខូច","ro": "vie <b>khouch</b>"},{"en": "It’s too small / too big.","kh": "តូចពេក / ធំពេក","ro": "<b>touch</b> peik / <b>thom</b> peik"},{"en": "I bought it yesterday.","kh": "ខ្ញុំទិញកាលពីម្សិលមិញ","ro": "khnyom tinh kaal-pii msel-<b>minh</b>"},{"en": "Is there a guarantee?","kh": "មានធានាទេ?","ro": "mien <b>thie-nie</b> tei?"},{"en": "Could you repair it?","kh": "ជួសជុលបានទេ?","ro": "chuoh-<b>chul</b> baan tei?"}],"tips": [{"label": "Test It Before You Leave","html": "There is no legal right to return goods you simply changed your mind about, and most small shops operate on “sold is sold”. So <b>test everything at the counter</b>: plug in the charger, switch on the fan, check both shoes, unfold the whole garment. Electronics from proper stores carry a genuine <span class=\"kh\">ធានា</span> <span class=\"ro\">(thie-nie, guarantee)</span> — keep that slip somewhere safe, because without it repairs are charged in full.","culture": false}],"goal": "Refunds are rare; exchanges are usually possible. Keep the receipt and go back quickly.","ch": 3},
{"n": 41,"title": "Checking In","titleKm": "ការចុះឈ្មោះចូលស្នាក់នៅ","scene": "Arriving at a guesthouse with no booking. Ask to see the room before you agree to anything.","dialogue": [{"who": "You","kh": "មានបន្ទប់ទំនេរទេ?","ro": "mien bon-<b>TUP</b> tum-nei tei?","en": "Do you have a free room?"},{"who": "Staff","kh": "មាន បាទ។ ស្នាក់ប៉ុន្មានយប់?","ro": "<b>MIEN</b>, baat. snak pon-man yub?","en": "Yes. How many nights?"},{"who": "You","kh": "បីយប់។ មួយយប់ថ្លៃប៉ុន្មាន?","ro": "bei yub. muoy yub <b>THLAI</b> pon-man?","en": "Three nights. How much per night?"},{"who": "Staff","kh": "ដប់ប្រាំដុល្លារ មានម៉ាស៊ីនត្រជាក់។","ro": "dop-pram dol-laa, mien maa-sin tro-<b>CHEAK</b>.","en": "Fifteen dollars, with air conditioning."},{"who": "You","kh": "សុំមើលបន្ទប់សិនបានទេ?","ro": "som <b>MEUL</b> bon-tup sen baan tei?","en": "May I see the room first?"}],"sayit": "<span class=\"kh\">សិន</span> <span class=\"ro\">(sen)</span> at the end of a request means “first, before anything else”. <span class=\"ro\">som meul … sen</span> is the polite way to inspect before committing.","phrases": [{"en": "Do you have a free room?","kh": "មានបន្ទប់ទំនេរទេ?","ro": "mien bon-<b>tup</b> tum-nei tei?"},{"en": "How much per night?","kh": "មួយយប់ថ្លៃប៉ុន្មាន?","ro": "muoy yub <b>thlai</b> pon-man?"},{"en": "Three nights","kh": "បីយប់","ro": "bei <b>yub</b>"},{"en": "I have a booking.","kh": "ខ្ញុំបានកក់រួចហើយ","ro": "khnyom baan <b>kok</b> ruoch haoy"},{"en": "May I see the room first?","kh": "សុំមើលបន្ទប់សិនបានទេ?","ro": "som <b>meul</b> bon-tup sen baan tei?"},{"en": "Is breakfast included?","kh": "មានអាហារពេលព្រឹកទេ?","ro": "mien aa-haa peil <b>pruk</b> tei?"},{"en": "Air-con / fan","kh": "ម៉ាស៊ីនត្រជាក់ / កង្ហារ","ro": "maa-sin tro-<b>cheak</b> / kong-<b>haa</b>"},{"en": "The key, please.","kh": "សុំសោបន្ទប់","ro": "som <b>sao</b> bon-tup"}],"tips": [{"label": "Always Ask to See It","html": "Inspecting the room before agreeing is completely normal and nobody is offended by it — guesthouses expect it. Check three things: that the <b>air conditioning actually blows cold</b>, that hot water reaches the shower, and that the window does not open onto a karaoke bar. Rooms on the same floor at the same price often differ enormously, and asking to see a second one usually gets you the better of the two.","culture": false}],"goal": "Arriving at a guesthouse with no booking. Ask to see the room before you agree to anything.","ch": 4},
{"n": 42,"title": "Hotel Requests & Problems","titleKm": "ការស្នើសុំ និងបញ្ហាបន្ទប់","scene": "Something is not working. Report it at reception in one sentence and it is usually fixed within the hour.","dialogue": [{"who": "You","kh": "បន្ទប់ខ្ញុំគ្មានទឹកក្ដៅទេ។","ro": "bon-tup khnyom kmien tuk-<b>KDAV</b> tei.","en": "My room has no hot water."},{"who": "Staff","kh": "សុំទោស បន្ទប់លេខប៉ុន្មាន?","ro": "som toh, bon-tup <b>LEIK</b> pon-man?","en": "Sorry, which room number?"},{"who": "You","kh": "លេខម្ភៃបី។ ហើយវ៉ាយហ្វាយក៏ខូចដែរ។","ro": "leik <b>MPHEY</b>-bei. haoy wai-fai kâ khouch dae.","en": "Twenty-three. And the Wi-Fi is broken too."},{"who": "You","kh": "សុំខ្នើយបន្ថែមមួយផង។","ro": "som <b>KHNOEY</b> bon-thaem muoy phong.","en": "And one extra pillow, please."},{"who": "Staff","kh": "បាទ ខ្ញុំឡើងទៅឥឡូវ។","ro": "baat, khnyom <b>LAEUNG</b> teuv eu-lov.","en": "Yes, I’ll come up now."}],"sayit": "<span class=\"kh\">គ្មាន … ទេ</span> <span class=\"ro\">(kmien … tei)</span> means “there isn’t any …”. It is the negative twin of <span class=\"ro\">mien … tei?</span> and reports a missing thing without blaming anybody.","phrases": [{"en": "There’s no hot water.","kh": "គ្មានទឹកក្ដៅទេ","ro": "kmien tuk-<b>kdav</b> tei"},{"en": "The air-con isn’t working.","kh": "ម៉ាស៊ីនត្រជាក់ខូច","ro": "maa-sin tro-cheak <b>khouch</b>"},{"en": "Extra pillow / blanket","kh": "ខ្នើយ / ភួយ បន្ថែម","ro": "<b>khnoey</b> / <b>phuoy</b> bon-thaem"},{"en": "Please clean the room.","kh": "សូមសម្អាតបន្ទប់","ro": "som som-<b>at</b> bon-tup"},{"en": "Towel / soap","kh": "កន្សែង / សាប៊ូ","ro": "kon-<b>saeng</b> / saa-<b>buu</b>"},{"en": "The room is too noisy.","kh": "បន្ទប់ថ្លង់ពេក","ro": "bon-tup <b>thlong</b> peik"},{"en": "Could I change rooms?","kh": "ប្ដូរបន្ទប់បានទេ?","ro": "<b>bdo</b> bon-tup baan tei?"},{"en": "There are mosquitoes.","kh": "មានមូសច្រើន","ro": "mien <b>muuh</b> chraen"}],"tips": [{"label": "Report It the Same Day","html": "Saying nothing and then complaining at checkout gets you nowhere; reporting a fault immediately almost always gets it fixed or gets you moved. Keep the tone light — a problem raised with a smile is a favour asked, and a favour asked is a favour granted. Power cuts are frequent in the provinces, so a guesthouse with a <span class=\"kh\">ម៉ាស៊ីនភ្លើង</span> <span class=\"ro\">(maa-sin phleung, generator)</span> is worth a dollar or two more per night.","culture": false}],"goal": "Something is not working. Report it at reception in one sentence and it is usually fixed within the hour.","ch": 4},
{"n": 43,"title": "Checking Out","titleKm": "ការចេញពីបន្ទប់","scene": "Leaving early, storing a bag, and checking the bill for things you did not drink.","dialogue": [{"who": "You","kh": "ខ្ញុំចង់ចេញថ្ងៃនេះ។","ro": "khnyom chong <b>CHENH</b> thngai nih.","en": "I’d like to check out today."},{"who": "Staff","kh": "សុំសោបន្ទប់ផង។","ro": "som <b>SAO</b> bon-tup phong.","en": "The room key, please."},{"who": "You","kh": "សុំមើលវិក្កយបត្របន្តិច។","ro": "som meul vik-<b>KAY</b>-bot bon-tech.","en": "May I see the bill?"},{"who": "You","kh": "ខ្ញុំមិនបានញ៉ាំអ្វីពីទូទេ។","ro": "khnyom min baan nyam a-vei pii <b>TUU</b> tei.","en": "I didn’t take anything from the fridge."},{"who": "You","kh": "ផ្ញើកាបូបទុកបានទេ?","ro": "<b>PHNHAEU</b> kaa-boub tuk baan tei?","en": "Can I leave my bag here?"}],"sayit": "<span class=\"kh\">ផ្ញើ</span> <span class=\"ro\">(phnhaeu)</span> means “to entrust / leave in someone’s care” — used for luggage, parcels and money alike. It implies you will come back for it.","phrases": [{"en": "I’d like to check out.","kh": "ខ្ញុំចង់ចេញ","ro": "khnyom chong <b>chenh</b>"},{"en": "May I see the bill?","kh": "សុំមើលវិក្កយបត្រ","ro": "som meul vik-<b>kay</b>-bot"},{"en": "What time is checkout?","kh": "ចេញម៉ោងប៉ុន្មាន?","ro": "<b>chenh</b> maong pon-man?"},{"en": "Can I stay one more night?","kh": "ស្នាក់មួយយប់ទៀតបានទេ?","ro": "snak muoy yub <b>tiet</b> baan tei?"},{"en": "Can I leave my bag here?","kh": "ផ្ញើកាបូបទុកបានទេ?","ro": "<b>phnhaeu</b> kaa-boub tuk baan tei?"},{"en": "Could you call me a tuk-tuk?","kh": "ជួយហៅតុកតុកឲ្យខ្ញុំផង","ro": "chuoy <b>hav</b> tuk-tuk aoy khnyom phong"},{"en": "I left something in the room.","kh": "ខ្ញុំភ្លេចរបស់ក្នុងបន្ទប់","ro": "khnyom <b>phlech</b> ro-boh knong bon-tup"},{"en": "Thank you for everything.","kh": "អរគុណសម្រាប់អ្វីៗទាំងអស់","ro": "or-kun som-rap a-vei-vei <b>teang</b>-oh"}],"tips": [{"label": "Luggage Storage Is Free","html": "Nearly every guesthouse will hold your bag for the day after checkout at no charge, which turns an awkward afternoon before a night bus into a free one. Ask with <span class=\"ro\">phnhaeu kaa-boub tuk baan tei?</span> and take anything valuable with you. Tipping is not expected in Cambodian hotels, but leaving a couple of dollars for the cleaner is quietly appreciated and very unusual.","culture": false}],"goal": "Leaving early, storing a bag, and checking the bill for things you did not drink.","ch": 4},
{"n": 44,"title": "Apartment Hunting","titleKm": "ការរកផ្ទះជួល","scene": "Viewing a flat. Ask about the rent, the deposit and — most importantly — the electricity rate.","dialogue": [{"who": "You","kh": "ថ្លៃឈ្នួលមួយខែប៉ុន្មាន?","ro": "thlai <b>CHHNUOL</b> muoy khae pon-man?","en": "How much is the monthly rent?"},{"who": "Agent","kh": "បីរយដុល្លារ មិនរាប់ភ្លើងទឹក។","ro": "bei roy dol-laa, min <b>ROAB</b> phleung tuk.","en": "Three hundred dollars, not including utilities."},{"who": "You","kh": "ភ្លើងមួយគីឡូវ៉ាត់ប៉ុន្មាន?","ro": "<b>PHLEUNG</b> muoy ki-lou-woat pon-man?","en": "How much per unit of electricity?"},{"who": "Agent","kh": "មួយពាន់រៀល។ កក់ប្រាក់ពីរខែ។","ro": "muoy poan riel. <b>KOK</b> brak pii khae.","en": "One thousand riel. Two months’ deposit."},{"who": "You","kh": "មានកិច្ចសន្យាជាភាសាអង់គ្លេសទេ?","ro": "mien kech-son-<b>YIE</b> chie phie-saa ong-gleih tei?","en": "Is there a contract in English?"}],"sayit": "<span class=\"kh\">មិនរាប់</span> <span class=\"ro\">(min roab)</span> means “not counting / not including”. When a landlord says it about <span class=\"ro\">phleung tuk</span>, ask the unit rate immediately.","phrases": [{"en": "How much is the rent?","kh": "ថ្លៃឈ្នួលប៉ុន្មាន?","ro": "thlai <b>chhnuol</b> pon-man?"},{"en": "Deposit","kh": "កក់ប្រាក់","ro": "<b>kok</b> brak"},{"en": "Not including utilities","kh": "មិនរាប់ភ្លើងទឹក","ro": "min <b>roab</b> phleung tuk"},{"en": "How many bedrooms?","kh": "មានបន្ទប់គេងប៉ុន្មាន?","ro": "mien bon-tup <b>keing</b> pon-man?"},{"en": "Is it furnished?","kh": "មានគ្រឿងសង្ហារិមទេ?","ro": "mien kroeung song-<b>haa</b>-rim tei?"},{"en": "Contract","kh": "កិច្ចសន្យា","ro": "kech-son-<b>yie</b>"},{"en": "Can I move in next month?","kh": "ចូលនៅខែក្រោយបានទេ?","ro": "<b>choul</b> nov khae kraoy baan tei?"},{"en": "Is parking included?","kh": "មានកន្លែងចតទេ?","ro": "mien kon-laeng <b>chot</b> tei?"}],"tips": [{"label": "The Electricity Rate Is the Real Rent","html": "Landlords in Cambodia commonly resell electricity at well above the state rate, and with air conditioning running you can add a hundred dollars a month without noticing. Always ask the <b>price per unit</b> and compare it against the official EDC tariff before signing. Two months’ deposit is standard, and getting it back at the end depends almost entirely on the relationship you build — so photograph the whole flat on the day you move in.","culture": false}],"goal": "Viewing a flat. Ask about the rent, the deposit and — most importantly — the electricity rate.","ch": 4},
{"n": 45,"title": "Talking to the Landlord","titleKm": "ការនិយាយជាមួយម្ចាស់ផ្ទះ","scene": "Rent day, a broken tap, and a request. Keep it warm — your landlord is also your neighbour.","dialogue": [{"who": "You","kh": "នេះថ្លៃឈ្នួលខែនេះ បង។","ro": "nih thlai <b>CHHNUOL</b> khae nih, bong.","en": "Here’s this month’s rent."},{"who": "Landlord","kh": "អរគុណ។ មានបញ្ហាអ្វីទេ?","ro": "or-kun. mien bon-<b>HAA</b> a-vei tei?","en": "Thank you. Any problems?"},{"who": "You","kh": "ក្បាលទឹកក្នុងបន្ទប់ទឹកលេច។","ro": "kbaal <b>TUK</b> knong bon-tup-tuk leich.","en": "The tap in the bathroom is leaking."},{"who": "Landlord","kh": "ខ្ញុំនឹងហៅជាងថ្ងៃស្អែក។","ro": "khnyom neung <b>HAV</b> chieng thngai sa-aek.","en": "I’ll call a repairman tomorrow."},{"who": "You","kh": "សុំបង្កាន់ដៃផង បង។","ro": "som bong-<b>KAN</b>-dai phong, bong.","en": "A receipt, please."}],"sayit": "Call your landlord <span class=\"ro\">bong</span> if they are near your age, <span class=\"ro\">om</span> if they are your parents’ generation. Getting this right shapes the entire relationship — and the relationship is what gets things repaired.","phrases": [{"en": "Landlord","kh": "ម្ចាស់ផ្ទះ","ro": "m-chah <b>phteah</b>"},{"en": "Here is this month’s rent.","kh": "នេះថ្លៃឈ្នួលខែនេះ","ro": "nih thlai <b>chhnuol</b> khae nih"},{"en": "The tap is leaking.","kh": "ក្បាលទឹកលេច","ro": "kbaal tuk <b>leich</b>"},{"en": "Could you fix it?","kh": "ជួយជួសជុលបានទេ?","ro": "chuoy chuoh-<b>chul</b> baan tei?"},{"en": "A receipt, please.","kh": "សុំបង្កាន់ដៃផង","ro": "som bong-<b>kan</b>-dai phong"},{"en": "I’ll pay a few days late.","kh": "ខ្ញុំបង់យឺតបន្តិច","ro": "khnyom bong <b>yoeut</b> bon-tech"},{"en": "I want to renew the contract.","kh": "ខ្ញុំចង់បន្តកិច្ចសន្យា","ro": "khnyom chong <b>bon-tor</b> kech-son-yie"},{"en": "I’m moving out next month.","kh": "ខ្ញុំនឹងចេញខែក្រោយ","ro": "khnyom neung <b>chenh</b> khae kraoy"}],"tips": [{"label": "Give a Month’s Notice, in Person","html": "Contracts here are often short and informally enforced, so what protects you is goodwill rather than paperwork. Announce a departure <b>a full month ahead and face to face</b>, never by message, and pay the last month rather than asking to have it taken from the deposit — that single gesture is what usually gets the deposit returned. A small gift at Khmer New Year does more for your tenancy than any clause.","culture": true}],"goal": "Rent day, a broken tap, and a request. Keep it warm — your landlord is also your neighbour.","ch": 4},
{"n": 46,"title": "Electricity, Water & Wi-Fi","titleKm": "ភ្លើង ទឹក និងអ៊ីនធឺណិត","scene": "The power is out and the bill looks wrong. Two conversations you will have more than once.","dialogue": [{"who": "You","kh": "ភ្លើងរលត់តាំងពីព្រឹក។","ro": "<b>PHLEUNG</b> ro-lot tang pii pruk.","en": "The power has been off since morning."},{"who": "Landlord","kh": "ទាំងផ្លូវនេះដាច់ភ្លើង។","ro": "teang <b>PHLOV</b> nih dach phleung.","en": "The whole street has a power cut."},{"who": "You","kh": "វិក្កយបត្រខែនេះថ្លៃជាងធម្មតា។","ro": "vik-kay-bot khae nih <b>THLAI</b> chieng thoam-ma-daa.","en": "This month’s bill is higher than usual."},{"who": "Landlord","kh": "ខ្ញុំនឹងពិនិត្យមាទ្រនិចឡើងវិញ។","ro": "khnyom neung pi-<b>NET</b> maa-tro-nech laeung vinh.","en": "I’ll check the meter again."},{"who": "You","kh": "អ៊ីនធឺណិតដាច់ជាញឹកញាប់។","ro": "in-thoe-net <b>DACH</b> chie nheuk-nheap.","en": "The internet cuts out often."}],"sayit": "<span class=\"kh\">ដាច់</span> <span class=\"ro\">(dach)</span> means “cut off” and applies to power, water, internet and roads alike: <span class=\"ro\">dach phleung</span>, <span class=\"ro\">dach tuk</span>, <span class=\"ro\">dach phlov</span>.","phrases": [{"en": "Electricity / water","kh": "ភ្លើង / ទឹក","ro": "<b>phleung</b> / <b>tuk</b>"},{"en": "The power is out.","kh": "ដាច់ភ្លើង","ro": "<b>dach</b> phleung"},{"en": "There’s no water.","kh": "គ្មានទឹកទេ","ro": "kmien <b>tuk</b> tei"},{"en": "The bill","kh": "វិក្កយបត្រ","ro": "vik-<b>kay</b>-bot"},{"en": "Meter","kh": "មាទ្រនិច","ro": "maa-tro-<b>nech</b>"},{"en": "It’s more expensive than usual.","kh": "ថ្លៃជាងធម្មតា","ro": "<b>thlai</b> chieng thoam-ma-daa"},{"en": "The internet keeps cutting out.","kh": "អ៊ីនធឺណិតដាច់ជាញឹកញាប់","ro": "in-thoe-net <b>dach</b> chie nheuk-nheap"},{"en": "When will it come back?","kh": "ពេលណាមានវិញ?","ro": "peil naa <b>mien</b> vinh?"}],"tips": [{"label": "Photograph the Meter","html": "Take a picture of the electricity meter on the day you move in and on the first of every month. It costs ten seconds and settles every billing dispute instantly, because you can show the reading rather than argue about it. Keep a torch and a power bank charged: cuts of two or three hours are ordinary, especially in the hot season when the whole city runs its air conditioning at once.","culture": false}],"goal": "The power is out and the bill looks wrong. Two conversations you will have more than once.","ch": 4},
{"n": 47,"title": "Calling a Repairman","titleKm": "ការហៅជាងជួសជុល","scene": "Something has broken. Name the thing, say it is broken, and agree the price before he starts.","dialogue": [{"who": "You","kh": "ម៉ាស៊ីនត្រជាក់ខ្ញុំខូច។","ro": "maa-sin tro-cheak khnyom <b>KHOUCH</b>.","en": "My air conditioner is broken."},{"who": "Repairman","kh": "វាមិនត្រជាក់ ឬមិនដើរ?","ro": "vie min tro-cheak reu min <b>DAEU</b>?","en": "Is it not cold, or not running at all?"},{"who": "You","kh": "ដើរ តែមិនត្រជាក់។","ro": "<b>DAEU</b>, tae min tro-cheak.","en": "It runs, but it isn’t cold."},{"who": "Repairman","kh": "ត្រូវបញ្ចូលឧស្ម័ន ម្ភៃដុល្លារ។","ro": "trov banh-choul <b>OS-MAN</b>, mphey dol-laa.","en": "It needs regassing, twenty dollars."},{"who": "You","kh": "មកបានពេលណា?","ro": "mok baan <b>PEIL</b> naa?","en": "When can you come?"}],"sayit": "<span class=\"kh\">ខូច</span> <span class=\"ro\">(khouch)</span> covers every kind of broken — machines, phones, roads, even food that has gone off. Point at the thing and say it; you will be understood.","phrases": [{"en": "It’s broken.","kh": "វាខូច","ro": "vie <b>khouch</b>"},{"en": "Repairman / technician","kh": "ជាងជួសជុល","ro": "<b>chieng</b> chuoh-chul"},{"en": "Electrician / plumber","kh": "ជាងភ្លើង / ជាងទឹក","ro": "chieng <b>phleung</b> / chieng <b>tuk</b>"},{"en": "When can you come?","kh": "មកបានពេលណា?","ro": "mok baan <b>peil</b> naa?"},{"en": "How much will it cost?","kh": "ជួសជុលអស់ប៉ុន្មាន?","ro": "chuoh-chul <b>oh</b> pon-man?"},{"en": "Can it be fixed today?","kh": "ជួសជុលថ្ងៃនេះបានទេ?","ro": "chuoh-chul thngai nih <b>baan</b> tei?"},{"en": "The toilet is blocked.","kh": "បង្គន់ស្ទះ","ro": "bong-kon <b>stoah</b>"},{"en": "Please buy the parts first.","kh": "សូមទិញគ្រឿងបន្លាស់សិន","ro": "som tinh kroeung bon-<b>lah</b> sen"}],"tips": [{"label": "Agree the Price Before He Opens It","html": "Once a machine is in pieces on your floor your negotiating position has gone. Ask <span class=\"ro\">chuoh-chul oh pon-man?</span> at the door, and ask again if he discovers a second fault. Most repairmen are found by <b>asking your neighbours</b> rather than searching online — the one who fixed the flat downstairs will come faster, charge the local rate and care about his reputation on your street.","culture": false}],"goal": "Something has broken. Name the thing, say it is broken, and agree the price before he starts.","ch": 4},
{"n": 48,"title": "Hiring a Cleaner","titleKm": "ការជួលអ្នកសម្អាតផ្ទះ","scene": "Agreeing days, hours and pay. Be clear and generous at the start; it is far easier than adjusting later.","dialogue": [{"who": "You","kh": "ខ្ញុំត្រូវការអ្នកសម្អាតផ្ទះ។","ro": "khnyom trov-kaa neak som-<b>AT</b> phteah.","en": "I need someone to clean the house."},{"who": "Cleaner","kh": "មួយអាទិត្យប៉ុន្មានដង?","ro": "muoy aa-tit pon-man <b>DONG</b>?","en": "How many times a week?"},{"who": "You","kh": "ពីរដង ថ្ងៃច័ន្ទ និងថ្ងៃសុក្រ។","ro": "<b>PII</b> dong, thngai chan ning thngai sok.","en": "Twice — Monday and Friday."},{"who": "Cleaner","kh": "មួយដងដប់ដុល្លារ បានទេ?","ro": "muoy dong <b>DOP</b> dol-laa, baan tei?","en": "Ten dollars a visit, alright?"},{"who": "You","kh": "បានហើយ។ ខ្ញុំបង់ចុងខែ។","ro": "<b>BAAN</b> haoy. khnyom bong chong khae.","en": "Agreed. I’ll pay at month’s end."}],"sayit": "Days of the week all begin with <span class=\"kh\">ថ្ងៃ</span> <span class=\"ro\">(thngai)</span>: <span class=\"ro\">thngai chan</span> Monday, <span class=\"ro\">thngai ong-kie</span> Tuesday, <span class=\"ro\">thngai sok</span> Friday, <span class=\"ro\">thngai aa-tit</span> Sunday.","phrases": [{"en": "To clean","kh": "សម្អាត","ro": "som-<b>at</b>"},{"en": "How many times a week?","kh": "មួយអាទិត្យប៉ុន្មានដង?","ro": "muoy aa-tit pon-man <b>dong</b>?"},{"en": "Monday / Friday","kh": "ថ្ងៃច័ន្ទ / ថ្ងៃសុក្រ","ro": "thngai <b>chan</b> / thngai <b>sok</b>"},{"en": "Please wash the dishes.","kh": "សូមលាងចាន","ro": "som <b>lieng</b> chaan"},{"en": "Please mop the floor.","kh": "សូមជូតឥដ្ឋ","ro": "som <b>chout</b> et"},{"en": "Don’t move these things.","kh": "កុំប៉ះរបស់ទាំងនេះ","ro": "kom <b>pah</b> ro-boh teang-nih"},{"en": "I’ll pay at the end of the month.","kh": "ខ្ញុំបង់ចុងខែ","ro": "khnyom bong <b>chong</b> khae"},{"en": "Thank you, well done.","kh": "អរគុណ ធ្វើបានល្អណាស់","ro": "or-kun, thveu baan <b>la-or</b> nas"}],"tips": [{"label": "Pay Well and Pay on Time","html": "Domestic work is often the household’s main income, and a day’s pay missed matters. Agree the rate openly at the start, pay on the day you promised, and add a month’s wage as a bonus at <b>Khmer New Year</b> — this is expected of good employers, not optional generosity. Praise directly and correct gently; criticism given in front of anyone else causes real loss of face and is rarely recovered from.","culture": true}],"goal": "Agreeing days, hours and pay. Be clear and generous at the start; it is far easier than adjusting later.","ch": 4},
{"n": 49,"title": "Neighbours & Security","titleKm": "អ្នកជិតខាង និងសន្តិសុខ","scene": "Introducing yourself to the people on your street, and to the guard who watches it at night.","dialogue": [{"who": "You","kh": "ជម្រាបសួរ ខ្ញុំទើបមកនៅថ្មី។","ro": "chom-riep suor, khnyom teub mok nov <b>THMEI</b>.","en": "Hello, I’ve just moved in."},{"who": "Neighbour","kh": "អូ! សូមស្វាគមន៍ បង។","ro": "ouh! som svie-<b>KOM</b>, bong.","en": "Oh! Welcome."},{"who": "You","kh": "ខ្ញុំនៅផ្ទះលេខដប់ពីរ។","ro": "khnyom nov phteah leik <b>DOP</b>-pii.","en": "I live at number twelve."},{"who": "You","kh": "ឆ្មាំបិទច្រកទ្វារម៉ោងប៉ុន្មាន?","ro": "<b>CHHMAM</b> bet chrok-tvie maong pon-man?","en": "What time does the guard lock the gate?"},{"who": "Neighbour","kh": "ម៉ោងដប់មួយយប់។","ro": "maong <b>DOP</b>-muoy yub.","en": "Eleven at night."}],"sayit": "<span class=\"kh\">សូមស្វាគមន៍</span> <span class=\"ro\">(som svie-kom)</span> is “welcome”. You will hear it constantly — at doors, at shops, and on every hotel sign in the country.","phrases": [{"en": "Neighbour","kh": "អ្នកជិតខាង","ro": "neak <b>chit</b>-khang"},{"en": "I’ve just moved in.","kh": "ខ្ញុំទើបមកនៅថ្មី","ro": "khnyom teub mok nov <b>thmei</b>"},{"en": "Welcome!","kh": "សូមស្វាគមន៍","ro": "som svie-<b>kom</b>"},{"en": "Security guard","kh": "ឆ្មាំ","ro": "<b>chhmam</b>"},{"en": "Gate / lock","kh": "ច្រកទ្វារ / សោ","ro": "chrok-<b>tvie</b> / <b>sao</b>"},{"en": "Please keep the noise down.","kh": "សូមបន្ថយសំឡេងបន្តិច","ro": "som bon-<b>thoy</b> som-leng bon-tech"},{"en": "I’ll be away a few days.","kh": "ខ្ញុំទៅឆ្ងាយពីរបីថ្ងៃ","ro": "khnyom teuv <b>chhngay</b> pii-bei thngai"},{"en": "Could you keep an eye on my house?","kh": "ជួយមើលផ្ទះខ្ញុំផង","ro": "chuoy <b>meul</b> phteah khnyom phong"}],"tips": [{"label": "Your Street Is Your Security System","html": "Introduce yourself to the neighbours and the <span class=\"ro\">chhmam</span> in your first week, and greet them every single day afterwards. On a Cambodian street, people watch out for those they know by name — the guard who has been handed a cold drink on a hot afternoon will notice a stranger at your gate. Weddings and funerals on the street are loud and go on for days; complaining about them marks you out, while attending for ten minutes makes you a neighbour.","culture": true}],"goal": "Introducing yourself to the people on your street, and to the guard who watches it at night.","ch": 4},
{"n": 50,"title": "Laundry","titleKm": "ការបោកគក់","scene": "Laundry is sold by the kilo and comes back folded. Say what must not go in the dryer.","dialogue": [{"who": "You","kh": "បោកគក់មួយគីឡូប៉ុន្មាន?","ro": "baok-kok muoy ki-<b>LOU</b> pon-man?","en": "How much per kilo for washing?"},{"who": "Staff","kh": "មួយពាន់រៀល រួមទាំងអ៊ុត។","ro": "muoy poan riel, ruom teang <b>UT</b>.","en": "One thousand riel, ironing included."},{"who": "You","kh": "ពេលណាបានយក?","ro": "peil naa baan <b>YOK</b>?","en": "When can I collect it?"},{"who": "Staff","kh": "ថ្ងៃស្អែករសៀល។","ro": "thngai sa-aek ro-<b>SIEL</b>.","en": "Tomorrow afternoon."},{"who": "You","kh": "អាវនេះកុំដាក់ម៉ាស៊ីនសម្ងួត។","ro": "aav nih kom dak maa-sin som-<b>NGUOT</b>.","en": "Don’t put this shirt in the dryer."}],"sayit": "<span class=\"kh\">បោកគក់</span> <span class=\"ro\">(baok-kok)</span> is the everyday word for doing laundry. Shops advertise it on hand-painted signs alongside the price per kilo.","phrases": [{"en": "Laundry / washing","kh": "បោកគក់","ro": "<b>baok</b>-kok"},{"en": "How much per kilo?","kh": "មួយគីឡូប៉ុន្មាន?","ro": "muoy ki-<b>lou</b> pon-man?"},{"en": "Ironing","kh": "អ៊ុត","ro": "<b>ut</b>"},{"en": "When can I collect it?","kh": "ពេលណាបានយក?","ro": "peil naa baan <b>yok</b>?"},{"en": "Not in the dryer, please.","kh": "កុំដាក់ម៉ាស៊ីនសម្ងួត","ro": "kom dak maa-sin som-<b>nguot</b>"},{"en": "Wash separately, please.","kh": "សូមបោកដាច់ដោយឡែក","ro": "som baok <b>dach</b> daoy-laek"},{"en": "A shirt is missing.","kh": "អាវខ្ញុំបាត់មួយ","ro": "aav khnyom <b>bat</b> muoy"},{"en": "Can you do it today?","kh": "ធ្វើថ្ងៃនេះបានទេ?","ro": "thveu thngai nih <b>baan</b> tei?"}],"tips": [{"label": "Count It In and Count It Out","html": "Laundry shops wash several households together, so socks and single shirts do migrate. Count the items as you hand them over — the staff will happily count with you, and it is entirely normal — then count them again on collection. In the rainy season, clothes may come back not quite dry and smelling of it; a shop with a proper <span class=\"kh\">ម៉ាស៊ីនសម្ងួត</span> <span class=\"ro\">(maa-sin som-nguot, dryer)</span> is worth walking an extra street for.","culture": false}],"goal": "Laundry is sold by the kilo and comes back folded. Say what must not go in the dryer.","ch": 4},
{"n": 51,"title": "Describing Symptoms","titleKm": "ការរៀបរាប់រោគសញ្ញា","scene": "One verb — <em>chheu</em> — plus a body part covers most of what you need to say when you are unwell.","dialogue": [{"who": "Nurse","kh": "ឈឺត្រង់ណា?","ro": "<b>CHHEU</b> trong naa?","en": "Where does it hurt?"},{"who": "You","kh": "ខ្ញុំឈឺពោះ និងក្ដៅខ្លួន។","ro": "khnyom chheu <b>POH</b> ning kdav kluon.","en": "My stomach hurts and I have a fever."},{"who": "Nurse","kh": "ចាប់ផ្ដើមពីពេលណា?","ro": "chap-<b>PHDAEUM</b> pii peil naa?","en": "When did it start?"},{"who": "You","kh": "តាំងពីម្សិលមិញ។ ខ្ញុំក៏ក្អួតដែរ។","ro": "tang pii msel-minh. khnyom kâ <b>KA-UOT</b> dae.","en": "Since yesterday. I’ve been vomiting too."},{"who": "You","kh": "ខ្ញុំវិលមុខពេលក្រោកឈរ។","ro": "khnyom <b>VIL</b> muk peil kraok chho.","en": "I feel dizzy when I stand up."}],"sayit": "<span class=\"kh\">ក្ដៅខ្លួន</span> <span class=\"ro\">(kdav kluon)</span> is literally “hot body” — a fever. Do not say <span class=\"ro\">khnyom kdav</span> alone; that just means you are feeling warm.","phrases": [{"en": "Where does it hurt?","kh": "ឈឺត្រង់ណា?","ro": "<b>chheu</b> trong naa?"},{"en": "Head / stomach / throat","kh": "ក្បាល / ពោះ / បំពង់ក","ro": "<b>kbaal</b> / <b>poh</b> / bom-pong-<b>kor</b>"},{"en": "I have a fever.","kh": "ខ្ញុំក្ដៅខ្លួន","ro": "khnyom <b>kdav</b> kluon"},{"en": "I’m coughing.","kh": "ខ្ញុំក្អក","ro": "khnyom <b>ka-ak</b>"},{"en": "I’ve been vomiting.","kh": "ខ្ញុំក្អួត","ro": "khnyom <b>ka-uot</b>"},{"en": "I feel dizzy.","kh": "ខ្ញុំវិលមុខ","ro": "khnyom <b>vil</b> muk"},{"en": "I have a cold / flu.","kh": "ខ្ញុំផ្ដាសាយ","ro": "khnyom phdaa-<b>say</b>"},{"en": "Since yesterday","kh": "តាំងពីម្សិលមិញ","ro": "tang pii msel-<b>minh</b>"}],"tips": [{"label": "Fever Plus Aches Means a Blood Test","html": "Dengue is common across Cambodia and its early signs look exactly like flu: high fever, headache behind the eyes, deep muscle ache. If a fever lasts more than <b>two days</b>, go to a clinic and ask for a blood test rather than taking more paracetamol — and avoid ibuprofen or aspirin, which are dangerous in dengue. Say <span class=\"ro\">khnyom chong pinet chhiem</span>: “I want a blood test.”","culture": false}],"goal": "One verb — chheu — plus a body part covers most of what you need to say when you are unwell.","ch": 5},
{"n": 52,"title": "At the Doctor","titleKm": "នៅជួបគ្រូពេទ្យ","scene": "Registering at a clinic, being examined, and asking the two questions that matter most.","dialogue": [{"who": "You","kh": "ខ្ញុំចង់ជួបគ្រូពេទ្យ។","ro": "khnyom chong chuop kruu-<b>PEIT</b>.","en": "I’d like to see a doctor."},{"who": "Doctor","kh": "សុំពិនិត្យបន្តិច។ ដកដង្ហើមវែងៗ។","ro": "som pi-<b>NET</b> bon-tech. dok dong-haeum veng-veng.","en": "Let me examine you. Breathe deeply."},{"who": "You","kh": "តើខ្ញុំកើតជំងឺអ្វី?","ro": "tae khnyom kaeut chum-<b>NGEU</b> a-vei?","en": "What illness do I have?"},{"who": "Doctor","kh": "ត្រូវពិនិត្យឈាមសិន។","ro": "trov pi-net <b>CHHIEM</b> sen.","en": "We need a blood test first."},{"who": "You","kh": "អស់ថ្លៃប៉ុន្មាន? មានធានារ៉ាប់រងទេ?","ro": "oh <b>THLAI</b> pon-man? mien thie-nie-rap-rong tei?","en": "How much will it cost? Do you take insurance?"}],"sayit": "<span class=\"kh\">គ្រូពេទ្យ</span> <span class=\"ro\">(kruu-peit)</span> is a doctor; <span class=\"kh\">មន្ទីរពេទ្យ</span> <span class=\"ro\">(mon-ti-peit)</span> is a hospital. Both contain <span class=\"ro\">peit</span>, the root for medicine.","phrases": [{"en": "Doctor / hospital","kh": "គ្រូពេទ្យ / មន្ទីរពេទ្យ","ro": "kruu-<b>peit</b> / mon-ti-<b>peit</b>"},{"en": "I’d like to see a doctor.","kh": "ខ្ញុំចង់ជួបគ្រូពេទ្យ","ro": "khnyom chong <b>chuop</b> kruu-peit"},{"en": "Blood test","kh": "ពិនិត្យឈាម","ro": "pi-net <b>chhiem</b>"},{"en": "Injection","kh": "ចាក់ថ្នាំ","ro": "<b>chak</b> thnam"},{"en": "I’m allergic to penicillin.","kh": "ខ្ញុំមានអាឡែស៊ីនឹងប៉េនីស៊ីលីន","ro": "khnyom mien aa-lae-<b>sii</b> neung pei-ni-si-lin"},{"en": "Do you take insurance?","kh": "មានធានារ៉ាប់រងទេ?","ro": "mien thie-nie-<b>rap</b>-rong tei?"},{"en": "Is it serious?","kh": "ធ្ងន់ធ្ងរទេ?","ro": "thngon-<b>thngo</b> tei?"},{"en": "I need a medical certificate.","kh": "ខ្ញុំត្រូវការលិខិតបញ្ជាក់សុខភាព","ro": "khnyom trov-kaa li-khet ban-<b>cheak</b> sok-kha-phiep"}],"tips": [{"label": "Know Your Nearest Good Clinic Now","html": "Find out today — before you need it — which clinic in your town handles foreigners, and save the number. In Phnom Penh and Siem Reap there are international clinics with English-speaking doctors; in the provinces, standards vary a great deal and serious cases are often evacuated to the capital or to Bangkok. If you are staying long term, <b>medical insurance that covers evacuation</b> is the single most valuable thing you can buy.","culture": false}],"goal": "Registering at a clinic, being examined, and asking the two questions that matter most.","ch": 5},
{"n": 53,"title": "At the Dentist","titleKm": "នៅពេទ្យធ្មេញ","scene": "Dentistry here is good and inexpensive. Point at the tooth and say how long it has hurt.","dialogue": [{"who": "You","kh": "ខ្ញុំឈឺធ្មេញខាងក្រោយ។","ro": "khnyom chheu <b>THMENH</b> khang-kraoy.","en": "My back tooth hurts."},{"who": "Dentist","kh": "ឈឺប៉ុន្មានថ្ងៃហើយ?","ro": "chheu pon-man <b>THNGAI</b> haoy?","en": "How many days has it hurt?"},{"who": "You","kh": "មួយអាទិត្យហើយ។ ឈឺពេលញ៉ាំត្រជាក់។","ro": "muoy <b>AA-TIT</b> haoy. chheu peil nyam tro-cheak.","en": "A week. It hurts with cold things."},{"who": "Dentist","kh": "ធ្មេញពុក ត្រូវឧបធ្មេញ។","ro": "thmenh <b>PUK</b>, trov op thmenh.","en": "It’s decayed; it needs a filling."},{"who": "You","kh": "សុំកុំដកធ្មេញបានទេ?","ro": "som kom <b>DOK</b> thmenh baan tei?","en": "Can you avoid pulling it?"}],"sayit": "<span class=\"kh\">ធ្មេញ</span> <span class=\"ro\">(thmenh)</span> begins with a puffed <em>t</em> pressed straight into <em>m</em> — one syllable, no vowel between. Say “t-menh”, not “ta-menh”.","phrases": [{"en": "Tooth / teeth","kh": "ធ្មេញ","ro": "<b>thmenh</b>"},{"en": "My tooth hurts.","kh": "ខ្ញុំឈឺធ្មេញ","ro": "khnyom chheu <b>thmenh</b>"},{"en": "Decayed tooth","kh": "ធ្មេញពុក","ro": "thmenh <b>puk</b>"},{"en": "Filling","kh": "ឧបធ្មេញ","ro": "<b>op</b> thmenh"},{"en": "Please don’t pull it out.","kh": "សុំកុំដកធ្មេញ","ro": "som kom <b>dok</b> thmenh"},{"en": "Teeth cleaning","kh": "សម្អាតធ្មេញ","ro": "som-<b>at</b> thmenh"},{"en": "Please give me an anaesthetic.","kh": "សូមចាក់ថ្នាំស្ពឹក","ro": "som chak thnam <b>spuk</b>"},{"en": "It still hurts.","kh": "នៅតែឈឺ","ro": "nov tae <b>chheu</b>"}],"tips": [{"label": "Dental Work Is a Bargain","html": "Cambodia has a large number of well-trained dentists, many educated abroad, and prices are a fraction of Western ones — a cleaning costs a few dollars, a filling perhaps twenty. Foreigners living here often schedule dental work deliberately during their stay. Choose a clinic that shows you <b>sterile packaging opened in front of you</b>, and ask what the total will be before treatment starts, not after.","culture": false}],"goal": "Dentistry here is good and inexpensive. Point at the tooth and say how long it has hurt.","ch": 5},
{"n": 54,"title": "Medicine & Dosage","titleKm": "ថ្នាំ និងកម្រិតប្រើ","scene": "Getting the instructions right. Repeat the dosage back — it is the safest thing you can do.","dialogue": [{"who": "Pharmacist","kh": "ញ៉ាំមួយគ្រាប់ព្រឹក និងល្ងាច។","ro": "nyam muoy <b>KROAB</b> pruk ning lngiech.","en": "One tablet morning and evening."},{"who": "You","kh": "ព្រឹកមួយ ល្ងាចមួយ មែនទេ?","ro": "pruk muoy, lngiech muoy, <b>MAEN</b> tei?","en": "One in the morning, one in the evening — correct?"},{"who": "Pharmacist","kh": "ត្រូវហើយ ញ៉ាំក្រោយអាហារ។","ro": "<b>TROV</b> haoy, nyam kraoy aa-haa.","en": "Correct, after food."},{"who": "You","kh": "ញ៉ាំប៉ុន្មានថ្ងៃ?","ro": "nyam pon-man <b>THNGAI</b>?","en": "For how many days?"},{"who": "You","kh": "មានផលរំខានទេ?","ro": "mien <b>PHOL</b> rom-khan tei?","en": "Are there side effects?"}],"sayit": "Repeat instructions back with <span class=\"ro\">… maen tei?</span> — “correct?”. It turns a one-way instruction into a confirmed one, and pharmacists appreciate it.","phrases": [{"en": "Tablet / capsule","kh": "គ្រាប់ថ្នាំ","ro": "<b>kroab</b> thnam"},{"en": "One tablet, twice a day","kh": "មួយគ្រាប់ ពីរដងក្នុងមួយថ្ងៃ","ro": "muoy kroab, pii <b>dong</b> knong muoy thngai"},{"en": "Before / after food","kh": "មុន / ក្រោយអាហារ","ro": "<b>mun</b> / <b>kraoy</b> aa-haa"},{"en": "For how many days?","kh": "ញ៉ាំប៉ុន្មានថ្ងៃ?","ro": "nyam pon-man <b>thngai</b>?"},{"en": "Are there side effects?","kh": "មានផលរំខានទេ?","ro": "mien <b>phol</b> rom-khan tei?"},{"en": "Antibiotics","kh": "ថ្នាំអង់ទីប៊ីយោទិច","ro": "thnam ong-ti-bi-yo-<b>tech</b>"},{"en": "Correct? / is that right?","kh": "មែនទេ?","ro": "<b>maen</b> tei?"},{"en": "I feel better now.","kh": "ខ្ញុំធូរស្បើយហើយ","ro": "khnyom <b>thuu</b>-sbaeuy haoy"}],"tips": [{"label": "Finish the Antibiotics","html": "Antibiotics are sold freely here and are often handed out for ordinary colds, which they do nothing for. If you are genuinely prescribed a course, <b>finish all of it</b> even once you feel well — stopping early is how resistant infections are bred, and Southeast Asia already has a serious problem with them. Also check every packet’s expiry date at the counter: stock rotation in small pharmacies is not always careful.","culture": false}],"goal": "Getting the instructions right. Repeat the dosage back — it is the safest thing you can do.","ch": 5},
{"n": 55,"title": "Calling for Help","titleKm": "ការស្រែកសុំជំនួយ","scene": "The page you hope never to need. Learn the first three lines by heart, tonight.","dialogue": [{"who": "You","kh": "ជួយផង! មានគ្រោះថ្នាក់!","ro": "<b>CHUOY</b> phong! mien kroh-thnak!","en": "Help! There’s been an accident!"},{"who": "You","kh": "សូមហៅរថយន្តសង្គ្រោះ!","ro": "som hav ro-<b>TEAH</b> song-kroh!","en": "Please call an ambulance!"},{"who": "Passer-by","kh": "មានរឿងអ្វី? នៅឯណា?","ro": "mien <b>ROEUNG</b> a-vei? nov ae-naa?","en": "What happened? Where?"},{"who": "You","kh": "មនុស្សម្នាក់របួសធ្ងន់។","ro": "mo-nuh mneak ro-<b>BUOH</b> thngon.","en": "Someone is badly injured."},{"who": "You","kh": "មន្ទីរពេទ្យជិតបំផុតនៅឯណា?","ro": "mon-ti-peit <b>CHIT</b> bom-phot nov ae-naa?","en": "Where is the nearest hospital?"}],"sayit": "<span class=\"kh\">ជួយផង!</span> <span class=\"ro\">(chuoy phong!)</span> is the shout for help. Two syllables, loud, repeated — this is the one phrase in the book to memorise before you need to look it up.","phrases": [{"en": "Help!","kh": "ជួយផង!","ro": "<b>chuoy</b> phong!"},{"en": "Call an ambulance!","kh": "ហៅរថយន្តសង្គ្រោះ!","ro": "hav ro-<b>teah</b> song-kroh!"},{"en": "Call the police!","kh": "ហៅប៉ូលិស!","ro": "hav <b>pou-lih</b>!"},{"en": "Fire!","kh": "ភ្លើងឆេះ!","ro": "phleung <b>chheh</b>!"},{"en": "Someone is injured.","kh": "មានមនុស្សរបួស","ro": "mien mo-nuh ro-<b>buoh</b>"},{"en": "Where is the nearest hospital?","kh": "មន្ទីរពេទ្យជិតបំផុតនៅឯណា?","ro": "mon-ti-peit <b>chit</b> bom-phot nov ae-naa?"},{"en": "It’s an emergency.","kh": "នេះជាគ្រាអាសន្ន","ro": "nih chie kroa aa-<b>son</b>"},{"en": "Please hurry!","kh": "សូមប្រញាប់!","ro": "som bra-<b>nhap</b>!"}],"tips": [{"label": "Get to the Hospital Yourself","html": "Ambulance coverage is limited and slow outside the capital, and in a real emergency Cambodians <b>drive the patient in themselves</b> — by car, by tuk-tuk, by motorbike. Do the same rather than waiting. Keep three things written in Khmer in your wallet or phone: your blood type, any allergy, and the name of the nearest hospital. The national emergency numbers are <b>119</b> for ambulance, <b>117</b> for police and <b>118</b> for fire.","culture": false}],"goal": "The page you hope never to need. Learn the first three lines by heart, tonight.","ch": 5},
{"n": 56,"title": "Reporting a Theft","titleKm": "ការរាយការណ៍ពីការលួច","scene": "Your bag is gone. You need a police report for the insurance, so go the same day.","dialogue": [{"who": "You","kh": "មានចោរលួចកាបូបខ្ញុំ។","ro": "mien <b>CHAO</b> luoch kaa-boub khnyom.","en": "A thief stole my bag."},{"who": "Officer","kh": "កើតឡើងនៅឯណា ពេលណា?","ro": "kaeut laeung nov <b>AE-NAA</b>, peil naa?","en": "Where and when did it happen?"},{"who": "You","kh": "នៅមុខផ្សារ ម៉ោងប្រាំល្ងាច។","ro": "nov muk <b>PHSAA</b>, maong pram lngiech.","en": "In front of the market, at five in the evening."},{"who": "You","kh": "ក្នុងនោះមានលិខិតឆ្លងដែន និងលុយ។","ro": "knong nuh mien li-khet <b>CHHLONG</b>-daen ning luy.","en": "It had my passport and money in it."},{"who": "You","kh": "ខ្ញុំត្រូវការរបាយការណ៍សម្រាប់ធានារ៉ាប់រង។","ro": "khnyom trov-kaa ro-bay-<b>KAA</b> som-rap thie-nie-rap-rong.","en": "I need a report for my insurance."}],"sayit": "<span class=\"kh\">លួច</span> <span class=\"ro\">(luoch)</span> is “to steal” and <span class=\"kh\">បាត់</span> <span class=\"ro\">(bat)</span> is “to be lost”. Choose carefully: one is a crime report, the other is a lost-property enquiry.","phrases": [{"en": "Police / police station","kh": "ប៉ូលិស / ស្នងការដ្ឋាន","ro": "<b>pou-lih</b> / sno-ng-kaa-<b>than</b>"},{"en": "Thief","kh": "ចោរ","ro": "<b>chao</b>"},{"en": "Someone stole my …","kh": "មានចោរលួច … ខ្ញុំ","ro": "mien chao <b>luoch</b> … khnyom"},{"en": "I lost my passport.","kh": "ខ្ញុំបាត់លិខិតឆ្លងដែន","ro": "khnyom <b>bat</b> li-khet chhlong-daen"},{"en": "Phone / wallet / bag","kh": "ទូរស័ព្ទ / កាបូបលុយ / កាបូប","ro": "tuu-ra-<b>sap</b> / kaa-boub <b>luy</b> / kaa-<b>boub</b>"},{"en": "I need a police report.","kh": "ខ្ញុំត្រូវការរបាយការណ៍","ro": "khnyom trov-kaa ro-bay-<b>kaa</b>"},{"en": "It happened at …","kh": "កើតឡើងនៅ …","ro": "<b>kaeut</b> laeung nov …"},{"en": "Please call my embassy.","kh": "សូមទាក់ទងស្ថានទូតខ្ញុំ","ro": "som teak-tong sthan-<b>tout</b> khnyom"}],"tips": [{"label": "Bag Snatching From Motorbikes","html": "The commonest crime against foreigners in Phnom Penh is a bag pulled from a passing motorbike, which can drag you into the road. Carry bags on the side <b>away from traffic</b>, or across your body under an arm, and never hold a phone loosely at the kerb. If it happens, let go — a bag is replaceable. Report it the same day; the station will write a report, sometimes for a small unofficial fee, and insurers require it.","culture": false}],"goal": "Your bag is gone. You need a police report for the insurance, so go the same day.","ch": 5},
{"n": 57,"title": "A Traffic Accident","titleKm": "គ្រោះថ្នាក់ចរាចរណ៍","scene": "A minor collision. Stay calm, check for injuries, and do not admit fault before anyone arrives.","dialogue": [{"who": "You","kh": "អ្នករបួសទេ?","ro": "neak ro-<b>BUOH</b> tei?","en": "Are you injured?"},{"who": "Rider","kh": "អត់ទេ តែម៉ូតូខូច។","ro": "ot tei, tae moto <b>KHOUCH</b>.","en": "No, but my motorbike is damaged."},{"who": "You","kh": "សូមហៅប៉ូលិសមកសិន។","ro": "som hav <b>POU-LIH</b> mok sen.","en": "Let’s call the police first."},{"who": "You","kh": "ខ្ញុំនឹងថតរូបទុក។","ro": "khnyom neung <b>THOT</b> ruup tuk.","en": "I’ll take photographs."},{"who": "You","kh": "សុំលេខទូរស័ព្ទ និងអត្តសញ្ញាណប័ណ្ណ។","ro": "som leik tuu-ra-sap ning at-ta-son-<b>NHAN</b>-ban.","en": "Your phone number and ID card, please."}],"sayit": "Ask <span class=\"ro\">neak ro-buoh tei?</span> — “are you injured?” — before anything else. Beginning with concern rather than blame changes how the entire situation unfolds.","phrases": [{"en": "Accident","kh": "គ្រោះថ្នាក់","ro": "kroh-<b>thnak</b>"},{"en": "Are you injured?","kh": "អ្នករបួសទេ?","ro": "neak ro-<b>buoh</b> tei?"},{"en": "It wasn’t my fault.","kh": "មិនមែនកំហុសខ្ញុំទេ","ro": "min maen kom-<b>hoh</b> khnyom tei"},{"en": "Let’s call the police.","kh": "សូមហៅប៉ូលិស","ro": "som hav <b>pou-lih</b>"},{"en": "I’ll take photographs.","kh": "ខ្ញុំនឹងថតរូប","ro": "khnyom neung <b>thot</b> ruup"},{"en": "Driving licence","kh": "បណ្ណបើកបរ","ro": "<b>ban</b> baeuk-bor"},{"en": "Insurance","kh": "ធានារ៉ាប់រង","ro": "thie-nie-<b>rap</b>-rong"},{"en": "Please wait for the police.","kh": "សូមចាំប៉ូលិសសិន","ro": "som <b>cham</b> pou-lih sen"}],"tips": [{"label": "Fault Follows the Larger Vehicle","html": "In practice, responsibility here is often assigned to whoever was driving the <b>bigger vehicle</b> — and to the foreigner, who is assumed able to pay. Disputes are usually settled on the spot with cash rather than through insurers. Stay calm, never raise your voice, photograph everything including both number plates, and phone a Khmer-speaking friend to negotiate for you. Above all, do not drive away: leaving the scene turns a claim into a criminal matter.","culture": true}],"goal": "A minor collision. Stay calm, check for injuries, and do not admit fault before anyone arrives.","ch": 5},
{"n": 58,"title": "Massage & Spa","titleKm": "ម៉ាស្សា និងស្ប៉ា","scene": "Khmer massage is firm. Learn “gently” and “too strong” before you lie down, not during.","dialogue": [{"who": "Staff","kh": "ម៉ាស្សាខ្មែរ ឬម៉ាស្សាប្រេង?","ro": "maa-saa <b>KHMAE</b> reu maa-saa breng?","en": "Khmer massage or oil massage?"},{"who": "You","kh": "ម៉ាស្សាខ្មែរ មួយម៉ោង។","ro": "maa-saa <b>KHMAE</b>, muoy maong.","en": "Khmer massage, one hour."},{"who": "You","kh": "សូមធ្វើថ្នមៗបន្តិច។","ro": "som thveu <b>THNOM</b>-thnom bon-tech.","en": "Please do it gently."},{"who": "You","kh": "ខ្លាំងពេក! ឈឺ។","ro": "<b>KHLANG</b> peik! chheu.","en": "Too strong! It hurts."},{"who": "You","kh": "សូមផ្ដោតលើស្មា។","ro": "som <b>PHDAOT</b> leu smaa.","en": "Please focus on my shoulders."}],"sayit": "<span class=\"kh\">ថ្នមៗ</span> <span class=\"ro\">(thnom-thnom)</span> means “gently, softly”, and <span class=\"kh\">ខ្លាំង</span> <span class=\"ro\">(khlang)</span> means “strong”. Between them you can steer any massage in the country.","phrases": [{"en": "Massage","kh": "ម៉ាស្សា","ro": "maa-<b>saa</b>"},{"en": "One hour / thirty minutes","kh": "មួយម៉ោង / សាមសិបនាទី","ro": "muoy <b>maong</b> / saam-sep nie-ti"},{"en": "Gently, please.","kh": "សូមធ្វើថ្នមៗ","ro": "som thveu <b>thnom</b>-thnom"},{"en": "Too strong!","kh": "ខ្លាំងពេក!","ro": "<b>khlang</b> peik!"},{"en": "Stronger, please.","kh": "សុំខ្លាំងជាងនេះ","ro": "som <b>khlang</b> chieng nih"},{"en": "Shoulders / back / feet","kh": "ស្មា / ខ្នង / ជើង","ro": "<b>smaa</b> / <b>khnong</b> / <b>choeung</b>"},{"en": "That’s the spot.","kh": "ត្រង់នោះហើយ","ro": "trong <b>nuh</b> haoy"},{"en": "That feels good.","kh": "ស្រួលណាស់","ro": "<b>sruol</b> nas"}],"tips": [{"label": "Look for the Blind Massage Centres","html": "Cambodia has a network of training centres employing blind and partially sighted therapists, and the standard of traditional Khmer massage there is generally excellent — firm, technical, and priced at a few dollars an hour. Seeing Hands is the best known. A tip of a dollar or two is genuinely appreciated. Note that Khmer massage involves stretching and deep pressure rather than oil and gliding; <span class=\"ro\">thnom-thnom</span> is not a sign of weakness, it is useful information.","culture": false}],"goal": "Khmer massage is firm. Learn “gently” and “too strong” before you lie down, not during.","ch": 5},
{"n": 59,"title": "At the Gym","titleKm": "នៅកន្លែងហាត់ប្រាណ","scene": "Joining a gym, asking about the monthly rate, and learning the words for the classes on the wall.","dialogue": [{"who": "You","kh": "សមាជិកមួយខែថ្លៃប៉ុន្មាន?","ro": "sa-mie-<b>CHEK</b> muoy khae thlai pon-man?","en": "How much is monthly membership?"},{"who": "Staff","kh": "ម្ភៃប្រាំដុល្លារមួយខែ។","ro": "<b>MPHEY</b>-pram dol-laa muoy khae.","en": "Twenty-five dollars a month."},{"who": "You","kh": "មកម្ដងថ្លៃប៉ុន្មាន?","ro": "mok <b>MDONG</b> thlai pon-man?","en": "How much for a single visit?"},{"who": "You","kh": "មានថ្នាក់យូហ្គាទេ?","ro": "mien thnak <b>YOU-KAA</b> tei?","en": "Do you have yoga classes?"},{"who": "Staff","kh": "មាន ព្រឹកម៉ោងប្រាំមួយ។","ro": "<b>MIEN</b>, pruk maong pram-muoy.","en": "Yes, at six in the morning."}],"sayit": "<span class=\"kh\">ហាត់ប្រាណ</span> <span class=\"ro\">(hat bran)</span> means “to exercise”. A gym is <span class=\"kh\">កន្លែងហាត់ប្រាណ</span> <span class=\"ro\">(kon-laeng hat bran)</span> — literally “the exercising place”.","phrases": [{"en": "To exercise","kh": "ហាត់ប្រាណ","ro": "<b>hat</b> bran"},{"en": "Membership","kh": "សមាជិក","ro": "sa-mie-<b>chek</b>"},{"en": "How much per month?","kh": "មួយខែថ្លៃប៉ុន្មាន?","ro": "muoy khae <b>thlai</b> pon-man?"},{"en": "Do you have yoga?","kh": "មានថ្នាក់យូហ្គាទេ?","ro": "mien thnak <b>you-kaa</b> tei?"},{"en": "Swimming pool","kh": "អាងហែលទឹក","ro": "ang hael <b>tuk</b>"},{"en": "What time do you open?","kh": "បើកម៉ោងប៉ុន្មាន?","ro": "<b>baeuk</b> maong pon-man?"},{"en": "Personal trainer","kh": "គ្រូបង្វឹក","ro": "kruu bong-<b>vuk</b>"},{"en": "I’m tired / I need a rest.","kh": "ខ្ញុំហត់ សុំសម្រាកបន្តិច","ro": "khnyom <b>hot</b>, som som-raak bon-tech"}],"tips": [{"label": "Exercise at Dawn or Dusk","html": "Cambodians train early and late, never in the middle of the day — by ten in the morning the heat makes outdoor exercise genuinely risky. Head to any riverside or public park at around six in the evening and you will find <b>free open-air aerobics classes</b>, dozens of people following an instructor with a speaker, for a few hundred riel or nothing at all. It is the friendliest possible way to practise both your fitness and your Khmer.","culture": false}],"goal": "Joining a gym, asking about the monthly rate, and learning the words for the classes on the wall.","ch": 5},
{"n": 60,"title": "Stress, Sleep & Feeling Low","titleKm": "ភាពតានតឹង និងការគេងមិនលក់","scene": "Living abroad is tiring in ways that are hard to name. These are the words for saying so.","dialogue": [{"who": "Friend","kh": "មើលទៅអ្នកហត់ណាស់។","ro": "meul teuv neak <b>HOT</b> nas.","en": "You look very tired."},{"who": "You","kh": "ខ្ញុំគេងមិនលក់ច្រើនយប់ហើយ។","ro": "khnyom keing min <b>LUOK</b> chraen yub haoy.","en": "I haven’t slept well for several nights."},{"who": "You","kh": "ខ្ញុំតានតឹងនឹងការងារ។","ro": "khnyom taan-<b>TEUNG</b> neung kaa-ngie.","en": "I’m stressed about work."},{"who": "Friend","kh": "សម្រាកខ្លះទៅ។ ថែរក្សាខ្លួនផង។","ro": "som-<b>RAAK</b> khlah teuv. thae-rak-saa kluon phong.","en": "Get some rest. Take care of yourself."},{"who": "You","kh": "ខ្ញុំនឹករលឹកផ្ទះ។","ro": "khnyom <b>NEUK</b> ro-leuk phteah.","en": "I’m homesick."}],"sayit": "<span class=\"kh\">នឹករលឹក</span> <span class=\"ro\">(neuk ro-leuk)</span> means “to miss / long for”. Say <span class=\"ro\">khnyom neuk ro-leuk phteah</span> and any Cambodian will understand exactly what you mean.","phrases": [{"en": "I’m tired.","kh": "ខ្ញុំហត់","ro": "khnyom <b>hot</b>"},{"en": "I can’t sleep.","kh": "ខ្ញុំគេងមិនលក់","ro": "khnyom keing min <b>luok</b>"},{"en": "I’m stressed.","kh": "ខ្ញុំតានតឹង","ro": "khnyom taan-<b>teung</b>"},{"en": "I’m homesick.","kh": "ខ្ញុំនឹករលឹកផ្ទះ","ro": "khnyom <b>neuk</b> ro-leuk phteah"},{"en": "I’m sad / unhappy.","kh": "ខ្ញុំមិនសប្បាយចិត្ត","ro": "khnyom min sa-bay <b>chet</b>"},{"en": "Get some rest.","kh": "សម្រាកខ្លះទៅ","ro": "som-<b>raak</b> khlah teuv"},{"en": "Take care of yourself.","kh": "ថែរក្សាខ្លួនផង","ro": "thae-rak-<b>saa</b> kluon phong"},{"en": "I need someone to talk to.","kh": "ខ្ញុំចង់និយាយជាមួយនរណាម្នាក់","ro": "khnyom chong ni-yiey chie-muoy <b>no-naa</b> mneak"}],"tips": [{"label": "Feelings Live in the Heart Word","html": "A great many Khmer emotional expressions are built on <span class=\"kh\">ចិត្ត</span> <span class=\"ro\">(chet)</span>, meaning heart or mind: <span class=\"ro\">sa-bay chet</span> is happy, <span class=\"ro\">min sa-bay chet</span> unhappy, <span class=\"ro\">khoeung chet</span> angry, <span class=\"ro\">smoh chet</span> sincere. Mental health is rarely discussed openly here and there are few local services, so long-term residents often rely on international clinics in Phnom Penh or on counselling online. Saying you are simply <span class=\"ro\">hot</span> — tired — is always understood, and always an acceptable answer.","culture": true}],"goal": "Living abroad is tiring in ways that are hard to name. These are the words for saying so.","ch": 5},
{"n": 61,"title": "Job Interview Basics","titleKm": "មូលដ្ឋានគ្រឹះនៃការសម្ភាសន៍","scene": "Interviewing a candidate, or being interviewed. Either way these five exchanges carry the meeting.","dialogue": [{"who": "Manager","kh": "សូមណែនាំខ្លួនបន្តិច។","ro": "som nae-<b>NOAM</b> kluon bon-tech.","en": "Please introduce yourself."},{"who": "You","kh": "ខ្ញុំមានបទពិសោធន៍ប្រាំឆ្នាំ។","ro": "khnyom mien bot-pi-<b>SAOT</b> pram chhnam.","en": "I have five years of experience."},{"who": "Manager","kh": "ហេតុអ្វីចង់ធ្វើការនៅទីនេះ?","ro": "haet a-vei chong thveu <b>KAA</b> nov ti-nih?","en": "Why do you want to work here?"},{"who": "You","kh": "ខ្ញុំចូលចិត្តការងារជាមួយក្រុម។","ro": "khnyom chol-chet kaa-ngie chie-muoy <b>KROM</b>.","en": "I enjoy working with a team."},{"who": "Manager","kh": "តើអ្នកចង់បានប្រាក់ខែប៉ុន្មាន?","ro": "tae neak chong baan brak-<b>KHAE</b> pon-man?","en": "What salary are you looking for?"}],"sayit": "<span class=\"kh\">ណែនាំខ្លួន</span> <span class=\"ro\">(nae-noam kluon)</span> means “introduce oneself”. The same verb <span class=\"ro\">nae-noam</span> is used for recommending a person or a restaurant.","phrases": [{"en": "Interview","kh": "ការសម្ភាសន៍","ro": "kaa som-<b>pheas</b>"},{"en": "Please introduce yourself.","kh": "សូមណែនាំខ្លួន","ro": "som nae-<b>noam</b> kluon"},{"en": "Experience","kh": "បទពិសោធន៍","ro": "bot-pi-<b>saot</b>"},{"en": "Salary","kh": "ប្រាក់ខែ","ro": "brak-<b>khae</b>"},{"en": "I can start next month.","kh": "ខ្ញុំអាចចាប់ផ្ដើមខែក្រោយ","ro": "khnyom ach chap-<b>phdaeum</b> khae kraoy"},{"en": "Full time / part time","kh": "ពេញម៉ោង / ក្រៅម៉ោង","ro": "<b>penh</b> maong / <b>krav</b> maong"},{"en": "Do you speak English?","kh": "និយាយអង់គ្លេសបានទេ?","ro": "ni-yiey ong-<b>gleih</b> baan tei?"},{"en": "Thank you for your time.","kh": "អរគុណសម្រាប់ពេលវេលា","ro": "or-kun som-rap peil-<b>vei-lie</b>"}],"tips": [{"label": "Modesty Reads Better Than Confidence","html": "Western interview style — listing achievements, selling yourself hard — can land badly here, where self-promotion is read as a lack of humility. Cambodian candidates tend to describe what the <b>team</b> accomplished and what they still hope to learn. If you are the one interviewing, note that a quiet candidate is not necessarily an unconfident one; ask what they did rather than how good they are, and you will get a far more accurate answer.","culture": true}],"goal": "Interviewing a candidate, or being interviewed. Either way these five exchanges carry the meeting.","ch": 6},
{"n": 62,"title": "Professional Introductions","titleKm": "ការណែនាំក្នុងការងារ","scene": "Meeting a client for the first time. Cards are exchanged with two hands, and titles matter.","dialogue": [{"who": "You","kh": "ជម្រាបសួរ លោក។ នេះនាមប័ណ្ណខ្ញុំ។","ro": "chom-riep suor, lowk. nih nie-ma-<b>BAN</b> khnyom.","en": "Hello, sir. Here is my business card."},{"who": "Client","kh": "អរគុណ។ អ្នកធ្វើការក្រុមហ៊ុនណា?","ro": "or-kun. neak thveu kaa krom-<b>HUN</b> naa?","en": "Thank you. Which company are you with?"},{"who": "You","kh": "ខ្ញុំជាអ្នកគ្រប់គ្រងផ្នែកលក់។","ro": "khnyom chie neak krop-<b>KRONG</b> phnaek luok.","en": "I’m the sales manager."},{"who": "Client","kh": "រីករាយដែលបានស្គាល់។","ro": "rik-<b>RIEY</b> dael baan skoal.","en": "Pleased to meet you."},{"who": "You","kh": "សង្ឃឹមថានឹងសហការគ្នា។","ro": "song-<b>KHEUM</b> thaa neung sa-ha-kaa knie.","en": "I hope we can work together."}],"sayit": "Give and receive a card with <b>both hands</b>, or with the right hand supported at the elbow by the left. Read it before putting it away — never straight into a back pocket.","phrases": [{"en": "Company","kh": "ក្រុមហ៊ុន","ro": "krom-<b>hun</b>"},{"en": "Business card","kh": "នាមប័ណ្ណ","ro": "nie-ma-<b>ban</b>"},{"en": "Manager / director","kh": "អ្នកគ្រប់គ្រង / នាយក","ro": "neak krop-<b>krong</b> / nie-<b>yok</b>"},{"en": "Colleague / staff","kh": "សហការី / បុគ្គលិក","ro": "sa-ha-kaa-<b>rii</b> / bok-ko-<b>lik</b>"},{"en": "I work in the … department.","kh": "ខ្ញុំធ្វើការផ្នែក …","ro": "khnyom thveu kaa <b>phnaek</b> …"},{"en": "This is my colleague.","kh": "នេះជាសហការីខ្ញុំ","ro": "nih chie sa-ha-kaa-<b>rii</b> khnyom"},{"en": "I hope we can work together.","kh": "សង្ឃឹមថានឹងសហការគ្នា","ro": "song-<b>kheum</b> thaa neung sa-ha-kaa knie"},{"en": "May I have your card?","kh": "សុំនាមប័ណ្ណបានទេ?","ro": "som nie-ma-<b>ban</b> baan tei?"}],"tips": [{"label": "Greet the Most Senior Person First","html": "Cambodian offices are strongly hierarchical, and the order in which you greet a room is noticed by everyone in it. Identify the most senior person — usually the oldest, and the one others defer to — and greet them <b>first</b>, with a sampeah slightly higher than you would use for peers. Use <span class=\"ro\">lowk</span> or <span class=\"ro\">lowk srei</span> until you are invited to do otherwise, and let them set the tone for how formal the meeting stays.","culture": true}],"goal": "Meeting a client for the first time. Cards are exchanged with two hands, and titles matter.","ch": 6},
{"n": 63,"title": "In a Meeting","titleKm": "ក្នុងកិច្ចប្រជុំ","scene": "Opening, contributing and closing. Disagree gently — the wording here is doing a lot of work.","dialogue": [{"who": "Chair","kh": "សូមចាប់ផ្ដើមប្រជុំ។","ro": "som chap-phdaeum bra-<b>CHUM</b>.","en": "Let’s begin the meeting."},{"who": "You","kh": "សុំបញ្ចេញមតិបន្តិចបានទេ?","ro": "som banh-chenh <b>MO-TI</b> bon-tech baan tei?","en": "May I share an opinion?"},{"who": "You","kh": "ខ្ញុំយល់ស្របជាមួយគំនិតនេះ។","ro": "khnyom yul-<b>SROP</b> chie-muoy kum-net nih.","en": "I agree with this idea."},{"who": "Colleague","kh": "ប្រហែលមានវិធីផ្សេងទៀត។","ro": "bra-hael mien vi-<b>THII</b> phseng tiet.","en": "Perhaps there’s another way."},{"who": "Chair","kh": "អញ្ចឹងសម្រេចយ៉ាងនេះ។","ro": "an-choeng som-<b>RECH</b> yang nih.","en": "Then we’ll decide it this way."}],"sayit": "<span class=\"kh\">ប្រហែល</span> <span class=\"ro\">(bra-hael, “perhaps”)</span> is how Cambodians disagree. “Perhaps there is another way” is a full objection — treat it as one.","phrases": [{"en": "Meeting","kh": "កិច្ចប្រជុំ","ro": "kech bra-<b>chum</b>"},{"en": "May I share an opinion?","kh": "សុំបញ្ចេញមតិបានទេ?","ro": "som banh-chenh <b>mo-ti</b> baan tei?"},{"en": "I agree.","kh": "ខ្ញុំយល់ស្រប","ro": "khnyom yul-<b>srop</b>"},{"en": "Perhaps there’s another way.","kh": "ប្រហែលមានវិធីផ្សេងទៀត","ro": "bra-hael mien vi-<b>thii</b> phseng tiet"},{"en": "I don’t quite understand.","kh": "ខ្ញុំមិនសូវយល់","ro": "khnyom min sao <b>yul</b>"},{"en": "Could you explain again?","kh": "ជួយពន្យល់ម្ដងទៀត","ro": "chuoy pon-<b>yul</b> mdong tiet"},{"en": "Who is responsible for this?","kh": "អ្នកណាទទួលខុសត្រូវ?","ro": "neak-naa to-tuol <b>khoh</b>-trov?"},{"en": "When is the deadline?","kh": "ផុតកំណត់ពេលណា?","ro": "<b>phot</b> kom-not peil naa?"}],"tips": [{"label": "Silence Is Not Agreement","html": "Juniors rarely contradict seniors in front of a room, so a meeting that ends with everyone nodding may have settled nothing at all. The real conversation happens afterwards, one to one. If you are leading, ask people individually and privately, and always finish by asking each person to <b>state back what they will do and by when</b>. Written follow-up in Khmer or simple English prevents the polite nod from becoming a missed deadline.","culture": true}],"goal": "Opening, contributing and closing. Disagree gently — the wording here is doing a lot of work.","ch": 6},
{"n": 64,"title": "Work Phone Calls","titleKm": "ការទូរស័ព្ទក្នុងការងារ","scene": "Answering, taking a message and getting off the line politely — all without seeing the other face.","dialogue": [{"who": "You","kh": "ហាឡូ ក្រុមហ៊ុនអេប៊ីស៊ី សូមស្វាគមន៍។","ro": "haa-lou, krom-hun ABC, som svie-<b>KOM</b>.","en": "Hello, ABC Company, good day."},{"who": "Caller","kh": "សុំជួបលោកសុខបានទេ?","ro": "som <b>CHUOP</b> lowk Sok baan tei?","en": "May I speak to Mr Sok?"},{"who": "You","kh": "គាត់មិននៅទេ។ ចាំបន្តិច។","ro": "koat min <b>NOV</b> tei. cham bon-tech.","en": "He isn’t here. One moment."},{"who": "You","kh": "តើអ្នកចង់ផ្ញើសារអ្វីទេ?","ro": "tae neak chong <b>PHNHAEU</b> saa a-vei tei?","en": "Would you like to leave a message?"},{"who": "You","kh": "ខ្ញុំនឹងឲ្យគាត់ទូរស័ព្ទមកវិញ។","ro": "khnyom neung aoy koat tuu-ra-sap mok <b>VINH</b>.","en": "I’ll have him call you back."}],"sayit": "<span class=\"kh\">គាត់</span> <span class=\"ro\">(koat)</span> is the respectful third-person pronoun for an adult — “he” or “she” alike. Khmer pronouns mark status, not gender.","phrases": [{"en": "Hello <em>(on the phone)</em>","kh": "ហាឡូ","ro": "haa-<b>lou</b>"},{"en": "May I speak to …?","kh": "សុំជួប … បានទេ?","ro": "som <b>chuop</b> … baan tei?"},{"en": "One moment, please.","kh": "សូមចាំបន្តិច","ro": "som <b>cham</b> bon-tech"},{"en": "He / she isn’t here.","kh": "គាត់មិននៅទេ","ro": "koat min <b>nov</b> tei"},{"en": "Leave a message","kh": "ផ្ញើសារ","ro": "<b>phnhaeu</b> saa"},{"en": "I’ll call you back.","kh": "ខ្ញុំនឹងទូរស័ព្ទមកវិញ","ro": "khnyom neung tuu-ra-sap mok <b>vinh</b>"},{"en": "The line is bad.","kh": "សេវាមិនច្បាស់","ro": "sei-vie min <b>chbah</b>"},{"en": "Who’s calling, please?","kh": "សុំទោស នរណាហ្នឹង?","ro": "som toh, <b>no-naa</b> nung?"}],"tips": [{"label": "Business Runs on Telegram","html": "Cambodia does most of its professional messaging on <b>Telegram</b> rather than email — quotes, invoices, contracts and appointments all arrive there, often as photographs of paper documents. Expect voice notes rather than typed replies, and expect to be added to a great many groups. Email is treated as formal and slow; if something is urgent, phone. And answer with your company name, as above: it is what callers expect to hear.","culture": false}],"goal": "Answering, taking a message and getting off the line politely — all without seeing the other face.","ch": 6},
{"n": 65,"title": "Messages & Appointments","titleKm": "សារ និងការណាត់ជួប","scene": "Fixing a time, confirming it, and rearranging when something inevitably moves.","dialogue": [{"who": "You","kh": "តើយើងណាត់ជួបថ្ងៃណា?","ro": "tae yeung <b>NAT</b> chuop thngai naa?","en": "What day shall we meet?"},{"who": "Client","kh": "ថ្ងៃពុធ ម៉ោងដប់ព្រឹក បានទេ?","ro": "thngai <b>PUT</b>, maong dop pruk, baan tei?","en": "Wednesday at ten, alright?"},{"who": "You","kh": "បានហើយ។ ខ្ញុំនឹងផ្ញើសារបញ្ជាក់។","ro": "<b>BAAN</b> haoy. khnyom neung phnhaeu saa banh-cheak.","en": "Fine. I’ll send a confirmation message."},{"who": "You","kh": "សុំទោស ខ្ញុំត្រូវពន្យារពេលបន្តិច។","ro": "som toh, khnyom trov pon-<b>YIE</b> peil bon-tech.","en": "Sorry, I need to postpone slightly."},{"who": "Client","kh": "អត់អីទេ ប្ដូរទៅថ្ងៃព្រហស្បតិ៍។","ro": "ot ei tei, <b>BDO</b> teuv thngai bro-hoah.","en": "No problem, move it to Thursday."}],"sayit": "<span class=\"kh\">ណាត់ជួប</span> <span class=\"ro\">(nat chuop)</span> means “to make an appointment”. <span class=\"kh\">បញ្ជាក់</span> <span class=\"ro\">(banh-cheak)</span> means “to confirm” — always do the second after the first.","phrases": [{"en": "Appointment","kh": "ការណាត់ជួប","ro": "kaa <b>nat</b> chuop"},{"en": "Monday / Wednesday / Thursday","kh": "ថ្ងៃច័ន្ទ / ថ្ងៃពុធ / ថ្ងៃព្រហស្បតិ៍","ro": "thngai chan / <b>put</b> / bro-<b>hoah</b>"},{"en": "Are you free on …?","kh": "ថ្ងៃ … ទំនេរទេ?","ro": "thngai … tum-<b>nei</b> tei?"},{"en": "I’ll confirm by message.","kh": "ខ្ញុំនឹងផ្ញើសារបញ្ជាក់","ro": "khnyom neung phnhaeu saa banh-<b>cheak</b>"},{"en": "I need to postpone.","kh": "ខ្ញុំត្រូវពន្យារពេល","ro": "khnyom trov pon-<b>yie</b> peil"},{"en": "I’ll be a little late.","kh": "ខ្ញុំនឹងយឺតបន្តិច","ro": "khnyom neung <b>yoeut</b> bon-tech"},{"en": "Please send me the documents.","kh": "សូមផ្ញើឯកសារមកខ្ញុំ","ro": "som phnhaeu aek-ka-<b>saa</b> mok khnyom"},{"en": "I’ve received it, thank you.","kh": "ខ្ញុំទទួលបានហើយ","ro": "khnyom to-<b>tuol</b> baan haoy"}],"tips": [{"label": "Confirm the Morning Of","html": "An appointment agreed a week ahead is an intention, not a commitment; traffic, rain, family obligations and more senior people all outrank it. Send a short confirming message on <b>the morning of the meeting</b> — this is normal practice, not nagging, and it is how Cambodians manage their own diaries. Build slack into your day, and treat a cancellation as circumstance rather than rudeness.","culture": false}],"goal": "Fixing a time, confirming it, and rearranging when something inevitably moves.","ch": 6},
{"n": 66,"title": "Small Talk at Work","titleKm": "ការនិយាយលេងជាមួយសហការី","scene": "The lunch hour is where working relationships are actually built. Join in.","dialogue": [{"who": "Colleague","kh": "ថ្ងៃនេះរវល់ណាស់មែនទេ?","ro": "thngai nih ro-<b>VOL</b> nas maen tei?","en": "Busy day today, isn’t it?"},{"who": "You","kh": "មែនហើយ! ការងារច្រើនណាស់។","ro": "maen haoy! kaa-ngie <b>CHRAEN</b> nas.","en": "Yes! So much work."},{"who": "Colleague","kh": "ទៅញ៉ាំបាយជាមួយគ្នាទេ?","ro": "teuv nyam bay chie-muoy <b>KNIE</b> tei?","en": "Shall we go for lunch together?"},{"who": "You","kh": "បាទ ទៅ! ថ្ងៃចុងសប្ដាហ៍ធ្វើអ្វី?","ro": "baat, <b>TEUV</b>! thngai chong sap-daa thveu a-vei?","en": "Yes, let’s! What are you doing at the weekend?"},{"who": "Colleague","kh": "ត្រឡប់ទៅស្រុកកំណើត។","ro": "tro-<b>LOP</b> teuv srok kom-naeut.","en": "Going back to my home province."}],"sayit": "<span class=\"kh\">ស្រុកកំណើត</span> <span class=\"ro\">(srok kom-naeut)</span> is “home village / birthplace”. Almost everyone working in Phnom Penh has one, and asking about it is a warm, safe question.","phrases": [{"en": "Busy today, isn’t it?","kh": "ថ្ងៃនេះរវល់ណាស់មែនទេ?","ro": "thngai nih ro-<b>vol</b> nas maen tei?"},{"en": "Shall we eat together?","kh": "ទៅញ៉ាំបាយជាមួយគ្នាទេ?","ro": "teuv nyam bay chie-muoy <b>knie</b> tei?"},{"en": "The weekend","kh": "ថ្ងៃចុងសប្ដាហ៍","ro": "thngai chong <b>sap-daa</b>"},{"en": "Home province / village","kh": "ស្រុកកំណើត","ro": "srok kom-<b>naeut</b>"},{"en": "How long have you worked here?","kh": "ធ្វើការនៅទីនេះបានប៉ុន្មានហើយ?","ro": "thveu kaa nov ti-nih baan <b>pon-man</b> haoy?"},{"en": "Have a good weekend.","kh": "សូមរីករាយថ្ងៃឈប់សម្រាក","ro": "som rik-riey thngai chhup som-<b>raak</b>"},{"en": "See you tomorrow.","kh": "ជួបគ្នាថ្ងៃស្អែក","ro": "chuop knie thngai <b>sa-aek</b>"},{"en": "I’m going home now.","kh": "ខ្ញុំត្រឡប់ទៅផ្ទះហើយ","ro": "khnyom tro-<b>lop</b> teuv phteah haoy"}],"tips": [{"label": "Eat Lunch With the Team","html": "Lunch in a Cambodian office is a shared, communal affair, often eaten together at someone’s desk or at the same stall every day. Turning it down repeatedly to work through — a virtue in some workplaces — reads here as keeping yourself apart. Say yes, pay your share, ask about people’s families and home provinces, and the working relationship that follows will be far more open than any number of meetings could produce.","culture": false}],"goal": "The lunch hour is where working relationships are actually built. Join in.","ch": 6},
{"n": 67,"title": "Instructing Staff","titleKm": "ការណែនាំបុគ្គលិក","scene": "Giving clear instructions and correcting mistakes without causing anyone to lose face.","dialogue": [{"who": "You","kh": "ជួយរៀបចំរបាយការណ៍នេះផង។","ro": "chuoy riep-<b>CHOM</b> ro-bay-kaa nih phong.","en": "Please prepare this report."},{"who": "Staff","kh": "បាទ ត្រូវការពេលណា?","ro": "baat, trov-kaa <b>PEIL</b> naa?","en": "Yes, when do you need it?"},{"who": "You","kh": "មុនម៉ោងបួនរសៀល។","ro": "mun maong <b>BUON</b> ro-siel.","en": "Before four in the afternoon."},{"who": "You","kh": "ត្រង់នេះខុសបន្តិច ជួយកែផង។","ro": "trong nih <b>KHOH</b> bon-tech, chuoy kae phong.","en": "This part is slightly wrong, please fix it."},{"who": "You","kh": "ធ្វើបានល្អណាស់ អរគុណ។","ro": "thveu baan <b>LA-OR</b> nas, or-kun.","en": "Very well done, thank you."}],"sayit": "Frame instructions as requests: <span class=\"ro\">chuoy … phong</span> means “please help … ”. A bare command is grammatically fine and socially cold; the <span class=\"ro\">chuoy … phong</span> wrapper costs two words.","phrases": [{"en": "Please help me … <em>(request)</em>","kh": "ជួយ … ផង","ro": "<b>chuoy</b> … phong"},{"en": "When do you need it?","kh": "ត្រូវការពេលណា?","ro": "trov-kaa <b>peil</b> naa?"},{"en": "Before four o’clock","kh": "មុនម៉ោងបួន","ro": "<b>mun</b> maong buon"},{"en": "This part is wrong.","kh": "ត្រង់នេះខុស","ro": "trong nih <b>khoh</b>"},{"en": "Please fix it.","kh": "ជួយកែផង","ro": "chuoy <b>kae</b> phong"},{"en": "Do you understand?","kh": "យល់ទេ?","ro": "<b>yul</b> tei?"},{"en": "Very well done.","kh": "ធ្វើបានល្អណាស់","ro": "thveu baan <b>la-or</b> nas"},{"en": "Take your time.","kh": "មិនបាច់ប្រញាប់ទេ","ro": "min bach bra-<b>nhap</b> tei"}],"tips": [{"label": "Correct in Private, Praise in Public","html": "Criticising someone in front of colleagues causes a loss of face that can quietly end their willingness to work with you, and they will rarely tell you so. Correct quietly, one to one, and soften it — <span class=\"ro\">khoh bon-tech</span>, “slightly wrong”, does the job. Praise, by contrast, should be given openly. And never ask <span class=\"ro\">yul tei?</span> expecting a truthful no; ask instead for the task to be explained back to you.","culture": true}],"goal": "Giving clear instructions and correcting mistakes without causing anyone to lose face.","ch": 6},
{"n": 68,"title": "Negotiating a Contract","titleKm": "ការចរចាកិច្ចសន្យា","scene": "Agreeing terms for a service. Get the price, the deadline and the payment schedule in writing.","dialogue": [{"who": "You","kh": "តម្លៃសរុបប៉ុន្មាន?","ro": "tom-lai sa-<b>ROP</b> pon-man?","en": "What is the total price?"},{"who": "Supplier","kh": "ពីរពាន់ដុល្លារ រួមទាំងដំឡើង។","ro": "pii poan dol-laa, ruom teang dom-<b>LAEUNG</b>.","en": "Two thousand dollars, installation included."},{"who": "You","kh": "បង់មុនប៉ុន្មានភាគរយ?","ro": "bong mun pon-man phiek-<b>ROY</b>?","en": "What percentage is paid up front?"},{"who": "Supplier","kh": "សាមសិបភាគរយ នៅសល់ពេលរួចរាល់។","ro": "saam-sep phiek-roy, nov <b>SOL</b> peil ruoch-roal.","en": "Thirty per cent, the rest on completion."},{"who": "You","kh": "សូមសរសេរក្នុងកិច្ចសន្យា។","ro": "som sor-sei knong kech-son-<b>YIE</b>.","en": "Please put that in the contract."}],"sayit": "<span class=\"kh\">រួមទាំង</span> <span class=\"ro\">(ruom teang)</span> means “including”; <span class=\"kh\">មិនរាប់</span> <span class=\"ro\">(min roab)</span> means “not including”. Ask which applies to every line of a quotation.","phrases": [{"en": "Contract","kh": "កិច្ចសន្យា","ro": "kech-son-<b>yie</b>"},{"en": "What is the total price?","kh": "តម្លៃសរុបប៉ុន្មាន?","ro": "tom-lai sa-<b>rop</b> pon-man?"},{"en": "Including / not including","kh": "រួមទាំង / មិនរាប់","ro": "ruom <b>teang</b> / min <b>roab</b>"},{"en": "Deposit / balance","kh": "ប្រាក់កក់ / ប្រាក់នៅសល់","ro": "brak <b>kok</b> / brak nov <b>sol</b>"},{"en": "When will it be finished?","kh": "រួចរាល់ពេលណា?","ro": "<b>ruoch</b>-roal peil naa?"},{"en": "Please put it in writing.","kh": "សូមសរសេរជាលាយលក្ខណ៍អក្សរ","ro": "som sor-sei chie lie-<b>lak</b> ak-so"},{"en": "To sign","kh": "ចុះហត្ថលេខា","ro": "choh hat-tha-lei-<b>khaa</b>"},{"en": "Is there a guarantee?","kh": "មានធានាទេ?","ro": "mien <b>thie-nie</b> tei?"}],"tips": [{"label": "Bilingual, and Two Copies","html": "Have any contract that matters drawn up in <b>Khmer and English side by side</b>, with both parties signing every page and each keeping an original. Where the two versions differ, the Khmer text is what a Cambodian court will read — so pay a local lawyer to check it rather than relying on a translation you cannot verify. Stage the payments against delivered work; a deposit of thirty per cent is normal, paying everything up front is not.","culture": false}],"goal": "Agreeing terms for a service. Get the price, the deadline and the payment schedule in writing.","ch": 6},
{"n": 69,"title": "In the Language Class","titleKm": "ក្នុងថ្នាក់រៀនភាសា","scene": "The classroom phrases that let you learn faster — and that work in any lesson, on any subject.","dialogue": [{"who": "Teacher","kh": "ថ្ងៃនេះយើងរៀនមេរៀនទីប្រាំ។","ro": "thngai nih yeung rien mei-rien ti <b>PRAM</b>.","en": "Today we study lesson five."},{"who": "You","kh": "លោកគ្រូ សុំសួរបន្តិចបានទេ?","ro": "lowk <b>KRUU</b>, som suo bon-tech baan tei?","en": "Teacher, may I ask something?"},{"who": "You","kh": "ពាក្យនេះអានយ៉ាងម៉េច?","ro": "peak nih <b>AAN</b> yang mech?","en": "How is this word pronounced?"},{"who": "Teacher","kh": "ល្អណាស់! ធ្វើលំហាត់ផ្ទះទំព័រដប់។","ro": "<b>LA-OR</b> nas! thveu lom-hat phteah tum-po dop.","en": "Very good! Do the homework on page ten."},{"who": "You","kh": "សុំមេរៀនម្ដងទៀតបានទេ?","ro": "som mei-<b>RIEN</b> mdong tiet baan tei?","en": "Could we go over it once more?"}],"sayit": "Address a male teacher as <span class=\"kh\">លោកគ្រូ</span> <span class=\"ro\">(lowk kruu)</span> and a female one as <span class=\"kh\">អ្នកគ្រូ</span> <span class=\"ro\">(neak kruu)</span>. Teachers are held in genuinely high regard in Cambodia.","phrases": [{"en": "Teacher <em>(male / female)</em>","kh": "លោកគ្រូ / អ្នកគ្រូ","ro": "lowk <b>kruu</b> / neak <b>kruu</b>"},{"en": "Student / lesson","kh": "សិស្ស / មេរៀន","ro": "<b>seh</b> / mei-<b>rien</b>"},{"en": "May I ask something?","kh": "សុំសួរបន្តិចបានទេ?","ro": "som <b>suo</b> bon-tech baan tei?"},{"en": "How is this word pronounced?","kh": "ពាក្យនេះអានយ៉ាងម៉េច?","ro": "peak nih <b>aan</b> yang mech?"},{"en": "What does this mean?","kh": "នេះមានន័យថាម៉េច?","ro": "nih mien <b>ney</b> thaa mech?"},{"en": "Homework","kh": "លំហាត់ផ្ទះ","ro": "lom-hat <b>phteah</b>"},{"en": "Once more, please.","kh": "សុំម្ដងទៀត","ro": "som <b>mdong</b> tiet"},{"en": "I’ve forgotten.","kh": "ខ្ញុំភ្លេចហើយ","ro": "khnyom <b>phlech</b> haoy"}],"tips": [{"label": "Learn the Alphabet Early","html": "Romanisation gets you speaking in week one — that is what this book is for — but it will quietly cap your progress, because no two systems agree and none captures Khmer vowels exactly. The script has 33 consonants and two vowel series, and most learners can read simple signs after a few weeks of steady work. Start with the consonants you meet daily on shopfronts, and treat every <span class=\"kh\">ផ្សារ</span> and <span class=\"kh\">វត្ត</span> you pass as a free flashcard.","culture": false}],"goal": "The classroom phrases that let you learn faster — and that work in any lesson, on any subject.","ch": 6},
{"n": 70,"title": "Talking About Your Job","titleKm": "ការនិយាយអំពីការងាររបស់អ្នក","scene": "You will be asked what you do and what you earn. Here is how to answer both — one fully, one lightly.","dialogue": [{"who": "Neighbour","kh": "តើអ្នកធ្វើការអ្វី?","ro": "tae neak thveu <b>KAA</b> a-vei?","en": "What work do you do?"},{"who": "You","kh": "ខ្ញុំធ្វើការនៅអង្គការមួយ។","ro": "khnyom thveu kaa nov ong-<b>KAA</b> muoy.","en": "I work for an organisation."},{"who": "Neighbour","kh": "ប្រាក់ខែច្រើនទេ?","ro": "brak-khae <b>CHRAEN</b> tei?","en": "Is the salary good?"},{"who": "You","kh": "គ្រប់គ្រាន់ហើយ អរគុណ។","ro": "krop-<b>KROAN</b> haoy, or-kun.","en": "It’s enough, thank you."},{"who": "You","kh": "ខ្ញុំចូលចិត្តការងារនេះណាស់។","ro": "khnyom chol-<b>CHET</b> kaa-ngie nih nas.","en": "I like this job very much."}],"sayit": "<span class=\"kh\">គ្រប់គ្រាន់ហើយ</span> <span class=\"ro\">(krop-kroan haoy)</span> — “it’s enough” — is the perfect answer to a salary question. It is honest, modest, and closes the subject warmly.","phrases": [{"en": "What work do you do?","kh": "តើអ្នកធ្វើការអ្វី?","ro": "tae neak thveu <b>kaa</b> a-vei?"},{"en": "Teacher / doctor / engineer","kh": "គ្រូ / គ្រូពេទ្យ / វិស្វករ","ro": "kruu / kruu-<b>peit</b> / vih-va-<b>ko</b>"},{"en": "Businessperson / student","kh": "អ្នកជំនួញ / និស្សិត","ro": "neak chum-<b>nuonh</b> / ni-<b>set</b>"},{"en": "I work for an organisation.","kh": "ខ្ញុំធ្វើការនៅអង្គការ","ro": "khnyom thveu kaa nov ong-<b>kaa</b>"},{"en": "It’s enough. <em>(about salary)</em>","kh": "គ្រប់គ្រាន់ហើយ","ro": "krop-<b>kroan</b> haoy"},{"en": "I like my job.","kh": "ខ្ញុំចូលចិត្តការងារខ្ញុំ","ro": "khnyom chol-<b>chet</b> kaa-ngie khnyom"},{"en": "I’m looking for work.","kh": "ខ្ញុំកំពុងរកការងារ","ro": "khnyom kom-pung <b>rok</b> kaa-ngie"},{"en": "I’m retired.","kh": "ខ្ញុំចូលនិវត្តន៍ហើយ","ro": "khnyom choul ni-<b>voat</b> haoy"}],"tips": [{"label": "The Salary Question Is Not Rude","html": "Asking what you earn, what your rent is or what your motorbike cost is ordinary friendly curiosity here, not an intrusion — Cambodians ask each other the same things freely. You are not obliged to answer with a number, and <span class=\"ro\">krop-kroan haoy</span> handles it gracefully. Bear in mind that a foreign salary is often many times a local one, so a precise figure can quietly change a friendship; vagueness is kinder to everybody.","culture": true}],"goal": "You will be asked what you do and what you earn. Here is how to answer both — one fully, one lightly.","ch": 6},
{"n": 71,"title": "Making Plans","titleKm": "ការរៀបចំកម្មវិធី","scene": "Fixing a time with a friend. Keep it loose — plans here are made and remade all day.","dialogue": [{"who": "You","kh": "ថ្ងៃសៅរ៍អ្នកទំនេរទេ?","ro": "thngai <b>SAO</b> neak tum-nei tei?","en": "Are you free on Saturday?"},{"who": "Friend","kh": "ទំនេរ។ ចង់ទៅណា?","ro": "tum-<b>NEI</b>. chong teuv naa?","en": "Yes. Where do you want to go?"},{"who": "You","kh": "ទៅញ៉ាំបាយមាត់ទន្លេទេ?","ro": "teuv nyam bay <b>MOAT</b> ton-lei tei?","en": "Shall we eat by the river?"},{"who": "Friend","kh": "បាទ! ជួបគ្នាម៉ោងប្រាំមួយ។","ro": "baat! chuop knie maong <b>PRAM</b>-muoy.","en": "Yes! Let’s meet at six."},{"who": "You","kh": "ខ្ញុំនឹងផ្ញើសារបញ្ជាក់។","ro": "khnyom neung phnhaeu saa banh-<b>CHEAK</b>.","en": "I’ll message to confirm."}],"sayit": "<span class=\"kh\">ទំនេរ</span> <span class=\"ro\">(tum-nei)</span> means “free / unoccupied” and works for people, tables and taxis alike. <span class=\"ro\">tum-nei tei?</span> is a complete question on its own.","phrases": [{"en": "Are you free?","kh": "អ្នកទំនេរទេ?","ro": "neak tum-<b>nei</b> tei?"},{"en": "Saturday / Sunday","kh": "ថ្ងៃសៅរ៍ / ថ្ងៃអាទិត្យ","ro": "thngai <b>sao</b> / thngai <b>aa-tit</b>"},{"en": "Where shall we go?","kh": "ចង់ទៅណា?","ro": "chong teuv <b>naa</b>?"},{"en": "Let’s meet at six.","kh": "ជួបគ្នាម៉ោងប្រាំមួយ","ro": "chuop knie maong <b>pram</b>-muoy"},{"en": "What time suits you?","kh": "ម៉ោងណាស្រួលសម្រាប់អ្នក?","ro": "maong naa <b>sruol</b> som-rap neak?"},{"en": "I’m busy that day.","kh": "ថ្ងៃនោះខ្ញុំរវល់","ro": "thngai nuh khnyom ro-<b>vol</b>"},{"en": "Let’s make it another day.","kh": "ប្ដូរទៅថ្ងៃផ្សេង","ro": "<b>bdo</b> teuv thngai phseng"},{"en": "See you there!","kh": "ជួបគ្នានៅទីនោះ!","ro": "chuop knie nov ti-<b>nuh</b>!"}],"tips": [{"label": "Plans Breathe","html": "A Cambodian “yes” to a social plan means <em>yes, in principle</em>. Rain, a family obligation or a request from someone senior will move it without much ceremony, and this is not considered flaky — the relationship matters more than the calendar. Confirm on the day, arrive expecting a flexible start, and do the same yourself without guilt. Friendships here are maintained by frequent small contact rather than by punctual appointments.","culture": true}],"goal": "Fixing a time with a friend. Keep it loose — plans here are made and remade all day.","ch": 7},
{"n": 72,"title": "Inviting Someone Out","titleKm": "ការអញ្ជើញនរណាម្នាក់","scene": "Extending an invitation, and settling the question of who pays before it becomes awkward.","dialogue": [{"who": "You","kh": "ខ្ញុំចង់អញ្ជើញអ្នកញ៉ាំបាយ។","ro": "khnyom chong an-<b>CHOEUN</b> neak nyam bay.","en": "I’d like to invite you for a meal."},{"who": "Friend","kh": "អរគុណ! នៅហាងណា?","ro": "or-kun! nov <b>HANG</b> naa?","en": "Thank you! Which restaurant?"},{"who": "You","kh": "ហាងជិតផ្សារ។ ខ្ញុំរៀបចំឲ្យ។","ro": "hang <b>CHIT</b> phsaa. khnyom riep-chom aoy.","en": "The place near the market. I’ll arrange it."},{"who": "Friend","kh": "យើងចែកគ្នាបង់ទេ?","ro": "yeung <b>CHAEK</b> knie bong tei?","en": "Shall we split the bill?"},{"who": "You","kh": "ថ្ងៃនេះខ្ញុំរៀបចំ។ លើកក្រោយអ្នក។","ro": "thngai nih khnyom <b>RIEP-CHOM</b>. leuk kraoy neak.","en": "Today it’s on me. Next time, you."}],"sayit": "<span class=\"kh\">អញ្ជើញ</span> <span class=\"ro\">(an-choeun)</span> is both “to invite” and “please, go ahead”. Whoever says <span class=\"ro\">khnyom an-choeun</span> is usually understood to be paying.","phrases": [{"en": "I’d like to invite you.","kh": "ខ្ញុំចង់អញ្ជើញអ្នក","ro": "khnyom chong an-<b>choeun</b> neak"},{"en": "Would you like to come?","kh": "ចង់ទៅជាមួយគ្នាទេ?","ro": "chong teuv chie-muoy <b>knie</b> tei?"},{"en": "For coffee / for a meal","kh": "ផឹកកាហ្វេ / ញ៉ាំបាយ","ro": "<b>pheuk</b> kaa-fei / <b>nyam</b> bay"},{"en": "Shall we split the bill?","kh": "យើងចែកគ្នាបង់ទេ?","ro": "yeung <b>chaek</b> knie bong tei?"},{"en": "Today it’s on me.","kh": "ថ្ងៃនេះខ្ញុំរៀបចំ","ro": "thngai nih khnyom <b>riep-chom</b>"},{"en": "Next time it’s yours.","kh": "លើកក្រោយអ្នក","ro": "<b>leuk</b> kraoy neak"},{"en": "Bring a friend if you like.","kh": "នាំមិត្តភក្តិមកជាមួយបាន","ro": "<b>noam</b> mit-phak mok chie-muoy baan"},{"en": "Thank you for inviting me.","kh": "អរគុណដែលបានអញ្ជើញ","ro": "or-kun dael baan an-<b>choeun</b>"}],"tips": [{"label": "The Inviter Pays","html": "Splitting a bill item by item is uncommon here. Whoever proposed the outing generally settles it, and the balance is restored next time rather than on the night — which is exactly what <span class=\"ro\">leuk kraoy neak</span> means. Bear in mind the income gap: insisting a Cambodian friend on a local salary pay half of a foreigner-priced dinner puts them in a difficult position they will never mention. Pay, lightly, and let them host you somewhere of their choosing later.","culture": true}],"goal": "Extending an invitation, and settling the question of who pays before it becomes awkward.","ch": 7},
{"n": 73,"title": "Parties & Weddings","titleKm": "ជប់លៀង និងអាពាហ៍ពិពាហ៍","scene": "You have been handed a wedding invitation by a colleague. Accept — and bring an envelope.","dialogue": [{"who": "Colleague","kh": "ខ្ញុំរៀបការថ្ងៃទីដប់។ អញ្ជើញមក!","ro": "khnyom riep-<b>KAA</b> thngai ti dop. an-choeun mok!","en": "I’m getting married on the tenth. Please come!"},{"who": "You","kh": "អបអរសាទរ! ខ្ញុំនឹងទៅ។","ro": "ap-or-saa-<b>TO</b>! khnyom neung teuv.","en": "Congratulations! I’ll be there."},{"who": "You","kh": "កម្មវិធីចាប់ផ្ដើមម៉ោងប៉ុន្មាន?","ro": "kam-ma-vi-thii chap-phdaeum <b>MAONG</b> pon-man?","en": "What time does it start?"},{"who": "Colleague","kh": "ល្ងាចម៉ោងប្រាំ នៅឯវត្ត។","ro": "lngiech maong <b>PRAM</b>, nov ae voat.","en": "Five in the evening, at the pagoda."},{"who": "You","kh": "សូមជូនពរឲ្យមានសុភមង្គល។","ro": "som choun <b>PO</b> aoy mien so-phak-mong-kol.","en": "I wish you every happiness."}],"sayit": "<span class=\"kh\">អបអរសាទរ</span> <span class=\"ro\">(ap-or-saa-to)</span> is “congratulations”, used for weddings, graduations and new babies alike. Four syllables, evenly stressed.","phrases": [{"en": "Wedding","kh": "អាពាហ៍ពិពាហ៍","ro": "aa-peah pi-<b>peah</b>"},{"en": "Party / celebration","kh": "ជប់លៀង","ro": "chob-<b>lieng</b>"},{"en": "Congratulations!","kh": "អបអរសាទរ!","ro": "ap-or-saa-<b>to</b>!"},{"en": "I’m getting married.","kh": "ខ្ញុំរៀបការ","ro": "khnyom riep-<b>kaa</b>"},{"en": "What time does it start?","kh": "ចាប់ផ្ដើមម៉ោងប៉ុន្មាន?","ro": "chap-<b>phdaeum</b> maong pon-man?"},{"en": "Bride / groom","kh": "កូនក្រមុំ / កូនកំលោះ","ro": "koun kro-<b>mom</b> / koun kom-<b>loh</b>"},{"en": "I wish you happiness.","kh": "សូមជូនពរឲ្យមានសុភមង្គល","ro": "som choun <b>po</b> aoy mien so-phak-mong-kol"},{"en": "Cheers! <em>(toast)</em>","kh": "លើកែវ!","ro": "leuk <b>kaev</b>!"}],"tips": [{"label": "Money in an Envelope","html": "Cambodian weddings are enormous — several hundred guests are ordinary — and the gift is <b>cash in the envelope</b> that came with your invitation, handed in at a table by the door where it is recorded in a book. Twenty to fifty dollars is a normal range depending on how close you are. Dress smartly and brightly; black alone is for funerals. Arriving an hour after the printed time is completely standard, and you may find the party still filling up.","culture": true}],"goal": "You have been handed a wedding invitation by a colleague. Accept — and bring an envelope.","ch": 7},
{"n": 74,"title": "Compliments","titleKm": "ការសរសើរ","scene": "Praising a person, a home, a meal or a language attempt. Compliments are warmly received here.","dialogue": [{"who": "You","kh": "អាវនេះស្អាតណាស់!","ro": "aav nih <b>S-AT</b> nas!","en": "That shirt is lovely!"},{"who": "Friend","kh": "អរគុណ! ទើបទិញថ្មី។","ro": "or-kun! teub tinh <b>THMEI</b>.","en": "Thank you! I just bought it."},{"who": "Friend","kh": "អ្នកនិយាយខ្មែរពិរោះណាស់!","ro": "neak ni-yiey khmae <b>PI-ROH</b> nas!","en": "You speak Khmer beautifully!"},{"who": "You","kh": "អត់ទេ ខ្ញុំនៅរៀនតិចតួច។","ro": "ot tei, khnyom nov rien <b>TECH</b>-tuoch.","en": "Not at all, I’m still learning a little."},{"who": "You","kh": "ផ្ទះអ្នកស្អាតណាស់។","ro": "phteah neak <b>S-AT</b> nas.","en": "Your home is beautiful."}],"sayit": "<span class=\"kh\">ស្អាត</span> <span class=\"ro\">(s-at)</span> means both “beautiful” and “clean”. Said of a house it is high praise; said of a person it means good-looking.","phrases": [{"en": "Beautiful / lovely","kh": "ស្អាត","ro": "<b>s-at</b>"},{"en": "Handsome","kh": "សង្ហា","ro": "song-<b>haa</b>"},{"en": "You speak Khmer well.","kh": "អ្នកនិយាយខ្មែរពិរោះណាស់","ro": "neak ni-yiey khmae <b>pi-roh</b> nas"},{"en": "You’re very kind.","kh": "អ្នកចិត្តល្អណាស់","ro": "neak chet <b>la-or</b> nas"},{"en": "Your home is lovely.","kh": "ផ្ទះអ្នកស្អាតណាស់","ro": "phteah neak <b>s-at</b> nas"},{"en": "Clever / capable","kh": "ពូកែ","ro": "pu-<b>kae</b>"},{"en": "Not at all. <em>(deflecting)</em>","kh": "អត់ទេ","ro": "ot <b>tei</b>"},{"en": "You’re too kind.","kh": "អ្នកសរសើរពេក","ro": "neak sor-<b>saeu</b> peik"}],"tips": [{"label": "Deflect, Don’t Accept","html": "Receiving praise with a straight “thank you” can sound like agreement, and agreement sounds like pride. Cambodians deflect first — <span class=\"ro\">ot tei</span>, “not at all” — and then thank. Do the same when your Khmer is complimented, which will happen constantly and often generously. Keep compliments to appearance, clothes, home and cooking; comments on a person’s body or weight, normal between close Cambodian friends, are best avoided by a newcomer.","culture": true}],"goal": "Praising a person, a home, a meal or a language attempt. Compliments are warmly received here.","ch": 7},
{"n": 75,"title": "Talking About Family","titleKm": "ការនិយាយអំពីគ្រួសារ","scene": "Family is the first subject anyone will ask about, and the one they most want to hear about.","dialogue": [{"who": "Friend","kh": "តើអ្នករៀបការហើយឬនៅ?","ro": "tae neak riep-<b>KAA</b> haoy reu nov?","en": "Are you married yet?"},{"who": "You","kh": "រៀបការហើយ មានកូនពីរនាក់។","ro": "riep-<b>KAA</b> haoy, mien koun pii neak.","en": "Yes, I have two children."},{"who": "Friend","kh": "ពួកគេនៅជាមួយអ្នកទេ?","ro": "puok-kei nov chie-muoy <b>NEAK</b> tei?","en": "Are they here with you?"},{"who": "You","kh": "អត់ទេ គេនៅស្រុកខ្ញុំ។","ro": "ot tei, kei nov <b>SROK</b> khnyom.","en": "No, they’re in my country."},{"who": "You","kh": "ចុះអ្នកវិញ? មានបងប្អូនប៉ុន្មាននាក់?","ro": "choh neak vinh? mien bong-<b>P’OUN</b> pon-man neak?","en": "And you? How many brothers and sisters?"}],"sayit": "<span class=\"kh\">បងប្អូន</span> <span class=\"ro\">(bong-p’oun)</span> literally means “elder-younger” and covers all siblings at once. Khmer marks relative age before it marks gender.","phrases": [{"en": "Family","kh": "គ្រួសារ","ro": "kruo-<b>saa</b>"},{"en": "Father / mother","kh": "ឪពុក / ម្ដាយ","ro": "<b>ov-puk</b> / <b>mdaay</b>"},{"en": "Husband / wife","kh": "ប្ដី / ប្រពន្ធ","ro": "<b>bdei</b> / bra-<b>pon</b>"},{"en": "Child / children","kh": "កូន","ro": "<b>koun</b>"},{"en": "Brothers and sisters","kh": "បងប្អូន","ro": "bong-<b>p’oun</b>"},{"en": "Are you married?","kh": "រៀបការហើយឬនៅ?","ro": "riep-<b>kaa</b> haoy reu nov?"},{"en": "I’m single.","kh": "ខ្ញុំនៅលីវ","ro": "khnyom nov <b>liv</b>"},{"en": "I have two children.","kh": "ខ្ញុំមានកូនពីរនាក់","ro": "khnyom mien koun <b>pii</b> neak"}],"tips": [{"label": "The Family Is the Unit","html": "Cambodian identity is rooted in family far more than in the individual, and much of a young worker’s salary goes home to parents in the province every month. Asking after someone’s parents and children is the warmest thing you can do; describing your own family — even briefly, even in poor Khmer — moves you from foreigner to person. If you are over thirty and unmarried, expect kind bewilderment and possibly an introduction.","culture": true}],"goal": "Family is the first subject anyone will ask about, and the one they most want to hear about.","ch": 7},
{"n": 76,"title": "Visiting Someone’s Home","titleKm": "ការទៅលេងផ្ទះគេ","scene": "Arriving at a family house. Shoes off at the door, greet the eldest, and accept the drink.","dialogue": [{"who": "Host","kh": "អញ្ជើញចូល! អញ្ជើញអង្គុយ។","ro": "an-choeun <b>CHOUL</b>! an-choeun ong-kuy.","en": "Please come in! Please sit down."},{"who": "You","kh": "អរគុណ។ ដោះស្បែកជើងទេ?","ro": "or-kun. <b>DOH</b> sbaek-choeung tei?","en": "Thank you. Shall I take off my shoes?"},{"who": "Host","kh": "បាទ ដោះនៅមុខទ្វារ។ ផឹកទឹកទេ?","ro": "baat, doh nov muk tvie. <b>PHEUK</b> tuk tei?","en": "Yes, at the door. Would you like a drink?"},{"who": "You","kh": "សុំទឹកមួយកែវ អរគុណ។","ro": "som tuk muoy <b>KAEV</b>, or-kun.","en": "A glass of water, thank you."},{"who": "You","kh": "ផ្ទះអ្នកកក់ក្ដៅណាស់។","ro": "phteah neak kok-<b>KDAV</b> nas.","en": "Your home is very welcoming."}],"sayit": "<span class=\"kh\">កក់ក្ដៅ</span> <span class=\"ro\">(kok-kdav)</span> literally means “warm”, but of a home it means welcoming and full of affection — a compliment any host is pleased to hear.","phrases": [{"en": "Please come in.","kh": "អញ្ជើញចូល","ro": "an-choeun <b>choul</b>"},{"en": "Please sit down.","kh": "អញ្ជើញអង្គុយ","ro": "an-choeun <b>ong-kuy</b>"},{"en": "Shall I take off my shoes?","kh": "ដោះស្បែកជើងទេ?","ro": "<b>doh</b> sbaek-choeung tei?"},{"en": "A glass of water, please.","kh": "សុំទឹកមួយកែវ","ro": "som tuk muoy <b>kaev</b>"},{"en": "Where is the toilet?","kh": "បង្គន់នៅឯណា?","ro": "bong-<b>kon</b> nov ae-naa?"},{"en": "Your home is welcoming.","kh": "ផ្ទះអ្នកកក់ក្ដៅណាស់","ro": "phteah neak kok-<b>kdav</b> nas"},{"en": "I should be going now.","kh": "ខ្ញុំសុំលាទៅមុនហើយ","ro": "khnyom som <b>lie</b> teuv mun haoy"},{"en": "Thank you for having me.","kh": "អរគុណដែលបានទទួល","ro": "or-kun dael baan to-<b>tuol</b>"}],"tips": [{"label": "Shoes Off, Head Down, Feet Away","html": "Three rules cover most of home etiquette. Take your <b>shoes off</b> at the door, always. Lower your head slightly when passing in front of someone seated and older. And never point the <b>soles of your feet</b> at a person or at the household shrine — sit cross-legged or with your feet tucked behind you. The head is the most sacred part of the body and the feet the least, which is why patting even a child’s head is best avoided.","culture": true}],"goal": "Arriving at a family house. Shoes off at the door, greet the eldest, and accept the drink.","ch": 7},
{"n": 77,"title": "Giving & Receiving Gifts","titleKm": "ការជូន និងទទួលអំណោយ","scene": "Handing over a small gift. Two hands, a modest word, and no expectation that it is opened.","dialogue": [{"who": "You","kh": "នេះជាអំណោយតូចមួយសម្រាប់អ្នក។","ro": "nih chie om-<b>NAOY</b> touch muoy som-rap neak.","en": "This is a small gift for you."},{"who": "Friend","kh": "អូ! មិនបាច់ទេ អរគុណច្រើន!","ro": "ouh! min <b>BACH</b> tei, or-kun chraen!","en": "Oh! You shouldn’t have, thank you!"},{"who": "You","kh": "របស់តូចតាចទេ។","ro": "ro-boh <b>TOUCH</b>-taach tei.","en": "It’s only a little thing."},{"who": "Friend","kh": "អ្នកគិតដល់ខ្ញុំណាស់។","ro": "neak <b>KET</b> dol khnyom nas.","en": "That’s very thoughtful of you."},{"who": "You","kh": "សូមទទួលដោយក្ដីរីករាយ។","ro": "som to-tuol daoy kdei rik-<b>RIEY</b>.","en": "Please accept it with pleasure."}],"sayit": "<span class=\"kh\">ជូន</span> <span class=\"ro\">(choun)</span> is the polite verb “to give” — used upwards, to elders and guests. The plain verb <span class=\"kh\">ឲ្យ</span> <span class=\"ro\">(aoy)</span> is for everyday giving.","phrases": [{"en": "Gift","kh": "អំណោយ","ro": "om-<b>naoy</b>"},{"en": "This is for you.","kh": "នេះសម្រាប់អ្នក","ro": "nih som-<b>rap</b> neak"},{"en": "You shouldn’t have.","kh": "មិនបាច់ទេ","ro": "min <b>bach</b> tei"},{"en": "It’s only a small thing.","kh": "របស់តូចតាចទេ","ro": "ro-boh <b>touch</b>-taach tei"},{"en": "That’s very thoughtful.","kh": "អ្នកគិតដល់ខ្ញុំណាស់","ro": "neak <b>ket</b> dol khnyom nas"},{"en": "Happy New Year!","kh": "សួស្តីឆ្នាំថ្មី!","ro": "suor-sdei chhnam <b>thmei</b>!"},{"en": "Happy birthday!","kh": "រីករាយថ្ងៃកំណើត!","ro": "rik-riey thngai kom-<b>naeut</b>!"},{"en": "Thank you for your kindness.","kh": "អរគុណចំពោះចិត្តល្អ","ro": "or-kun chom-poh chet <b>la-or</b>"}],"tips": [{"label": "Give With Two Hands, Don’t Expect It Opened","html": "Offer and receive gifts with <b>both hands</b>, and do not be surprised when yours is set aside unopened — opening a present in front of the giver can seem greedy, so it is enjoyed privately later. Fruit, cakes and useful household things travel well; avoid anything sharp, and avoid white wrapping or white flowers, which belong to funerals. When visiting a family home, a bag of fruit for the household is always the right answer.","culture": true}],"goal": "Handing over a small gift. Two hands, a modest word, and no expectation that it is opened.","ch": 7},
{"n": 78,"title": "Apologising Properly","titleKm": "ការសុំទោសឲ្យបានត្រឹមត្រូវ","scene": "Something went wrong and it was your fault. Say so plainly — it repairs faster than explaining.","dialogue": [{"who": "You","kh": "សូមអភ័យទោស ខ្ញុំមកយឺត។","ro": "som a-<b>PHEY</b> toh, khnyom mok yoeut.","en": "I sincerely apologise for being late."},{"who": "Friend","kh": "អត់អីទេ ខ្ញុំក៏ទើបមកដែរ។","ro": "ot ei tei, khnyom kâ <b>TEUB</b> mok dae.","en": "It’s fine, I just arrived too."},{"who": "You","kh": "ខ្ញុំយល់ច្រឡំ។ កំហុសខ្ញុំ។","ro": "khnyom yul chro-<b>LOM</b>. kom-hoh khnyom.","en": "I misunderstood. It was my mistake."},{"who": "You","kh": "ខ្ញុំមិនចង់ធ្វើឲ្យអ្នកខឹងទេ។","ro": "khnyom min chong thveu aoy neak <b>KHEUNG</b> tei.","en": "I didn’t mean to upset you."},{"who": "Friend","kh": "ភ្លេចវាទៅ។ យើងនៅជាមិត្ត។","ro": "<b>PHLECH</b> vie teuv. yeung nov chie mit.","en": "Forget it. We’re still friends."}],"sayit": "<span class=\"kh\">សូមអភ័យទោស</span> <span class=\"ro\">(som a-phey toh)</span> is the full, formal apology; <span class=\"kh\">សូមទោស</span> <span class=\"ro\">(som toh)</span> is the everyday one. Use the long form when it genuinely matters.","phrases": [{"en": "I sincerely apologise.","kh": "សូមអភ័យទោស","ro": "som a-<b>phey</b> toh"},{"en": "It was my mistake.","kh": "កំហុសខ្ញុំ","ro": "kom-<b>hoh</b> khnyom"},{"en": "I misunderstood.","kh": "ខ្ញុំយល់ច្រឡំ","ro": "khnyom yul chro-<b>lom</b>"},{"en": "I didn’t mean to.","kh": "ខ្ញុំមិនចេតនាទេ","ro": "khnyom min chei-ta-<b>nie</b> tei"},{"en": "Are you angry with me?","kh": "អ្នកខឹងខ្ញុំទេ?","ro": "neak <b>kheung</b> khnyom tei?"},{"en": "It won’t happen again.","kh": "នឹងមិនកើតឡើងទៀតទេ","ro": "neung min <b>kaeut</b> laeung tiet tei"},{"en": "Never mind, forget it.","kh": "អត់អីទេ ភ្លេចវាទៅ","ro": "ot ei tei, <b>phlech</b> vie teuv"},{"en": "Let’s talk about it calmly.","kh": "យើងនិយាយគ្នាដោយស្ងប់ស្ងាត់","ro": "yeung ni-yiey knie daoy <b>sngop</b>-sngat"}],"tips": [{"label": "Anger Costs More Than the Problem","html": "Losing your temper in public is remembered long after whatever caused it is forgotten, and it can permanently damage a working or personal relationship. A person who has been shouted at will usually keep smiling — and quietly withdraw. Apologise early, apologise simply, and do not pile on explanations, which read as excuses. A calm <span class=\"ro\">kom-hoh khnyom</span> and a small gift the next day repairs almost anything.","culture": true}],"goal": "Something went wrong and it was your fault. Say so plainly — it repairs faster than explaining.","ch": 7},
{"n": 79,"title": "Saying No Politely","titleKm": "ការបដិសេធដោយសុភាព","scene": "Declining an invitation, a price, or a persistent seller — without hardness and without lying.","dialogue": [{"who": "Seller","kh": "ទិញមួយទៅ បង! ថោកណាស់។","ro": "tinh muoy teuv, bong! <b>THAOK</b> nas.","en": "Buy one! It’s very cheap."},{"who": "You","kh": "អរគុណ តែខ្ញុំមិនត្រូវការទេ។","ro": "or-kun, tae khnyom min <b>TROV-KAA</b> tei.","en": "Thank you, but I don’t need it."},{"who": "Friend","kh": "ល្ងាចនេះទៅជប់លៀងជាមួយគ្នាទេ?","ro": "lngiech nih teuv chob-<b>LIENG</b> chie-muoy knie tei?","en": "Coming to the party tonight?"},{"who": "You","kh": "សុំទោស ថ្ងៃនេះខ្ញុំមិនអាចទេ។","ro": "som toh, thngai nih khnyom min <b>ACH</b> tei.","en": "Sorry, I can’t today."},{"who": "You","kh": "លើកក្រោយប្រាកដជាទៅ។","ro": "<b>LEUK</b> kraoy bra-kot chie teuv.","en": "Next time for certain."}],"sayit": "Soften every refusal with <span class=\"ro\">or-kun</span> in front and an offer of <span class=\"ro\">leuk kraoy</span> — “next time” — behind. A bare <span class=\"ro\">ot tei</span> is not wrong, just cold.","phrases": [{"en": "Thank you, but no.","kh": "អរគុណ តែអត់ទេ","ro": "or-kun, tae <b>ot</b> tei"},{"en": "I don’t need it.","kh": "ខ្ញុំមិនត្រូវការទេ","ro": "khnyom min <b>trov-kaa</b> tei"},{"en": "I can’t today.","kh": "ថ្ងៃនេះខ្ញុំមិនអាចទេ","ro": "thngai nih khnyom min <b>ach</b> tei"},{"en": "Maybe next time.","kh": "ប្រហែលលើកក្រោយ","ro": "bra-hael <b>leuk</b> kraoy"},{"en": "I already have one.","kh": "ខ្ញុំមានហើយ","ro": "khnyom <b>mien</b> haoy"},{"en": "I’m sorry, I’m busy.","kh": "សុំទោស ខ្ញុំរវល់","ro": "som toh, khnyom ro-<b>vol</b>"},{"en": "Please don’t be upset.","kh": "សូមកុំខឹង","ro": "som kom <b>kheung</b>"},{"en": "I’m just looking.","kh": "ខ្ញុំគ្រាន់តែមើល","ro": "khnyom <b>kroan</b>-tae meul"}],"tips": [{"label": "The Smile-and-Keep-Walking","html": "With persistent street sellers, the effective response is not a firmer no but a <b>softer one delivered while still moving</b>: a smile, <span class=\"ro\">ot tei, or-kun</span>, and a small wave without breaking stride. Stopping to explain invites a longer negotiation. Note too that Cambodians rarely refuse outright, so if you hear <span class=\"ro\">bra-hael</span> or <span class=\"ro\">cham meul sen</span> — “let me see” — from someone, that is very often a polite no.","culture": false}],"goal": "Declining an invitation, a price, or a persistent seller — without hardness and without lying.","ch": 7},
{"n": 80,"title": "Keeping in Touch","titleKm": "ការរក្សាទំនាក់ទំនង","scene": "Exchanging numbers at the end of a good conversation. Everyone here is on Telegram.","dialogue": [{"who": "You","kh": "សុំលេខទូរស័ព្ទបានទេ?","ro": "som <b>LEIK</b> tuu-ra-sap baan tei?","en": "May I have your phone number?"},{"who": "Friend","kh": "បាន! អ្នកមានតេឡេក្រាមទេ?","ro": "<b>BAAN</b>! neak mien tei-lei-kraam tei?","en": "Sure! Do you have Telegram?"},{"who": "You","kh": "មាន។ ខ្ញុំនឹងផ្ញើសារទៅ។","ro": "<b>MIEN</b>. khnyom neung phnhaeu saa teuv.","en": "Yes. I’ll message you."},{"who": "Friend","kh": "ទាក់ទងមកបានគ្រប់ពេល។","ro": "<b>TEAK</b>-tong mok baan krop peil.","en": "Get in touch any time."},{"who": "You","kh": "រក្សាទំនាក់ទំនងណា! ជួបគ្នាថ្ងៃក្រោយ។","ro": "rak-<b>SAA</b> tum-neak-tum-nong naa! chuop knie thngai kraoy.","en": "Keep in touch! See you next time."}],"sayit": "<span class=\"kh\">ទាក់ទង</span> <span class=\"ro\">(teak-tong)</span> means “to contact / be in touch”. <span class=\"ro\">teak-tong mok baan krop peil</span> is the standard warm sign-off.","phrases": [{"en": "May I have your number?","kh": "សុំលេខទូរស័ព្ទបានទេ?","ro": "som <b>leik</b> tuu-ra-sap baan tei?"},{"en": "Do you have Telegram?","kh": "អ្នកមានតេឡេក្រាមទេ?","ro": "neak mien tei-lei-<b>kraam</b> tei?"},{"en": "I’ll message you.","kh": "ខ្ញុំនឹងផ្ញើសារទៅ","ro": "khnyom neung <b>phnhaeu</b> saa teuv"},{"en": "Get in touch any time.","kh": "ទាក់ទងមកបានគ្រប់ពេល","ro": "<b>teak</b>-tong mok baan krop peil"},{"en": "Keep in touch!","kh": "រក្សាទំនាក់ទំនងណា!","ro": "rak-<b>saa</b> tum-neak-tum-nong naa!"},{"en": "Add me as a friend.","kh": "បញ្ចូលខ្ញុំជាមិត្ត","ro": "banh-<b>choul</b> khnyom chie mit"},{"en": "I miss you. <em>(a friend)</em>","kh": "ខ្ញុំនឹករលឹកអ្នក","ro": "khnyom <b>neuk</b> ro-leuk neak"},{"en": "Say hello to your family.","kh": "ជម្រាបសួរគ្រួសារជំនួសខ្ញុំ","ro": "chom-riep suor kruo-saa chum-<b>nuoh</b> khnyom"}],"tips": [{"label": "Telegram Is the Address Book","html": "Phone numbers here are held on <b>Telegram</b> rather than in email or on paper, and it is where friends, landlords, drivers, colleagues and shops all reach you. Expect voice messages instead of typed ones — recording a reply is faster than typing Khmer script, and it is excellent listening practice for you. Sending <span class=\"ro\">chom-riep suor kruo-saa chum-nuoh khnyom</span>, “say hello to your family for me”, is a small courtesy that lands very warmly.","culture": false}],"goal": "Exchanging numbers at the end of a good conversation. Everyone here is on Telegram.","ch": 7},
{"n": 81,"title": "Angkor & Temple Tickets","titleKm": "អង្គរ និងសំបុត្រចូលប្រាសាទ","scene": "Buying a pass at the ticket office outside Siem Reap. Decide how many days before you queue.","dialogue": [{"who": "You","kh": "សុំសំបុត្របីថ្ងៃមួយ។","ro": "som som-bot <b>BEI</b> thngai muoy.","en": "One three-day pass, please."},{"who": "Clerk","kh": "ប្រាំមួយសិបពីរដុល្លារ។ សុំថតរូប។","ro": "pram-muoy-sep-<b>PII</b> dol-laa. som thot ruup.","en": "Sixty-two dollars. Photo, please."},{"who": "You","kh": "ប្រាសាទបើកម៉ោងប៉ុន្មាន?","ro": "bra-<b>SAAT</b> baeuk maong pon-man?","en": "What time do the temples open?"},{"who": "Clerk","kh": "ម៉ោងប្រាំព្រឹក ដល់ថ្ងៃលិច។","ro": "maong <b>PRAM</b> pruk, dol thngai lech.","en": "Five in the morning until sunset."},{"who": "You","kh": "តើសំបុត្រនេះប្រើបានប៉ុន្មានថ្ងៃ?","ro": "tae som-bot nih braeu baan pon-man <b>THNGAI</b>?","en": "How many days is this ticket valid for?"}],"sayit": "<span class=\"kh\">ប្រាសាទ</span> <span class=\"ro\">(bra-saat)</span> is a stone temple of the Angkor kind. A living Buddhist monastery is a <span class=\"kh\">វត្ត</span> <span class=\"ro\">(voat)</span> — a different word entirely.","phrases": [{"en": "Ticket","kh": "សំបុត្រ","ro": "som-<b>bot</b>"},{"en": "Temple <em>(Angkorian)</em>","kh": "ប្រាសាទ","ro": "bra-<b>saat</b>"},{"en": "One day / three days","kh": "មួយថ្ងៃ / បីថ្ងៃ","ro": "muoy thngai / <b>bei</b> thngai"},{"en": "What time does it open?","kh": "បើកម៉ោងប៉ុន្មាន?","ro": "<b>baeuk</b> maong pon-man?"},{"en": "Sunrise / sunset","kh": "ថ្ងៃរះ / ថ្ងៃលិច","ro": "thngai <b>reah</b> / thngai <b>lech</b>"},{"en": "Is it far from here?","kh": "ឆ្ងាយពីទីនេះទេ?","ro": "<b>chhngay</b> pii ti-nih tei?"},{"en": "May I go inside?","kh": "ចូលទៅក្នុងបានទេ?","ro": "<b>choul</b> teuv knong baan tei?"},{"en": "It’s magnificent.","kh": "អស្ចារ្យណាស់","ro": "ah-<b>chaa</b> nas"}],"tips": [{"label": "Cover Your Shoulders and Knees","html": "Angkor is a working sacred site, not only a ruin, and the dress code is enforced at the upper level of Angkor Wat: <b>shoulders and knees covered</b> for everyone. Carry a scarf. Go at sunrise for Angkor Wat and late afternoon for Ta Prohm and Bayon, avoiding the coach hours in between. Children selling postcards at the gates should be politely declined — buying encourages families to keep them out of school.","culture": true}],"goal": "Buying a pass at the ticket office outside Siem Reap. Decide how many days before you queue.","ch": 8},
{"n": 82,"title": "Hiring a Guide","titleKm": "ការជួលមគ្គុទេសក៍","scene": "A licensed guide transforms a day of old stones into a day of history. Agree hours and price first.","dialogue": [{"who": "You","kh": "ខ្ញុំចង់ជួលមគ្គុទេសក៍មួយថ្ងៃ។","ro": "khnyom chong chuol mok-ku-<b>TEIH</b> muoy thngai.","en": "I’d like to hire a guide for one day."},{"who": "Guide","kh": "មួយថ្ងៃសែសិបដុល្លារ។","ro": "muoy thngai <b>SAE</b>-sep dol-laa.","en": "Forty dollars a day."},{"who": "You","kh": "រួមទាំងឡានទេ?","ro": "ruom <b>TEANG</b> laan tei?","en": "Does that include transport?"},{"who": "Guide","kh": "មិនរាប់ទេ។ តុកតុកដប់ប្រាំដុល្លារ។","ro": "min <b>ROAB</b> tei. tuk-tuk dop-pram dol-laa.","en": "Not included. A tuk-tuk is fifteen."},{"who": "You","kh": "សូមពន្យល់ជាភាសាអង់គ្លេសយឺតៗ។","ro": "som pon-yul chie phie-saa ong-gleih <b>YOEUT</b>-yoeut.","en": "Please explain in English, slowly."}],"sayit": "<span class=\"kh\">មគ្គុទេសក៍</span> <span class=\"ro\">(mok-ku-teih)</span> is a formal word — you will see it on licence badges. In speech many people simply say <span class=\"ro\">guide</span>.","phrases": [{"en": "Guide","kh": "មគ្គុទេសក៍","ro": "mok-ku-<b>teih</b>"},{"en": "I’d like to hire a guide.","kh": "ខ្ញុំចង់ជួលមគ្គុទេសក៍","ro": "khnyom chong <b>chuol</b> mok-ku-teih"},{"en": "Does that include transport?","kh": "រួមទាំងឡានទេ?","ro": "ruom <b>teang</b> laan tei?"},{"en": "How many hours?","kh": "ប៉ុន្មានម៉ោង?","ro": "pon-man <b>maong</b>?"},{"en": "Please explain slowly.","kh": "សូមពន្យល់យឺតៗ","ro": "som pon-yul <b>yoeut</b>-yoeut"},{"en": "What is the story of this?","kh": "នេះមានរឿងអ្វី?","ro": "nih mien <b>roeung</b> a-vei?"},{"en": "Can we rest a moment?","kh": "សម្រាកបន្តិចបានទេ?","ro": "som-<b>raak</b> bon-tech baan tei?"},{"en": "Thank you, that was excellent.","kh": "អរគុណ ល្អណាស់","ro": "or-kun, <b>la-or</b> nas"}],"tips": [{"label": "Ask to See the Licence","html": "Official Angkor guides carry a <b>photo licence badge</b> and have passed real examinations in history and languages; unlicensed guides are cheaper and often far less informed. Book through your guesthouse or the tourism office. A tip of five to ten dollars at the end of a full day is normal and genuinely appreciated, and a guide who has been treated well will happily take you to the quieter temples nobody else visits.","culture": false}],"goal": "A licensed guide transforms a day of old stones into a day of history. Agree hours and price first.","ch": 8},
{"n": 83,"title": "At the Pagoda","titleKm": "នៅវត្ត","scene": "Visiting a working monastery. Speak quietly, sit low, and know the words for respect.","dialogue": [{"who": "You","kh": "ចូលទៅក្នុងវិហារបានទេ?","ro": "<b>CHOUL</b> teuv knong vi-hie baan tei?","en": "May I go into the temple hall?"},{"who": "Layman","kh": "បាន តែដោះស្បែកជើងសិន។","ro": "baan, tae <b>DOH</b> sbaek-choeung sen.","en": "Yes, but take off your shoes first."},{"who": "You","kh": "ថតរូបបានទេ?","ro": "<b>THOT</b> ruup baan tei?","en": "May I take photographs?"},{"who": "Layman","kh": "បាន តែកុំថតព្រះសង្ឃ។","ro": "baan, tae kom thot preah <b>SONG</b>.","en": "Yes, but not the monks."},{"who": "You","kh": "ខ្ញុំសូមថ្វាយបង្គំព្រះ។","ro": "khnyom som thvay bong-<b>KOM</b> preah.","en": "I would like to pay my respects."}],"sayit": "<span class=\"kh\">ព្រះ</span> <span class=\"ro\">(preah)</span> marks anything sacred — the Buddha, monks, kings. <span class=\"kh\">ព្រះសង្ឃ</span> <span class=\"ro\">(preah song)</span> is a monk, and the word is always said with care.","phrases": [{"en": "Pagoda / monastery","kh": "វត្ត","ro": "<b>voat</b>"},{"en": "Monk","kh": "ព្រះសង្ឃ","ro": "preah <b>song</b>"},{"en": "May I go inside?","kh": "ចូលទៅក្នុងបានទេ?","ro": "<b>choul</b> teuv knong baan tei?"},{"en": "Take off your shoes.","kh": "ដោះស្បែកជើង","ro": "<b>doh</b> sbaek-choeung"},{"en": "May I take a photo?","kh": "ថតរូបបានទេ?","ro": "<b>thot</b> ruup baan tei?"},{"en": "To pay respects","kh": "ថ្វាយបង្គំ","ro": "thvay bong-<b>kom</b>"},{"en": "To make an offering","kh": "ធ្វើបុណ្យ","ro": "thveu <b>bon</b>"},{"en": "It’s very peaceful here.","kh": "នៅទីនេះស្ងប់ស្ងាត់ណាស់","ro": "nov ti-nih <b>sngop</b>-sngat nas"}],"tips": [{"label": "Women Do Not Touch Monks","html": "A monk may not be touched by a woman, nor accept anything directly from her hand — objects are set down on a cloth for him to pick up. This is not a slight; it is monastic discipline, and Cambodian women observe it automatically. Everyone should sit <b>lower than a monk</b>, keep their feet pointed away, and dress with shoulders and knees covered. A donation box at the door is the right place for money.","culture": true}],"goal": "Visiting a working monastery. Speak quietly, sit low, and know the words for respect.","ch": 8},
{"n": 84,"title": "Holidays & Festivals","titleKm": "ពិធីបុណ្យ និងថ្ងៃឈប់សម្រាក","scene": "Three festivals shut the country down. Knowing which is coming saves a great deal of confusion.","dialogue": [{"who": "Colleague","kh": "អាទិត្យក្រោយចូលឆ្នាំខ្មែរ។","ro": "aa-tit kraoy choul chhnam <b>KHMAE</b>.","en": "Next week is Khmer New Year."},{"who": "You","kh": "ឈប់សម្រាកប៉ុន្មានថ្ងៃ?","ro": "chhup som-raak pon-man <b>THNGAI</b>?","en": "How many days is the holiday?"},{"who": "Colleague","kh": "បីថ្ងៃ។ ខ្ញុំត្រឡប់ទៅស្រុក។","ro": "bei thngai. khnyom tro-lop teuv <b>SROK</b>.","en": "Three days. I’m going back to my province."},{"who": "You","kh": "សូមអោយបុណ្យសប្បាយ!","ro": "som aoy <b>BON</b> sa-bay!","en": "Have a happy festival!"},{"who": "You","kh": "តើគេធ្វើអ្វីខ្លះក្នុងបុណ្យនេះ?","ro": "tae kei thveu a-vei <b>KHLAH</b> knong bon nih?","en": "What do people do at this festival?"}],"sayit": "<span class=\"kh\">បុណ្យ</span> <span class=\"ro\">(bon)</span> means both “festival” and “merit”. <span class=\"ro\">thveu bon</span> — “to make merit” — is what the festivals are for.","phrases": [{"en": "Festival","kh": "បុណ្យ","ro": "<b>bon</b>"},{"en": "Khmer New Year","kh": "ចូលឆ្នាំខ្មែរ","ro": "choul chhnam <b>khmae</b>"},{"en": "Pchum Ben <em>(ancestors)</em>","kh": "ភ្ជុំបិណ្ឌ","ro": "pchum <b>ben</b>"},{"en": "Water Festival","kh": "បុណ្យអុំទូក","ro": "bon om <b>touk</b>"},{"en": "How many days off?","kh": "ឈប់សម្រាកប៉ុន្មានថ្ងៃ?","ro": "chhup som-raak pon-man <b>thngai</b>?"},{"en": "Happy festival!","kh": "សូមអោយបុណ្យសប្បាយ!","ro": "som aoy <b>bon</b> sa-bay!"},{"en": "Are the shops open?","kh": "ហាងបើកទេ?","ro": "hang <b>baeuk</b> tei?"},{"en": "I’m going to my home province.","kh": "ខ្ញុំត្រឡប់ទៅស្រុក","ro": "khnyom tro-<b>lop</b> teuv srok"}],"tips": [{"label": "Plan Around the Big Three","html": "<b>Khmer New Year</b> in mid-April empties the cities entirely as everyone returns to their home village; expect water thrown in the streets and almost nothing open for a week. <b>Pchum Ben</b> in September or October is for feeding the ancestors at the pagoda, and is quieter and more solemn. <b>Bon Om Touk</b> in November fills Phnom Penh’s riverside with boat races and enormous crowds. Book transport weeks ahead, or do not travel at all.","culture": true}],"goal": "Three festivals shut the country down. Knowing which is coming saves a great deal of confusion.","ch": 8},
{"n": 85,"title": "At the Beach","titleKm": "នៅឆ្នេរសមុទ្រ","scene": "Renting a chair, ordering a crab, and checking whether it is safe to swim today.","dialogue": [{"who": "You","kh": "ជួលកៅអីមួយថ្ងៃប៉ុន្មាន?","ro": "chuol <b>KAV-EI</b> muoy thngai pon-man?","en": "How much to rent a chair for the day?"},{"who": "Vendor","kh": "មួយដុល្លារ បើទិញម្ហូបគឺឥតគិតថ្លៃ។","ro": "muoy dol-laa; baeu tinh mhoub keu <b>ET</b> ket thlai.","en": "One dollar, free if you buy food."},{"who": "You","kh": "សុំក្ដាមអាំងមួយចាន។","ro": "som <b>KDAAM</b> ang muoy chaan.","en": "One plate of grilled crab, please."},{"who": "You","kh": "ថ្ងៃនេះហែលទឹកបានទេ?","ro": "thngai nih <b>HAEL</b> tuk baan tei?","en": "Is it safe to swim today?"},{"who": "Vendor","kh": "បាន តែរលកខ្លាំងបន្តិច។","ro": "baan, tae ro-<b>LOK</b> khlang bon-tech.","en": "Yes, but the waves are a bit strong."}],"sayit": "<span class=\"kh\">ហែលទឹក</span> <span class=\"ro\">(hael tuk)</span> is “to swim”, literally “swim water”. The sea is <span class=\"kh\">សមុទ្រ</span> <span class=\"ro\">(sa-mot)</span>; a river is <span class=\"kh\">ទន្លេ</span> <span class=\"ro\">(ton-lei)</span>.","phrases": [{"en": "Beach / sea","kh": "ឆ្នេរ / សមុទ្រ","ro": "<b>chhnei</b> / sa-<b>mot</b>"},{"en": "To swim","kh": "ហែលទឹក","ro": "<b>hael</b> tuk"},{"en": "How much to rent a chair?","kh": "ជួលកៅអីប៉ុន្មាន?","ro": "chuol <b>kav-ei</b> pon-man?"},{"en": "Crab / squid / fish","kh": "ក្ដាម / មឹក / ត្រី","ro": "<b>kdaam</b> / <b>meuk</b> / <b>trei</b>"},{"en": "The waves are strong.","kh": "រលកខ្លាំង","ro": "ro-<b>lok</b> khlang"},{"en": "Sunscreen","kh": "ក្រែមការពារកម្ដៅថ្ងៃ","ro": "kraem kaa-<b>pie</b> kom-dav thngai"},{"en": "Boat to the island","kh": "ទូកទៅកោះ","ro": "touk teuv <b>koh</b>"},{"en": "It’s beautiful here.","kh": "នៅទីនេះស្អាតណាស់","ro": "nov ti-nih <b>s-at</b> nas"}],"tips": [{"label": "Cambodians Swim Dressed","html": "On local beaches you will notice Cambodian women swimming fully clothed — shirt, shorts, sometimes a hat. Bikinis are normal on tourist beaches at Otres or on the islands, and quietly out of place at a family beach in Kep or Kampot. Sun and sea are stronger than they look; the sun is directly overhead at midday and the currents around the islands are real. Ask <span class=\"ro\">hael tuk baan tei?</span> before going in.","culture": true}],"goal": "Renting a chair, ordering a crab, and checking whether it is safe to swim today.","ch": 8},
{"n": 86,"title": "Countryside & Villages","titleKm": "ជនបទ និងភូមិ","scene": "Out among the rice fields. Village Khmer is slower and warmer, and everyone will want to talk.","dialogue": [{"who": "Farmer","kh": "មកពីណា បង? វង្វេងទេ?","ro": "mok pii <b>NAA</b>, bong? vong-veng tei?","en": "Where are you from? Are you lost?"},{"who": "You","kh": "អត់ទេ ខ្ញុំមកលេងភូមិ។","ro": "ot tei, khnyom mok leing <b>PHUM</b>.","en": "No, I’ve come to visit the village."},{"who": "You","kh": "ស្រែនេះស្អាតណាស់។ ដាំស្រូវអីខ្លះ?","ro": "<b>SRAE</b> nih s-at nas. dam srov ei khlah?","en": "These fields are beautiful. What rice do you grow?"},{"who": "Farmer","kh": "ស្រូវក្រអូប។ អញ្ជើញផឹកទឹកដូង។","ro": "srov kro-<b>OB</b>. an-choeun pheuk tuk-doung.","en": "Fragrant rice. Come and have a coconut."},{"who": "You","kh": "អរគុណច្រើន បង!","ro": "or-<b>KUN</b> chraen, bong!","en": "Thank you very much!"}],"sayit": "<span class=\"kh\">ស្រែ</span> <span class=\"ro\">(srae)</span> is a rice field; <span class=\"kh\">ស្រូវ</span> <span class=\"ro\">(srov)</span> is rice growing in it; <span class=\"kh\">បាយ</span> <span class=\"ro\">(bay)</span> is cooked rice on your plate. Three words, one crop.","phrases": [{"en": "Village","kh": "ភូមិ","ro": "<b>phum</b>"},{"en": "Rice field","kh": "ស្រែ","ro": "<b>srae</b>"},{"en": "Farmer","kh": "កសិករ","ro": "ka-se-<b>ko</b>"},{"en": "Cow / buffalo / chicken","kh": "គោ / ក្របី / មាន់","ro": "<b>kou</b> / kro-<b>bei</b> / <b>moan</b>"},{"en": "Coconut","kh": "ដូង","ro": "<b>doung</b>"},{"en": "I’ve come to visit.","kh": "ខ្ញុំមកលេង","ro": "khnyom mok <b>leing</b>"},{"en": "Is this road passable?","kh": "ផ្លូវនេះទៅបានទេ?","ro": "<b>phlov</b> nih teuv baan tei?"},{"en": "It’s very peaceful here.","kh": "នៅទីនេះស្ងប់ណាស់","ro": "nov ti-nih <b>sngop</b> nas"}],"tips": [{"label": "Accept the Coconut","html": "Rural hospitality is offered immediately and generously, often by people with very little, and refusing it politely still reads as refusal. <b>Accept</b> the drink or the fruit, sit down for ten minutes, and answer the questions about where you are from — that is the exchange. Never photograph inside a house or of children without asking. And in remote areas near the Thai border, stay on marked paths: unexploded ordnance is still a genuine hazard.","culture": true}],"goal": "Out among the rice fields. Village Khmer is slower and warmer, and everyone will want to talk.","ch": 8},
{"n": 87,"title": "Asking to Take Photos","titleKm": "ការសុំអនុញ្ញាតថតរូប","scene": "Six words that turn a stolen photograph into a shared one — and often into a conversation.","dialogue": [{"who": "You","kh": "សុំថតរូបបានទេ?","ro": "som <b>THOT</b> ruup baan tei?","en": "May I take a photo?"},{"who": "Seller","kh": "បាន! ថតទៅ។","ro": "<b>BAAN</b>! thot teuv.","en": "Yes! Go ahead."},{"who": "You","kh": "សុំថតជាមួយគ្នាបានទេ?","ro": "som thot chie-muoy <b>KNIE</b> baan tei?","en": "May I take one together with you?"},{"who": "You","kh": "ខ្ញុំនឹងផ្ញើរូបទៅឲ្យ។","ro": "khnyom neung phnhaeu <b>RUUP</b> teuv aoy.","en": "I’ll send you the picture."},{"who": "Seller","kh": "អរគុណ! សុំលេខទូរស័ព្ទ។","ro": "or-kun! som <b>LEIK</b> tuu-ra-sap.","en": "Thank you! Give me your number."}],"sayit": "<span class=\"kh\">ថតរូប</span> <span class=\"ro\">(thot ruup)</span> is “to take a photo”. Add <span class=\"ro\">chie-muoy knie</span> — “together” — and you have asked for a picture <em>with</em> someone rather than <em>of</em> them.","phrases": [{"en": "May I take a photo?","kh": "សុំថតរូបបានទេ?","ro": "som <b>thot</b> ruup baan tei?"},{"en": "A photo together?","kh": "ថតជាមួយគ្នាបានទេ?","ro": "thot chie-muoy <b>knie</b> baan tei?"},{"en": "Could you take one of us?","kh": "ជួយថតឲ្យយើងផង","ro": "chuoy <b>thot</b> aoy yeung phong"},{"en": "Please don’t photograph.","kh": "សូមកុំថត","ro": "som kom <b>thot</b>"},{"en": "I’ll send you the picture.","kh": "ខ្ញុំនឹងផ្ញើរូបទៅឲ្យ","ro": "khnyom neung phnhaeu <b>ruup</b> teuv aoy"},{"en": "Smile!","kh": "ញញឹម!","ro": "nho-<b>nheum</b>!"},{"en": "One more, please.","kh": "សុំមួយទៀត","ro": "som muoy <b>tiet</b>"},{"en": "Beautiful photo!","kh": "រូបស្អាតណាស់!","ro": "ruup <b>s-at</b> nas!"}],"tips": [{"label": "Ask, Then Actually Send It","html": "Asking first is the difference between a tourist and a guest, and the answer is nearly always a delighted yes. Then <b>keep the promise</b>: take the person’s Telegram number and send the photograph. Many Cambodians have few good pictures of themselves, and a printed copy delivered on a second visit is a gift people remember for years. Never photograph monks without permission, nor children without a parent’s.","culture": false}],"goal": "Six words that turn a stolen photograph into a shared one — and often into a conversation.","ch": 8},
{"n": 88,"title": "Cinema & Karaoke","titleKm": "រោងកុន និងខារ៉ាអូខេ","scene": "A night out. Karaoke is the national pastime, and you will be handed the microphone.","dialogue": [{"who": "You","kh": "សុំសំបុត្រកុនពីរ។","ro": "som som-bot <b>KON</b> pii.","en": "Two cinema tickets, please."},{"who": "Clerk","kh": "កុនចាប់ផ្ដើមម៉ោងប្រាំពីរ។","ro": "kon chap-phdaeum maong <b>PRAM</b>-pil.","en": "The film starts at seven."},{"who": "Friend","kh": "ក្រោយកុន ទៅច្រៀងខារ៉ាអូខេទេ?","ro": "kraoy kon, teuv <b>CHRIENG</b> kaa-raa-ou-khei tei?","en": "After the film, shall we sing karaoke?"},{"who": "You","kh": "ខ្ញុំច្រៀងមិនពីរោះទេ!","ro": "khnyom chrieng min <b>PI-ROH</b> tei!","en": "I don’t sing well!"},{"who": "Friend","kh": "អត់អីទេ! សប្បាយជាងសំខាន់។","ro": "ot ei tei! <b>SA-BAY</b> chieng som-khan.","en": "Never mind! Having fun matters more."}],"sayit": "<span class=\"kh\">ច្រៀង</span> <span class=\"ro\">(chrieng)</span> is “to sing” and <span class=\"kh\">ពីរោះ</span> <span class=\"ro\">(pi-roh)</span> is “melodious”. The same word praises a singer and a foreigner’s Khmer.","phrases": [{"en": "Cinema / film","kh": "រោងកុន / កុន","ro": "rong-<b>kon</b> / <b>kon</b>"},{"en": "Two tickets, please.","kh": "សុំសំបុត្រពីរ","ro": "som som-<b>bot</b> pii"},{"en": "What time does it start?","kh": "ចាប់ផ្ដើមម៉ោងប៉ុន្មាន?","ro": "chap-<b>phdaeum</b> maong pon-man?"},{"en": "To sing","kh": "ច្រៀង","ro": "<b>chrieng</b>"},{"en": "I don’t sing well.","kh": "ខ្ញុំច្រៀងមិនពីរោះទេ","ro": "khnyom chrieng min <b>pi-roh</b> tei"},{"en": "Your turn!","kh": "វេនអ្នកហើយ!","ro": "<b>vein</b> neak haoy!"},{"en": "A private room","kh": "បន្ទប់ឯកជន","ro": "bon-tup aek-ka-<b>chon</b>"},{"en": "That was fun!","kh": "សប្បាយណាស់!","ro": "sa-<b>bay</b> nas!"}],"tips": [{"label": "Sing Badly, Sing Anyway","html": "Karaoke in Cambodia is done in <b>private rooms</b> with friends and family rather than in front of a bar, and the point is participation, not talent. Refusing the microphone repeatedly is the only real mistake — sing one song, badly, and you will have made a dozen friends. Note that some venues advertised as “KTV” are hostess bars rather than family karaoke; if you are unsure, go where colleagues take you.","culture": true}],"goal": "A night out. Karaoke is the national pastime, and you will be handed the microphone.","ch": 8},
{"n": 89,"title": "Sport & Football","titleKm": "កីឡា និងបាល់ទាត់","scene": "Football is the universal conversation. So is the local boxing on Sunday afternoons.","dialogue": [{"who": "Friend","kh": "យប់នេះមានបាល់ទាត់។ មើលទេ?","ro": "yub nih mien <b>BAL</b>-toat. meul tei?","en": "There’s football tonight. Watching?"},{"who": "You","kh": "មើល! អ្នកគាំទ្រក្រុមណា?","ro": "<b>MEUL</b>! neak koam-tro krom naa?","en": "Yes! Which team do you support?"},{"who": "Friend","kh": "ខ្ញុំគាំទ្រក្រុមកម្ពុជា។","ro": "khnyom koam-<b>TRO</b> krom kam-pu-chie.","en": "I support the Cambodian team."},{"who": "You","kh": "ស្គរប៉ុន្មានហើយ?","ro": "<b>SKO</b> pon-man haoy?","en": "What’s the score?"},{"who": "Friend","kh": "មួយសូន្យ។ ឈ្នះហើយ!","ro": "muoy <b>SOUN</b>. chhneah haoy!","en": "One–nil. We’ve won!"}],"sayit": "<span class=\"kh\">គាំទ្រ</span> <span class=\"ro\">(koam-tro)</span> means “to support”, of a team or a person. <span class=\"kh\">ឈ្នះ</span> <span class=\"ro\">(chhneah)</span> is win; <span class=\"kh\">ចាញ់</span> <span class=\"ro\">(chanh)</span> is lose.","phrases": [{"en": "Football","kh": "បាល់ទាត់","ro": "<b>bal</b>-toat"},{"en": "Team","kh": "ក្រុម","ro": "<b>krom</b>"},{"en": "Which team do you support?","kh": "អ្នកគាំទ្រក្រុមណា?","ro": "neak koam-<b>tro</b> krom naa?"},{"en": "What’s the score?","kh": "ស្គរប៉ុន្មានហើយ?","ro": "<b>sko</b> pon-man haoy?"},{"en": "Win / lose / draw","kh": "ឈ្នះ / ចាញ់ / ស្មើ","ro": "<b>chhneah</b> / <b>chanh</b> / <b>smaeu</b>"},{"en": "Kickboxing <em>(Kun Khmer)</em>","kh": "គុនខ្មែរ","ro": "kun <b>khmae</b>"},{"en": "Shall we play?","kh": "លេងជាមួយគ្នាទេ?","ro": "<b>leing</b> chie-muoy knie tei?"},{"en": "Well played!","kh": "លេងបានល្អណាស់!","ro": "leing baan <b>la-or</b> nas!"}],"tips": [{"label": "Kun Khmer, Not Muay Thai","html": "Cambodia’s traditional kickboxing is <span class=\"kh\">គុនខ្មែរ</span> <span class=\"ro\">(kun khmae)</span>, broadcast live on Sunday afternoons and followed passionately. Calling it Muay Thai will get you a firm correction — the question of which country originated the sport is a genuinely sensitive one. Football is the other national obsession, and an evening watching the Cambodian national team in a riverside café is one of the easiest ways into ordinary conversation.","culture": true}],"goal": "Football is the universal conversation. So is the local boxing on Sunday afternoons.","ch": 8},
{"n": 90,"title": "Speaking of History","titleKm": "ការនិយាយអំពីប្រវត្តិសាស្ត្រ","scene": "The hardest conversation in this book. Listen far more than you speak, and let the other person lead.","dialogue": [{"who": "You","kh": "ខ្ញុំចង់រៀនប្រវត្តិសាស្ត្រកម្ពុជា។","ro": "khnyom chong rien bra-voat-te-<b>SAAH</b> kam-pu-chie.","en": "I want to learn Cambodian history."},{"who": "Friend","kh": "សម័យអង្គរ គឺជាសម័យរុងរឿង។","ro": "sa-may <b>ANG-KO</b> keu chie sa-may rung-roeung.","en": "The Angkor period was a golden age."},{"who": "You","kh": "ខ្ញុំបានទៅសារមន្ទីរតួលស្លែង។","ro": "khnyom baan teuv saa-ra-mon-<b>TII</b> Tuol Sleng.","en": "I visited the Tuol Sleng museum."},{"who": "Friend","kh": "គ្រួសារយើងជាច្រើនបានបាត់បង់។","ro": "kruo-saa yeung chie chraen baan <b>BAT</b>-bong.","en": "Many of our families were lost."},{"who": "You","kh": "ខ្ញុំសោកស្ដាយណាស់។ អរគុណដែលប្រាប់។","ro": "khnyom saok-<b>SDAY</b> nas. or-kun dael brab.","en": "I’m very sorry. Thank you for telling me."}],"sayit": "<span class=\"kh\">សោកស្ដាយ</span> <span class=\"ro\">(saok-sday)</span> means “to be sorry / to grieve” — sorrow, not apology. It is the right word when someone tells you of a loss.","phrases": [{"en": "History","kh": "ប្រវត្តិសាស្ត្រ","ro": "bra-voat-te-<b>saah</b>"},{"en": "The Angkor period","kh": "សម័យអង្គរ","ro": "sa-may <b>ang-ko</b>"},{"en": "I want to learn about …","kh": "ខ្ញុំចង់រៀនអំពី …","ro": "khnyom chong <b>rien</b> om-pii …"},{"en": "Museum","kh": "សារមន្ទីរ","ro": "saa-ra-mon-<b>tii</b>"},{"en": "I’m very sorry. <em>(for a loss)</em>","kh": "ខ្ញុំសោកស្ដាយណាស់","ro": "khnyom saok-<b>sday</b> nas"},{"en": "Thank you for telling me.","kh": "អរគុណដែលប្រាប់ខ្ញុំ","ro": "or-kun dael <b>brab</b> khnyom"},{"en": "Cambodia is at peace now.","kh": "ឥឡូវកម្ពុជាមានសន្តិភាព","ro": "eu-lov kam-pu-chie mien son-te-<b>phiep</b>"},{"en": "I admire your country.","kh": "ខ្ញុំកោតសរសើរប្រទេសអ្នក","ro": "khnyom kaot sor-<b>saeu</b> bra-teih neak"}],"tips": [{"label": "Let Them Raise It First","html": "Almost every Cambodian family lost people under the Khmer Rouge, and almost everyone you meet is connected to that loss. It is not a topic to open over lunch out of curiosity. If someone chooses to tell you their family’s story, that is a considerable trust: <b>listen, don’t compare, don’t ask for details</b>, and thank them. Visit Tuol Sleng and Choeung Ek quietly and without photographing yourself there. Cambodians are far more eager to talk about Angkor, about their food and about the future.","culture": true}],"goal": "The hardest conversation in this book. Listen far more than you speak, and let the other person lead.","ch": 8},
{"n": 91,"title": "Post Office & Parcels","titleKm": "ប្រៃសណីយ៍ និងកញ្ចប់","scene": "Sending something home. Ask the price both ways — air and sea differ enormously.","dialogue": [{"who": "You","kh": "ខ្ញុំចង់ផ្ញើកញ្ចប់ទៅបារាំង។","ro": "khnyom chong phnhaeu kon-<b>CHOP</b> teuv baa-rang.","en": "I’d like to send a parcel to France."},{"who": "Clerk","kh": "ផ្ញើតាមអាកាស ឬតាមសមុទ្រ?","ro": "phnhaeu taam aa-<b>KAAH</b> reu taam sa-mot?","en": "By air or by sea?"},{"who": "You","kh": "តាមអាកាស។ ថ្លៃប៉ុន្មាន?","ro": "taam aa-<b>KAAH</b>. thlai pon-man?","en": "By air. How much?"},{"who": "Clerk","kh": "សែសិបដុល្លារ ដល់ក្នុងពីរអាទិត្យ។","ro": "<b>SAE</b>-sep dol-laa, dol knong pii aa-tit.","en": "Forty dollars, arriving in two weeks."},{"who": "You","kh": "សុំលេខតាមដានផង។","ro": "som leik taam-<b>DAAN</b> phong.","en": "A tracking number, please."}],"sayit": "<span class=\"kh\">ផ្ញើ</span> <span class=\"ro\">(phnhaeu)</span> covers sending parcels, messages and money alike. <span class=\"kh\">តាមដាន</span> <span class=\"ro\">(taam-daan)</span> means “to track / follow”.","phrases": [{"en": "Post office","kh": "ប្រៃសណីយ៍","ro": "prai-sa-<b>nii</b>"},{"en": "Parcel / letter","kh": "កញ្ចប់ / សំបុត្រ","ro": "kon-<b>chop</b> / som-<b>bot</b>"},{"en": "I want to send this to …","kh": "ខ្ញុំចង់ផ្ញើវាទៅ …","ro": "khnyom chong <b>phnhaeu</b> vie teuv …"},{"en": "By air / by sea","kh": "តាមអាកាស / តាមសមុទ្រ","ro": "taam aa-<b>kaah</b> / taam sa-<b>mot</b>"},{"en": "How many days will it take?","kh": "ប៉ុន្មានថ្ងៃទើបដល់?","ro": "pon-man thngai teub <b>dol</b>?"},{"en": "Tracking number","kh": "លេខតាមដាន","ro": "leik taam-<b>daan</b>"},{"en": "Stamp","kh": "តែម","ro": "<b>taem</b>"},{"en": "It’s fragile.","kh": "វាងាយបែក","ro": "vie <b>ngiey</b> baek"}],"tips": [{"label": "Use a Courier for Anything Valuable","html": "The state post is inexpensive but slow, and parcels are opened for customs inspection as a matter of routine. For documents or anything of value, use an international courier — more expensive, insured, and genuinely trackable. Never post cash. Note that incoming parcels frequently attract a customs charge on collection, and that the address to give senders is the <b>post office box</b>, since street delivery outside the main cities is limited.","culture": false}],"goal": "Sending something home. Ask the price both ways — air and sea differ enormously.","ch": 9},
{"n": 92,"title": "Visa Extension","titleKm": "ការពន្យារទិដ្ឋាការ","scene": "At the immigration office. Bring the passport, the photos and more patience than you think you need.","dialogue": [{"who": "You","kh": "ខ្ញុំចង់ពន្យារទិដ្ឋាការ។","ro": "khnyom chong pon-yie tet-thaa-<b>KAA</b>.","en": "I’d like to extend my visa."},{"who": "Officer","kh": "ពន្យារប៉ុន្មានខែ?","ro": "pon-yie pon-man <b>KHAE</b>?","en": "For how many months?"},{"who": "You","kh": "មួយឆ្នាំ។ ត្រូវការឯកសារអ្វីខ្លះ?","ro": "muoy chhnam. trov-kaa aek-ka-<b>SAA</b> a-vei khlah?","en": "One year. What documents do I need?"},{"who": "Officer","kh": "លិខិតឆ្លងដែន និងរូបថតពីរសន្លឹក។","ro": "li-khet chhlong-daen ning ruup-<b>THOT</b> pii son-leuk.","en": "Passport and two photographs."},{"who": "You","kh": "ពេលណាមកយកវិញ?","ro": "peil naa mok <b>YOK</b> vinh?","en": "When do I collect it?"}],"sayit": "<span class=\"kh\">ពន្យារ</span> <span class=\"ro\">(pon-yie)</span> means “to extend / postpone” — the same verb for a visa, a deadline and a meeting.","phrases": [{"en": "Visa","kh": "ទិដ្ឋាការ","ro": "tet-thaa-<b>kaa</b>"},{"en": "I’d like to extend my visa.","kh": "ខ្ញុំចង់ពន្យារទិដ្ឋាការ","ro": "khnyom chong pon-<b>yie</b> tet-thaa-kaa"},{"en": "Immigration office","kh": "អន្តោប្រវេសន៍","ro": "an-tou-bra-<b>veih</b>"},{"en": "Documents","kh": "ឯកសារ","ro": "aek-ka-<b>saa</b>"},{"en": "Photographs","kh": "រូបថត","ro": "ruup-<b>thot</b>"},{"en": "Work permit","kh": "លិខិតអនុញ្ញាតការងារ","ro": "li-khet a-nu-<b>nhat</b> kaa-ngie"},{"en": "My visa has expired.","kh": "ទិដ្ឋាការខ្ញុំផុតកំណត់","ro": "tet-thaa-kaa khnyom <b>phot</b> kom-not"},{"en": "When can I collect it?","kh": "ពេលណាមកយកវិញ?","ro": "peil naa mok <b>yok</b> vinh?"}],"tips": [{"label": "Get the Right Visa on Arrival","html": "The tourist visa (T) can be extended only once, for a month. The ordinary visa (E) is the one that extends for six months or a year and permits work — and you <b>cannot switch from T to E</b> without leaving the country. Ask for the E class at the airport if there is any chance you will stay. Overstaying is fined per day at the border and quickly becomes expensive; most long-term residents use an agent, which costs a little more and saves the queue entirely.","culture": false}],"goal": "At the immigration office. Bring the passport, the photos and more patience than you think you need.","ch": 9},
{"n": 93,"title": "Barber & Hair Salon","titleKm": "ហាងកាត់សក់","scene": "A haircut costs a couple of dollars. Say how much to take off — and show a photo if you can.","dialogue": [{"who": "You","kh": "សុំកាត់សក់។ ខ្លីបន្តិច។","ro": "som kat <b>SOK</b>. khlei bon-tech.","en": "A haircut, please. A little short."},{"who": "Barber","kh": "ខ្លីប៉ុណ្ណា? ខាងក្រោយវិញ?","ro": "<b>KHLEI</b> pon-naa? khang-kraoy vinh?","en": "How short? And the back?"},{"who": "You","kh": "ខាងក្រោយខ្លី ខាងលើទុកវែង។","ro": "khang-kraoy <b>KHLEI</b>, khang-leu tuk veng.","en": "Short at the back, leave the top long."},{"who": "You","kh": "កុំកាត់ខ្លីពេក។","ro": "kom kat <b>KHLEI</b> peik.","en": "Don’t cut it too short."},{"who": "Barber","kh": "កោរពុកមាត់ផងទេ?","ro": "<b>KAO</b> puk-moat phong tei?","en": "Shall I shave you as well?"}],"sayit": "<span class=\"kh\">ខ្លី</span> <span class=\"ro\">(khlei)</span> is short and <span class=\"kh\">វែង</span> <span class=\"ro\">(veng)</span> is long. Add <span class=\"ro\">peik</span> — “too” — for the word every haircut needs: <span class=\"ro\">kom kat khlei peik</span>.","phrases": [{"en": "Haircut","kh": "កាត់សក់","ro": "kat <b>sok</b>"},{"en": "Short / long","kh": "ខ្លី / វែង","ro": "<b>khlei</b> / <b>veng</b>"},{"en": "Don’t cut it too short.","kh": "កុំកាត់ខ្លីពេក","ro": "kom kat <b>khlei</b> peik"},{"en": "Just a trim.","kh": "កាត់តិចតួច","ro": "kat <b>tech</b>-tuoch"},{"en": "Shave","kh": "កោរពុកមាត់","ro": "<b>kao</b> puk-moat"},{"en": "Wash my hair, please.","kh": "សុំកក់សក់ផង","ro": "som <b>kok</b> sok phong"},{"en": "Like this photo","kh": "ដូចរូបនេះ","ro": "<b>douch</b> ruup nih"},{"en": "That’s perfect, thank you.","kh": "ល្អហើយ អរគុណ","ro": "<b>la-or</b> haoy, or-kun"}],"tips": [{"label": "Show a Picture","html": "Hair vocabulary is where careful learners still come unstuck, and the consequences last a month. <b>Show a photograph on your phone</b> and use <span class=\"ro\">douch ruup nih</span> — “like this picture”. A cut usually includes a hair wash, a head and shoulder massage and sometimes an ear cleaning, all for two or three dollars. If you would rather skip the ear cleaning, <span class=\"ro\">min bach tei, or-kun</span> declines it politely.","culture": false}],"goal": "A haircut costs a couple of dollars. Say how much to take off — and show a photo if you can.","ch": 9},
{"n": 94,"title": "Talking to Children","titleKm": "ការនិយាយជាមួយក្មេងៗ","scene": "Children will call out to you everywhere. A few words back and you will have made their day.","dialogue": [{"who": "Child","kh": "ហេឡូ! ហេឡូ!","ro": "hei-<b>LOU</b>! hei-lou!","en": "Hello! Hello!"},{"who": "You","kh": "សួស្តី! ប្អូនឈ្មោះអ្វី?","ro": "suor-sdei! <b>P’OUN</b> chhmuoh a-vei?","en": "Hi! What’s your name?"},{"who": "Child","kh": "ខ្ញុំឈ្មោះស្រីនាង។ អាយុប្រាំបីឆ្នាំ។","ro": "khnyom chhmuoh Srey Neang. aa-yuk <b>PRAM</b>-bei chhnam.","en": "I’m Srey Neang. I’m eight years old."},{"who": "You","kh": "ប្អូនរៀនថ្នាក់ទីប៉ុន្មាន?","ro": "p’oun rien thnak ti <b>PON-MAN</b>?","en": "What grade are you in?"},{"who": "You","kh": "ពូកែណាស់! រៀនឲ្យបានល្អណា។","ro": "pu-<b>KAE</b> nas! rien aoy baan la-or naa.","en": "Very clever! Study well."}],"sayit": "Call a child <span class=\"kh\">ប្អូន</span> <span class=\"ro\">(p’oun)</span> — “younger one”. They will call you <span class=\"ro\">bong</span>, or <span class=\"ro\">om</span> if you are their parents’ age or older.","phrases": [{"en": "Child / children","kh": "ក្មេង / ក្មេងៗ","ro": "<b>kmeng</b> / kmeng-<b>kmeng</b>"},{"en": "What’s your name? <em>(to a child)</em>","kh": "ប្អូនឈ្មោះអ្វី?","ro": "<b>p’oun</b> chhmuoh a-vei?"},{"en": "How old are you?","kh": "អាយុប៉ុន្មានឆ្នាំ?","ro": "aa-yuk pon-man <b>chhnam</b>?"},{"en": "Do you go to school?","kh": "ទៅសាលារៀនទេ?","ro": "teuv saa-lie-<b>rien</b> tei?"},{"en": "Very clever!","kh": "ពូកែណាស់!","ro": "pu-<b>kae</b> nas!"},{"en": "Study hard.","kh": "រៀនឲ្យបានល្អ","ro": "<b>rien</b> aoy baan la-or"},{"en": "Be careful!","kh": "ប្រយ័ត្ន!","ro": "bra-<b>yat</b>!"},{"en": "Where is your mother?","kh": "ម្ដាយប្អូននៅឯណា?","ro": "<b>mdaay</b> p’oun nov ae-naa?"}],"tips": [{"label": "Don’t Pat the Head","html": "Ruffling a child’s hair is affectionate in the West and quietly wrong here: the head is the most sacred part of the body. A smile, a wave and a question about school are the right warmth. Please also do not hand money or sweets to begging children, however hard that is — it keeps them working the streets instead of at school. If you want to help, give to a school or a registered organisation instead.","culture": true}],"goal": "Children will call out to you everywhere. A few words back and you will have made their day.","ch": 9},
{"n": 95,"title": "Pets & the Vet","titleKm": "សត្វចិញ្ចឹម និងពេទ្យសត្វ","scene": "Taking a dog or cat to the clinic, and the words for the street dogs you will meet everywhere.","dialogue": [{"who": "You","kh": "ឆ្កែខ្ញុំឈឺ មិនញ៉ាំអាហារ។","ro": "<b>CHHKAE</b> khnyom chheu, min nyam aa-haa.","en": "My dog is sick, it isn’t eating."},{"who": "Vet","kh": "ប៉ុន្មានថ្ងៃហើយ? អាយុប៉ុន្មាន?","ro": "pon-man thngai haoy? <b>AA-YUK</b> pon-man?","en": "For how long? How old is it?"},{"who": "You","kh": "ពីរថ្ងៃ។ អាយុបីឆ្នាំ។","ro": "<b>PII</b> thngai. aa-yuk bei chhnam.","en": "Two days. It’s three years old."},{"who": "Vet","kh": "ត្រូវចាក់វ៉ាក់សាំងផងទេ?","ro": "trov chak <b>VAK</b>-sang phong tei?","en": "Does it need vaccinations as well?"},{"who": "You","kh": "បាទ ចាក់ថ្នាំកំចាត់ឆ្កួតជ្រូកផង។","ro": "baat, chak thnam kom-chat <b>CHHKUOT</b> phong.","en": "Yes, the rabies vaccination too."}],"sayit": "<span class=\"kh\">ឆ្កែ</span> <span class=\"ro\">(chhkae)</span> is dog and <span class=\"kh\">ឆ្មា</span> <span class=\"ro\">(chhmaa)</span> is cat. Both begin with the breathy <em>chh</em> that also starts <span class=\"ro\">chheu</span>, to hurt.","phrases": [{"en": "Dog / cat","kh": "ឆ្កែ / ឆ្មា","ro": "<b>chhkae</b> / <b>chhmaa</b>"},{"en": "Vet","kh": "ពេទ្យសត្វ","ro": "peit <b>sat</b>"},{"en": "My dog is sick.","kh": "ឆ្កែខ្ញុំឈឺ","ro": "<b>chhkae</b> khnyom chheu"},{"en": "It isn’t eating.","kh": "វាមិនញ៉ាំអាហារ","ro": "vie min <b>nyam</b> aa-haa"},{"en": "Vaccination","kh": "ចាក់វ៉ាក់សាំង","ro": "chak <b>vak</b>-sang"},{"en": "Does it bite?","kh": "វាខាំទេ?","ro": "vie <b>kham</b> tei?"},{"en": "A dog bit me.","kh": "ឆ្កែខាំខ្ញុំ","ro": "chhkae <b>kham</b> khnyom"},{"en": "Pet food","kh": "ចំណីសត្វ","ro": "chom-<b>nei</b> sat"}],"tips": [{"label": "Rabies Is Real Here","html": "Cambodia has one of the world’s highest rates of rabies deaths, and street dogs are everywhere. Do not approach or feed them, and if you are bitten or even scratched, <b>wash the wound with soap for fifteen minutes and get to a clinic the same day</b> — the Institut Pasteur in Phnom Penh provides the vaccine. Pre-exposure vaccination is well worth it for anyone living here, especially cyclists and families with children.","culture": false}],"goal": "Taking a dog or cat to the clinic, and the words for the street dogs you will meet everywhere.","ch": 9},
{"n": 96,"title": "Traffic, Noise & Grumbles","titleKm": "ចរាចរណ៍ សំឡេង និងការត្អូញត្អែរ","scene": "The daily complaints of city life. Shared grumbling is a genuine social glue — join in.","dialogue": [{"who": "Friend","kh": "ថ្ងៃនេះស្ទះចរាចរណ៍ខ្លាំងណាស់។","ro": "thngai nih <b>STOAH</b> cha-raa-chor khlang nas.","en": "The traffic is terrible today."},{"who": "You","kh": "មែនហើយ! ខ្ញុំមកយឺតកន្លះម៉ោង។","ro": "maen haoy! khnyom mok <b>YOEUT</b> kon-lah maong.","en": "Yes! I was half an hour late."},{"who": "You","kh": "យប់មិញសំឡេងខ្លាំងណាស់។","ro": "yub minh <b>SOM-LENG</b> khlang nas.","en": "Last night was so noisy."},{"who": "Friend","kh": "មានពិធីមង្គលការជិតផ្ទះ។","ro": "mien pi-thii mong-kol-<b>KAA</b> chit phteah.","en": "There’s a wedding near the house."},{"who": "You","kh": "ធូលីច្រើនណាស់ក្នុងរដូវប្រាំង។","ro": "thou-<b>LII</b> chraen nas knong ro-dov prang.","en": "So much dust in the dry season."}],"sayit": "<span class=\"kh\">ស្ទះ</span> <span class=\"ro\">(stoah)</span> means “blocked” — of traffic, a drain or a nose alike. <span class=\"ro\">stoah cha-raa-chor</span> is a traffic jam.","phrases": [{"en": "Traffic jam","kh": "ស្ទះចរាចរណ៍","ro": "<b>stoah</b> cha-raa-chor"},{"en": "I was late.","kh": "ខ្ញុំមកយឺត","ro": "khnyom mok <b>yoeut</b>"},{"en": "It’s very noisy.","kh": "សំឡេងខ្លាំងណាស់","ro": "<b>som-leng</b> khlang nas"},{"en": "Dust","kh": "ធូលី","ro": "thou-<b>lii</b>"},{"en": "The road is flooded.","kh": "ផ្លូវលិចទឹក","ro": "phlov <b>lech</b> tuk"},{"en": "Be careful on the road.","kh": "ប្រយ័ត្នពេលបើកបរ","ro": "bra-<b>yat</b> peil baeuk-bor"},{"en": "It’s always like this.","kh": "តែងតែបែបនេះ","ro": "taeng-tae <b>baep</b> nih"},{"en": "Never mind, that’s life.","kh": "អត់អីទេ ជីវិតបែបនេះ","ro": "ot ei tei, <b>chi-vit</b> baep nih"}],"tips": [{"label": "Grumble Sideways, Not Upward","html": "Complaining companionably about heat, traffic and dust is friendly and expected; complaining <em>at</em> a person about their service or their country is not, and lands much harder than you intend. Note the useful national shrug: <span class=\"kh\">អត់អីទេ</span> <span class=\"ro\">(ot ei tei)</span> — “never mind”. It carries a genuine Buddhist patience with things that cannot be changed, and reaching for it instead of frustration will make your life here considerably easier.","culture": true}],"goal": "The daily complaints of city life. Shared grumbling is a genuine social glue — join in.","ch": 9},
{"n": 97,"title": "Opinions & Disagreeing","titleKm": "មតិ និងការមិនយល់ស្រប","scene": "Saying what you think, and differing without confrontation. The softening words are the skill here.","dialogue": [{"who": "Friend","kh": "អ្នកគិតយ៉ាងម៉េចដែរ?","ro": "neak ket yang <b>MECH</b> dae?","en": "What do you think?"},{"who": "You","kh": "ខ្ញុំគិតថាវាល្អ។","ro": "khnyom <b>KET</b> thaa vie la-or.","en": "I think it’s good."},{"who": "Friend","kh": "ខ្ញុំមិនសូវយល់ស្របទេ។","ro": "khnyom min sao yul-<b>SROP</b> tei.","en": "I don’t quite agree."},{"who": "You","kh": "អ្នកនិយាយត្រូវដែរ។","ro": "neak ni-yiey <b>TROV</b> dae.","en": "You have a point too."},{"who": "You","kh": "តាមខ្ញុំគិត ប្រហែលបែបនេះល្អជាង។","ro": "taam khnyom ket, bra-hael <b>BAEP</b> nih la-or chieng.","en": "In my view, perhaps this way is better."}],"sayit": "<span class=\"kh\">មិនសូវ</span> <span class=\"ro\">(min sao)</span> means “not very / not quite” and is the great softener. <span class=\"ro\">min sao yul-srop</span> is a firm disagreement wearing good manners.","phrases": [{"en": "What do you think?","kh": "អ្នកគិតយ៉ាងម៉េចដែរ?","ro": "neak ket yang <b>mech</b> dae?"},{"en": "I think that …","kh": "ខ្ញុំគិតថា …","ro": "khnyom <b>ket</b> thaa …"},{"en": "In my view","kh": "តាមខ្ញុំគិត","ro": "taam khnyom <b>ket</b>"},{"en": "I agree.","kh": "ខ្ញុំយល់ស្រប","ro": "khnyom yul-<b>srop</b>"},{"en": "I don’t quite agree.","kh": "ខ្ញុំមិនសូវយល់ស្របទេ","ro": "khnyom min sao yul-<b>srop</b> tei"},{"en": "You have a point.","kh": "អ្នកនិយាយត្រូវដែរ","ro": "neak ni-yiey <b>trov</b> dae"},{"en": "Maybe / perhaps","kh": "ប្រហែល","ro": "bra-<b>hael</b>"},{"en": "It depends.","kh": "អាស្រ័យ","ro": "aa-<b>srey</b>"}],"tips": [{"label": "Avoid Politics With Strangers","html": "Cambodians discuss food, family, football and money freely, and national politics far more carefully — particularly with a foreigner they have just met. If a political conversation starts, listen and ask questions rather than offering verdicts about a country you are a guest in. The same applies to religion. <span class=\"ro\">Aa-srey</span>, “it depends”, and <span class=\"ro\">bra-hael</span>, “perhaps”, are perfectly respectable places to leave an opinion.","culture": true}],"goal": "Saying what you think, and differing without confrontation. The softening words are the skill here.","ch": 9},
{"n": 98,"title": "Telling a Story","titleKm": "ការនិទានរឿង","scene": "Khmer verbs never change form. Past, present and future are handled by three little words.","dialogue": [{"who": "Friend","kh": "ម្សិលមិញអ្នកទៅណា?","ro": "msel-minh neak <b>TEUV</b> naa?","en": "Where did you go yesterday?"},{"who": "You","kh": "ខ្ញុំបានទៅសៀមរាប។","ro": "khnyom <b>BAAN</b> teuv siem-riep.","en": "I went to Siem Reap."},{"who": "You","kh": "កាលពីម្សិលមិញភ្លៀងធ្លាក់ខ្លាំង។","ro": "kaal-pii msel-minh <b>PLEANG</b> thleak khlang.","en": "Yesterday it rained heavily."},{"who": "You","kh": "ឥឡូវខ្ញុំកំពុងសម្រាក។","ro": "eu-lov khnyom <b>KOM-PUNG</b> som-raak.","en": "Right now I’m resting."},{"who": "You","kh": "ថ្ងៃស្អែកខ្ញុំនឹងទៅធ្វើការ។","ro": "thngai sa-aek khnyom <b>NEUNG</b> teuv thveu kaa.","en": "Tomorrow I will go to work."}],"sayit": "Three markers carry all of Khmer tense: <span class=\"kh\">បាន</span> <span class=\"ro\">(baan)</span> before a verb for the past, <span class=\"kh\">កំពុង</span> <span class=\"ro\">(kom-pung)</span> for right now, <span class=\"kh\">នឹង</span> <span class=\"ro\">(neung)</span> for the future.","phrases": [{"en": "Past marker <em>(before the verb)</em>","kh": "បាន","ro": "<b>baan</b>"},{"en": "Happening now","kh": "កំពុង","ro": "<b>kom-pung</b>"},{"en": "Future marker","kh": "នឹង","ro": "<b>neung</b>"},{"en": "Yesterday / today / tomorrow","kh": "ម្សិលមិញ / ថ្ងៃនេះ / ថ្ងៃស្អែក","ro": "msel-<b>minh</b> / thngai nih / thngai <b>sa-aek</b>"},{"en": "Last week / next week","kh": "អាទិត្យមុន / អាទិត្យក្រោយ","ro": "aa-tit <b>mun</b> / aa-tit <b>kraoy</b>"},{"en": "Then / after that","kh": "បន្ទាប់មក","ro": "bon-<b>toab</b> mok"},{"en": "Suddenly","kh": "ភ្លាមៗ","ro": "<b>phliem</b>-phliem"},{"en": "Really? / is that so?","kh": "មែនអ៊ីចឹង?","ro": "<b>maen</b> ei-cheung?"}],"tips": [{"label": "The Time Word Does the Work","html": "Because verbs never conjugate, Khmer usually drops the tense marker altogether once a time word has been said: <span class=\"ro\">msel-minh khnyom teuv …</span> — “yesterday I go” — is complete and natural. Put the time word at the <b>front of the sentence</b> and the rest looks after itself. This is the moment most learners realise Khmer grammar is far kinder than its script suggests.","culture": false}],"goal": "Khmer verbs never change form. Past, present and future are handled by three little words.","ch": 9},
{"n": 99,"title": "Requests & Favours","titleKm": "ការស្នើសុំ និងជំនួយ","scene": "Asking for help, and offering it. One structure — <em>chuoy … phong</em> — does almost all of it.","dialogue": [{"who": "You","kh": "សុំរំខានបន្តិច។ ជួយខ្ញុំបានទេ?","ro": "som rom-<b>KHAN</b> bon-tech. chuoy khnyom baan tei?","en": "Sorry to bother you. Could you help me?"},{"who": "Friend","kh": "បាន! មានរឿងអ្វី?","ro": "<b>BAAN</b>! mien roeung a-vei?","en": "Sure! What is it?"},{"who": "You","kh": "ជួយបកប្រែឲ្យខ្ញុំបន្តិចផង។","ro": "chuoy bok-<b>BRAE</b> aoy khnyom bon-tech phong.","en": "Please translate this for me."},{"who": "Friend","kh": "អត់បញ្ហាទេ។","ro": "ot bon-<b>HAA</b> tei.","en": "No problem at all."},{"who": "You","kh": "អរគុណណាស់ អ្នកជួយខ្ញុំច្រើន។","ro": "or-kun nas, neak <b>CHUOY</b> khnyom chraen.","en": "Thank you, you’ve helped me a lot."}],"sayit": "The polite request frame is <span class=\"ro\">chuoy</span> + verb + <span class=\"ro\">phong</span>. <span class=\"kh\">សុំរំខានបន្តិច</span> <span class=\"ro\">(som rom-khan bon-tech)</span> — “sorry to disturb” — is the perfect opener.","phrases": [{"en": "Sorry to bother you.","kh": "សុំរំខានបន្តិច","ro": "som rom-<b>khan</b> bon-tech"},{"en": "Could you help me?","kh": "ជួយខ្ញុំបានទេ?","ro": "<b>chuoy</b> khnyom baan tei?"},{"en": "Please translate for me.","kh": "ជួយបកប្រែឲ្យខ្ញុំផង","ro": "chuoy bok-<b>brae</b> aoy khnyom phong"},{"en": "Could you lend me …?","kh": "ខ្ចី … បានទេ?","ro": "<b>khchei</b> … baan tei?"},{"en": "No problem at all.","kh": "អត់បញ្ហាទេ","ro": "ot bon-<b>haa</b> tei"},{"en": "Can I help you?","kh": "ខ្ញុំជួយអ្នកបានទេ?","ro": "khnyom <b>chuoy</b> neak baan tei?"},{"en": "You’ve helped me a lot.","kh": "អ្នកជួយខ្ញុំច្រើន","ro": "neak <b>chuoy</b> khnyom chraen"},{"en": "I owe you one.","kh": "ខ្ញុំជំពាក់គុណអ្នក","ro": "khnyom chum-<b>peak</b> kun neak"}],"tips": [{"label": "Favours Are a Ledger, Not a Transaction","html": "Help given here creates a warm, unspoken obligation that runs in both directions and is never settled with cash. If a colleague spends their Saturday helping you deal with a landlord, the way to repay it is to be available when their family needs something — not to hand them money, which turns a friendship into a service. The word for this debt of kindness is <span class=\"kh\">គុណ</span> <span class=\"ro\">(kun)</span>, and it also sits inside <span class=\"ro\">or-kun</span>, thank you.","culture": true}],"goal": "Asking for help, and offering it. One structure — chuoy … phong — does almost all of it.","ch": 9},
{"n": 100,"title": "Farewells & Blessings","titleKm": "ការលា និងការជូនពរ","scene": "The last page. Leaving well matters as much as arriving well — and takes longer than you expect.","dialogue": [{"who": "You","kh": "ខ្ញុំនឹងត្រឡប់ទៅស្រុកខ្ញុំវិញ។","ro": "khnyom neung tro-lop teuv <b>SROK</b> khnyom vinh.","en": "I’m going back to my country."},{"who": "Friend","kh": "យើងនឹងនឹករលឹកអ្នកណាស់។","ro": "yeung neung <b>NEUK</b> ro-leuk neak nas.","en": "We will miss you very much."},{"who": "You","kh": "អរគុណសម្រាប់អ្វីៗទាំងអស់។","ro": "or-kun som-rap a-vei-vei <b>TEANG</b>-oh.","en": "Thank you for everything."},{"who": "Friend","kh": "សូមធ្វើដំណើរដោយសុវត្ថិភាព។","ro": "som thveu dom-naeu daoy so-vat-thi-<b>PHIEP</b>.","en": "Have a safe journey."},{"who": "You","kh": "ខ្ញុំនឹងត្រឡប់មកវិញ។ ជម្រាបលា។","ro": "khnyom neung tro-lop <b>MOK</b> vinh. chom-riep lie.","en": "I’ll come back. Goodbye."}],"sayit": "<span class=\"kh\">ជម្រាបលា</span> <span class=\"ro\">(chom-riep lie)</span> is the formal farewell, the mirror of <span class=\"ro\">chom-riep suor</span> on page one. You have come full circle.","phrases": [{"en": "Goodbye <em>(formal)</em>","kh": "ជម្រាបលា","ro": "chom-<b>riep</b> lie"},{"en": "Have a safe journey.","kh": "សូមធ្វើដំណើរដោយសុវត្ថិភាព","ro": "som thveu dom-naeu daoy so-vat-thi-<b>phiep</b>"},{"en": "Good luck!","kh": "សូមឲ្យមានសំណាងល្អ!","ro": "som aoy mien som-<b>nang</b> la-or!"},{"en": "Take care of your health.","kh": "ថែរក្សាសុខភាពផង","ro": "thae-rak-saa sok-kha-<b>phiep</b> phong"},{"en": "We will miss you.","kh": "យើងនឹងនឹករលឹកអ្នក","ro": "yeung neung <b>neuk</b> ro-leuk neak"},{"en": "Thank you for everything.","kh": "អរគុណសម្រាប់អ្វីៗទាំងអស់","ro": "or-kun som-rap a-vei-vei <b>teang</b>-oh"},{"en": "I’ll come back.","kh": "ខ្ញុំនឹងត្រឡប់មកវិញ","ro": "khnyom neung tro-<b>lop</b> mok vinh"},{"en": "May you be happy and well.","kh": "សូមឲ្យមានសុខភាពល្អ","ro": "som aoy mien sok-kha-<b>phiep</b> la-or"}],"tips": [{"label": "Goodbyes Take an Hour","html": "Leaving a Cambodian gathering is not a single act but a slow circuit: you announce your departure, are pressed to stay, eat a little more, announce it again, and are walked all the way to your motorbike. Allow for it — leaving abruptly is the one discourtesy. And when you do finally go, the blessing you give matters more than the farewell itself. <span class=\"ro\">Som aoy mien sok-kha-phiep la-or</span> — may you have good health — is never the wrong thing to say.","culture": true}],"goal": "The last page. Leaving well matters as much as arriving well — and takes longer than you expect.","ch": 9}]};
